/* ---------- Mexique régional, Amérique centrale et Caraïbes ---------- */
const D49 = [
{ id:'caldo-de-piedra', c:'na', lat:17.400, lon:-96.300, base:4, prep:30, cook:10, diff:2, tags:['sea','soup','festive'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#f0a878','#c9402c','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Caldo de piedra',en:'Caldo de piedra'},
  p:{fr:'San Felipe Usila, Oaxaca, Mexique',en:'San Felipe Usila, Oaxaca, Mexico'},
  d:{fr:"Une soupe de poisson cuite en quelques secondes par une pierre de rivière chauffée à blanc, plongée dans une calebasse. Chez les Chinantèques, seuls les hommes la préparent, et le geste est aussi ancien que le village.",
     en:"A fish soup cooked in seconds by a white-hot river stone plunged into a gourd. Among the Chinantec only men prepare it, and the gesture is as old as the village."},
  i:[['river_prawns',400,'g'],['tilapia',600,'g'],['ripe_tomato',400,'g'],['onion',1,'pc'],['cilantro',1,'bunch'],['epazote',1,'bunch'],['serrano_pepper',3,'pc'],['garlic',4,'clove'],['lime',3,'pc'],['corn_tortillas',12,'pc'],['salt',null,'']],
  s:{fr:["Faites chauffer des pierres de rivière lisses dans un feu de bois pendant deux heures, jusqu'à ce qu'elles rougissent.","Taillez le poisson en gros morceaux et décortiquez les crevettes ; ne les cuisez surtout pas d'avance.","Répartissez dans chaque calebasse le poisson cru, les crevettes, la tomate, l'oignon, l'ail, le piment et les herbes.","Versez de l'eau froide salée jusqu'à couvrir, puis plongez-y une pierre brûlante avec des pinces de bois.","L'eau explose en ébullition et cuit tout en trente secondes. Retirez la pierre et servez immédiatement avec du citron vert."],
     en:["Heat smooth river stones in a wood fire for two hours, until they glow red.","Cut the fish into large pieces and peel the prawns; on no account cook them in advance.","Divide between gourds the raw fish, prawns, tomato, onion, garlic, chilli and herbs.","Pour in cold salted water to cover, then lower in a scorching stone with wooden tongs.","The water erupts into a boil and cooks everything in thirty seconds. Lift out the stone and serve at once with lime."]} },

{ id:'tlayuda', c:'na', lat:17.073, lon:-96.727, base:4, prep:30, cook:15, diff:2, tags:['street','grill','cheese'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8dcb8','#4f6f3a','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tlayuda',en:'Tlayuda'},
  p:{fr:'Ocotlán, Oaxaca, Mexique',en:'Ocotlán, Oaxaca, Mexico'},
  d:{fr:"Une grande tortilla séchée, grillée jusqu'à craquer, tartinée de saindoux noir de haricot et couverte de quesillo. On la plie en deux sur la braise : mangée à plat, c'est une tlayuda ; pliée, une clayuda de nuit.",
     en:"A large dried tortilla, grilled until it cracks, spread with black bean lard and covered in quesillo. It is folded in two over the coals: eaten flat it is a tlayuda; folded, a late-night clayuda."},
  i:[['large_tortillas',4,'pc'],['black_beans',300,'g'],['lard',100,'g'],['quesillo',300,'g'],['cecina',400,'g'],['chorizo',200,'g'],['cabbage',200,'g'],['avocado',2,'pc'],['ripe_tomato',300,'g'],['pasilla_chili',3,'pc'],['onion',1,'pc'],['lime',3,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire les haricots noirs avec de l'épazote, puis écrasez-les et faites-les réduire dans le saindoux jusqu'à obtenir une pâte noire et épaisse, l'asiento.","Faites griller la cecina et le chorizo sur la braise et découpez-les en morceaux.","Posez la grande tortilla sur la grille et tartinez-la d'asiento pendant qu'elle chauffe.","Ajoutez le quesillo effiloché et laissez-le fondre : la tortilla doit croustiller sans brûler, comptez 4 minutes.","Couronnez de chou finement émincé, de viande, de tomate, d'avocat et d'une salsa de piment pasilla. Pliez en deux et mangez à la main."],
     en:["Cook the black beans with epazote, then mash them and reduce them in the lard into a thick black paste, the asiento.","Grill the cecina and chorizo over the coals and cut them into pieces.","Lay the large tortilla on the grill and spread it with asiento as it heats.","Add the shredded quesillo and let it melt: the tortilla should crisp without burning, about 4 minutes.","Crown with finely shredded cabbage, meat, tomato, avocado and a pasilla chilli salsa. Fold in two and eat by hand."]} },

{ id:'papadzules', c:'na', lat:20.967, lon:-89.624, base:4, prep:40, cook:25, diff:2, tags:['veg','comfort','fresh'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'flat',food:['#7fae5a','#4f8f4a','#e0913a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Papadzules',en:'Papadzules'},
  p:{fr:'Mérida, Yucatán, Mexique',en:'Mérida, Yucatán, Mexico'},
  d:{fr:"Des tortillas roulées autour d'œuf dur, nappées d'une sauce verte de graines de courge et d'une huile de pépita séparée. Le nom maya signifierait « nourriture des seigneurs » ; le plat est antérieur à la conquête.",
     en:"Tortillas rolled around hard-boiled egg, cloaked in a green pumpkin-seed sauce with its separated pepita oil. The Maya name is said to mean 'food of the lords'; the dish predates the conquest."},
  i:[['pumpkin_seeds',300,'g'],['corn_tortillas',12,'pc'],['egg',8,'pc'],['epazote',1,'bunch'],['ripe_tomato',500,'g'],['onion',2,'pc'],['habanero',2,'pc'],['garlic',4,'clove'],['peanut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Faites griller les graines de courge à sec sans les laisser brunir, puis moulez-les très finement.","Faites infuser l'épazote dans un demi-litre d'eau chaude salée, et filtrez.","Travaillez la poudre de courge avec cette eau tiède en pétrissant à la main : l'huile verte se sépare et remonte. Recueillez-la à la cuillère.","Faites une sauce tomate avec l'oignon, l'ail et le habanero entier, et passez-la au tamis.","Trempez chaque tortilla dans la pâte de courge, roulez-la sur l'œuf dur haché, nappez de sauce tomate et arrosez de l'huile verte recueillie."],
     en:["Toast the pumpkin seeds dry without letting them brown, then grind them very finely.","Infuse the epazote in half a litre of hot salted water, and strain.","Work the seed powder with this warm water, kneading by hand: the green oil separates and rises. Spoon it off.","Make a tomato sauce with the onion, garlic and whole habanero, and pass it through a sieve.","Dip each tortilla in the seed paste, roll it around chopped hard-boiled egg, cloak with tomato sauce and drizzle over the reserved green oil."]} },

{ id:'chiles-en-nogada', c:'na', lat:19.043, lon:-98.198, base:6, prep:120, cook:40, diff:3, tags:['festive','fresh','pork'],
  art:{v:'plate',bg:'#28331f',plate:'#f4f0e6',style:'stew',food:['#f4f0e6','#4f8f4a','#8f1a3a','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Chiles en nogada',en:'Chiles en nogada'},
  p:{fr:'Puebla, Mexique',en:'Puebla, Mexico'},
  d:{fr:"Un piment poblano farci de viande et de fruits, nappé d'une crème de noix fraîches et parsemé de grenade. Vert, blanc, rouge : les couleurs du drapeau. On ne le sert qu'en août et septembre, quand la noix de Castille est laiteuse.",
     en:"A poblano chilli stuffed with meat and fruit, cloaked in a fresh walnut cream and scattered with pomegranate. Green, white, red: the colours of the flag. It is served only in August and September, when the walnut is milky."},
  i:[['poblano_pepper',6,'pc'],['ground_pork',400,'g'],['ground_beef',300,'g'],['onion',2,'pc'],['garlic',6,'clove'],['ripe_tomato',400,'g'],['apple',2,'pc'],['pear',2,'pc'],['peach',2,'pc'],['plantain',1,'pc'],['raisins',80,'g'],['almonds',80,'g'],['fresh_walnuts',300,'g'],['queso_fresco',150,'g'],['sour_cream',300,'ml'],['sherry',50,'ml'],['pomegranate',1,'pc'],['parsley',1,'bunch'],['cinnamon',1,'tsp'],['salt',null,'']],
  s:{fr:["Grillez les poblanos à la flamme jusqu'à ce que la peau cloque, enfermez-les 10 minutes dans un sac, puis pelez-les et videz-les par une fente.","Faites le picadillo : revenez oignon et ail, ajoutez les viandes, la tomate, puis les fruits en dés, les raisins, les amandes et la cannelle. Laissez confire 30 minutes.","Épluchez les noix fraîches une à une en retirant la fine peau amère : c'est long, et c'est indispensable.","Mixez-les avec le fromage frais, la crème et le xérès, sans sucrer : la nogada doit rester d'un blanc franc.","Farcissez les piments, nappez de nogada froide et parsemez de grains de grenade et de persil. Ne réchauffez jamais."],
     en:["Char the poblanos over a flame until the skin blisters, close them in a bag for 10 minutes, then peel and empty them through a slit.","Make the picadillo: fry onion and garlic, add the meats, the tomato, then the diced fruit, raisins, almonds and cinnamon. Cook down for 30 minutes.","Peel the fresh walnuts one by one, removing the thin bitter skin: it is slow, and it is essential.","Blend them with the fresh cheese, cream and sherry, without sugar: the nogada must stay a frank white.","Stuff the chillies, cloak them in cold nogada and scatter pomegranate seeds and parsley. Never reheat."]} },

{ id:'birria-de-res', c:'na', lat:20.674, lon:-103.344, base:8, prep:45, cook:210, diff:2, tags:['beef','slow','street'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#c9402c','#8f3b2a','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Birria de res',en:'Birria de res'},
  p:{fr:'Guadalajara, Jalisco, Mexique',en:'Guadalajara, Jalisco, Mexico'},
  d:{fr:"Un ragoût de bœuf aux piments guajillo et à la cannelle, dont le bouillon rouge sert à tremper les tacos. Le mot birria voulait dire « chose sans valeur » : les colons méprisaient la chèvre, les Mexicains en ont fait un chef-d'œuvre.",
     en:"A beef stew with guajillo chillies and cinnamon, whose red broth is used to dip the tacos. Birria once meant 'worthless thing': the colonists scorned goat, and Mexicans made a masterpiece of it."},
  i:[['beef_shank',1.5,'kg'],['beef_short_ribs',1,'kg'],['guajillo_chili',10,'pc'],['ancho_chili',4,'pc'],['chipotle',2,'pc'],['ripe_tomato',400,'g'],['onion',2,'pc'],['garlic',12,'clove'],['cinnamon',1,'pc'],['cloves',5,'pc'],['cumin',1,'tbsp'],['oregano',1,'tbsp'],['bay_leaf',3,'pc'],['white_wine_vinegar',80,'ml'],['corn_tortillas',24,'pc'],['cilantro',1,'bunch'],['lime',4,'pc'],['salt',null,'']],
  s:{fr:["Faites griller les piments à sec 30 secondes par face — pas davantage, ils deviendraient amers — et faites-les tremper 30 minutes.","Mixez-les avec la tomate, l'ail, les épices et le vinaigre en une sauce lisse, et passez-la au tamis.","Frottez-en la viande et laissez mariner 6 heures.","Faites cuire 3 heures à couvert avec de l'eau à mi-hauteur et le laurier, jusqu'à ce que la viande se défasse.","Effilochez la viande, dégraissez le bouillon en gardant l'huile rouge du dessus : c'est elle qui sert à frire les tortillas garnies avant de les tremper dans le consommé."],
     en:["Toast the chillies dry for 30 seconds a side — no more, or they turn bitter — and soak them for 30 minutes.","Blend them with the tomato, garlic, spices and vinegar into a smooth sauce, and pass it through a sieve.","Rub it over the meat and marinate for 6 hours.","Cook for 3 hours covered, with water halfway up and the bay, until the meat falls apart.","Shred the meat and skim the broth, keeping the red oil from the top: it is what the filled tortillas are fried in before being dipped in the consommé."]} },

{ id:'machaca-con-huevo', c:'na', lat:25.686, lon:-100.316, base:4, prep:20, cook:15, diff:1, tags:['beef','breakfast','fast'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'grill',food:['#e8c46a','#8f5a3a','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Machaca con huevo',en:'Machaca con huevo'},
  p:{fr:'Monterrey, Nuevo León, Mexique',en:'Monterrey, Nuevo León, Mexico'},
  d:{fr:"Du bœuf séché au soleil, pilé jusqu'à devenir cotonneux, sauté avec des œufs et un pico de gallo. Machacar veut dire « écraser » : dans le désert du Nord, on battait la viande séchée à la pierre pour l'attendrir.",
     en:"Sun-dried beef pounded until fluffy, fried with eggs and a pico de gallo. Machacar means 'to pound': in the northern desert the dried meat was beaten with a stone to tenderise it."},
  i:[['dried_beef',250,'g'],['egg',8,'pc'],['ripe_tomato',300,'g'],['onion',1,'pc'],['serrano_pepper',3,'pc'],['garlic',3,'clove'],['flour_tortillas',12,'pc'],['peanut_oil',60,'ml'],['cilantro',1,'bunch'],['lime',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper la viande séchée 15 minutes à l'eau tiède, essorez-la, puis pilez-la au mortier jusqu'à ce qu'elle se défasse en filaments.","Faites-la revenir à sec dans une poêle très chaude pour la réhydrater et concentrer son goût.","Ajoutez l'huile, l'oignon, l'ail et le piment serrano, et faites-les fondre 4 minutes.","Ajoutez la tomate concassée et laissez évaporer complètement : de l'humidité rendrait les œufs baveux.","Versez les œufs battus et brouillez-les à feu doux, en les laissant à peine prendre. Servez dans des tortillas de blé."],
     en:["Soak the dried beef in warm water for 15 minutes, squeeze it dry, then pound it in a mortar until it falls into strands.","Toast it dry in a very hot pan to rehydrate it and concentrate its flavour.","Add the oil, onion, garlic and serrano chilli, and soften for 4 minutes.","Add the crushed tomato and let it evaporate completely: moisture would make the eggs runny.","Pour in the beaten eggs and scramble over low heat, barely setting them. Serve in flour tortillas."]} },

{ id:'kak-ik', c:'na', lat:15.472, lon:-90.371, base:6, prep:40, cook:90, diff:2, tags:['poultry','soup','festive'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'soup',food:['#c9402c','#8f3b2a','#e0913a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kak’ik',en:'Kak’ik'},
  p:{fr:'Cobán, Alta Verapaz, Guatemala',en:'Cobán, Alta Verapaz, Guatemala'},
  d:{fr:"Une soupe de dinde rouge vif des Q'eqchi', au piment cobanero et à l'annatto. Le nom vient de kak, rouge, et ik, piment ; c'est un plat de cérémonie maya déclaré patrimoine national guatémaltèque.",
     en:"A vivid red Q'eqchi' turkey soup with cobanero chilli and annatto. The name comes from kak, red, and ik, chilli; a Maya ceremonial dish declared Guatemalan national heritage."},
  i:[['turkey',2,'kg'],['guajillo_chili',6,'pc'],['chile_cobanero',4,'pc'],['ripe_tomato',600,'g'],['tomatillo',300,'g'],['achiote_paste',2,'tbsp'],['onion',2,'pc'],['garlic',10,'clove'],['cilantro',2,'bunch'],['mint',1,'bunch'],['spring_onion',5,'pc'],['corn_tortillas',12,'pc'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites cuire la dinde en morceaux 1 heure dans trois litres d'eau avec l'oignon et l'ail ; gardez le bouillon.","Faites griller à sec les piments, les tomates et les tomatilles sur une plaque, jusqu'à ce qu'ils noircissent par plaques.","Mixez-les avec l'urucum et une louche de bouillon, puis passez au tamis fin.","Faites cuire cette purée 20 minutes à feu doux, en remuant, puis versez-la dans le bouillon.","Remettez la dinde, ajoutez la coriandre et la menthe dix minutes avant la fin, et servez avec des tamalitos ou du riz."],
     en:["Cook the jointed turkey for 1 hour in three litres of water with the onion and garlic; keep the broth.","Char the chillies, tomatoes and tomatillos dry on a griddle, until they blacken in patches.","Blend them with the annatto and a ladle of broth, then pass through a fine sieve.","Cook this purée for 20 minutes over low heat, stirring, then stir it into the broth.","Return the turkey, add the coriander and mint ten minutes before the end, and serve with tamalitos or rice."]} },

{ id:'sopa-de-caracol', c:'na', lat:15.783, lon:-86.783, base:6, prep:30, cook:60, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4ecd8',style:'soup',food:['#f4f0e6','#e8c46a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Sopa de caracol',en:'Sopa de caracol'},
  p:{fr:'La Ceiba, côte garifuna, Honduras',en:'La Ceiba, Garifuna coast, Honduras'},
  d:{fr:"Une soupe garifuna de lambi au lait de coco, au manioc et au plantain vert. Elle a fait le tour du monde en 1991 grâce à une chanson de Banda Blanca, et l'on en connaît le refrain sans connaître le plat.",
     en:"A Garifuna conch soup with coconut milk, cassava and green plantain. It travelled the world in 1991 on a Banda Blanca song, and many know the chorus without knowing the dish."},
  i:[['conch',800,'g'],['coconut_milk',800,'ml'],['cassava',500,'g'],['green_plantain',3,'pc'],['carrot',2,'pc'],['onion',2,'pc'],['garlic',8,'clove'],['cilantro',2,'bunch'],['achiote_paste',1,'tbsp'],['cumin',1,'tsp'],['lime',3,'pc'],['scotch_bonnet',1,'pc'],['peanut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Battez le lambi au maillet jusqu'à l'attendrir, puis taillez-le en lanières et frottez-le au citron vert.","Faites revenir oignon, ail et urucum à l'huile, ajoutez le cumin.","Mouillez d'un litre d'eau et ajoutez le manioc, le plantain vert cassé à la main et la carotte.","Laissez cuire 30 minutes, puis versez le lait de coco et laissez frémir sans bouillir.","Ajoutez le lambi pour 8 minutes seulement : trop cuit, il devient caoutchouc. Coriandre et citron vert hors du feu."],
     en:["Beat the conch with a mallet to tenderise it, then cut it into strips and rub it with lime.","Fry the onion, garlic and annatto in the oil, and add the cumin.","Add a litre of water with the cassava, the green plantain broken by hand and the carrot.","Cook for 30 minutes, then pour in the coconut milk and let it steam without boiling.","Add the conch for 8 minutes only: overcooked it turns to rubber. Coriander and lime off the heat."]} },

{ id:'olla-de-carne', c:'na', lat:9.935, lon:-84.088, base:8, prep:35, cook:180, diff:1, tags:['beef','soup','sunday'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'soup',food:['#e0913a','#8f5a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Olla de carne',en:'Olla de carne'},
  p:{fr:'Cartago, Costa Rica',en:'Cartago, Costa Rica'},
  d:{fr:"Un pot-au-feu costaricien où entrent sept racines différentes, cuit trois heures le dimanche. Le bouillon se boit d'abord dans une tasse, avant que la viande et les légumes ne passent à table.",
     en:"A Costa Rican boiled dinner with seven different roots, cooked for three hours on Sundays. The broth is drunk first from a cup, before the meat and vegetables come to the table."},
  i:[['beef_shank',1.5,'kg'],['cassava',500,'g'],['yautia',400,'g'],['sweet_potato',400,'g'],['pumpkin',500,'g'],['green_plantain',3,'pc'],['corn_cobs',3,'pc'],['chayote',2,'pc'],['carrot',3,'pc'],['onion',2,'pc'],['spring_onion',5,'pc'],['cilantro',1,'bunch'],['garlic',8,'clove'],['long_grain_rice',500,'g'],['lime',3,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire le jarret avec l'os 2 heures dans quatre litres d'eau, avec l'oignon et l'ail, en écumant régulièrement.","Le collagène de l'os est indispensable : sans lui, le bouillon reste maigre et plat.","Ajoutez les racines par ordre de fermeté — manioc, yautía, patate douce — à vingt minutes d'intervalle.","Terminez par la courge, le chayotte, le maïs et le plantain, qui cuisent en 20 minutes.","Servez le bouillon en tasse d'abord, puis viande et légumes dans une assiette creuse, avec du riz et du citron vert."],
     en:["Cook the shank on the bone for 2 hours in four litres of water, with the onion and garlic, skimming regularly.","The collagen from the bone is essential: without it the broth stays thin and flat.","Add the roots in order of firmness — cassava, yautía, sweet potato — at twenty-minute intervals.","Finish with the squash, chayote, corn and plantain, which need 20 minutes.","Serve the broth in a cup first, then meat and vegetables in a deep plate, with rice and lime."]} },

{ id:'tamal-en-cazuela', c:'na', lat:23.135, lon:-82.359, base:8, prep:40, cook:90, diff:2, tags:['pork','comfort','slow'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#e8c46a','#e0b45a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Tamal en cazuela',en:'Tamal en cazuela'},
  p:{fr:'La Havane, Cuba',en:'Havana, Cuba'},
  d:{fr:"Le tamal cubain défait de sa feuille : le maïs frais et le porc cuits ensemble dans une marmite, comme une polenta. On l'a inventé par paresse assumée, et personne à La Havane ne s'en excuse.",
     en:"The Cuban tamal freed from its husk: fresh corn and pork cooked together in a pot, like polenta. It was invented out of frank laziness, and nobody in Havana apologises for it."},
  i:[['corn_kernels',1.2,'kg'],['corn_flour',200,'g'],['pork_shoulder',700,'g'],['smoked_bacon',150,'g'],['onion',3,'pc'],['green_pepper',2,'pc'],['garlic',10,'clove'],['ripe_tomato',400,'g'],['cumin',1,'tbsp'],['oregano',1,'tbsp'],['sour_orange_juice',150,'ml'],['achiote_paste',1,'tbsp'],['olive_oil',120,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le porc en dés 2 heures dans l'orange amère, l'ail, le cumin et l'origan.","Faites fondre le lard, saisissez le porc, puis retirez-le et faites le sofrito : oignon, poivron, ail, tomate, 20 minutes.","Râpez le maïs frais et mixez-le avec la farine de maïs et un litre d'eau ; passez au tamis pour ôter les fibres.","Versez cette crème dans le sofrito et cuisez 45 minutes à feu doux, en remuant sans arrêt à la cuillère de bois.","Remettez le porc pour les 20 dernières minutes. La cazuela est prête quand la cuillère tient debout au milieu."],
     en:["Marinate the diced pork for 2 hours in sour orange, garlic, cumin and oregano.","Render the bacon, sear the pork, then lift it out and make the sofrito: onion, pepper, garlic, tomato, 20 minutes.","Grate the fresh corn and blend it with the maize flour and a litre of water; sieve to remove the fibres.","Pour this cream into the sofrito and cook for 45 minutes over low heat, stirring constantly with a wooden spoon.","Return the pork for the last 20 minutes. The cazuela is ready when the spoon stands up in the middle."]} },

{ id:'arroz-con-gandules', c:'na', lat:18.201, lon:-66.664, base:8, prep:35, cook:50, diff:2, tags:['rice','legume','festive'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'rice',food:['#e0913a','#4f6f3a','#8f5a3a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Arroz con gandules',en:'Arroz con gandules'},
  p:{fr:'Bayamón, Porto Rico',en:'Bayamón, Puerto Rico'},
  d:{fr:"Le riz national portoricain, aux pois d'Angole et au sofrito, dont on recherche le fond caramélisé, le pegao. Servir un riz sans pegao passe pour un aveu de maladresse : on le racle et on se le dispute.",
     en:"Puerto Rico's national rice, with pigeon peas and sofrito, prized for its caramelised bottom crust, the pegao. Serving rice with no pegao is taken as an admission of clumsiness: it is scraped up and fought over."},
  i:[['long_grain_rice',600,'g'],['pigeon_peas',500,'g'],['sofrito',150,'g'],['salt_pork',150,'g'],['smoked_ham',150,'g'],['achiote_paste',2,'tbsp'],['tomato_sauce',200,'ml'],['olives',80,'g'],['capers',2,'tbsp'],['oregano',1,'tbsp'],['cumin',1,'tsp'],['bay_leaf',2,'pc'],['olive_oil',100,'ml'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites fondre le lard salé et le jambon fumé dans un caldero de fonte, jusqu'à ce qu'ils croustillent.","Ajoutez le sofrito et l'urucum, et laissez revenir 5 minutes : la graisse doit devenir orange.","Ajoutez la sauce tomate, les olives, les câpres et les épices, puis les pois d'Angole égouttés.","Versez le riz et de l'eau à un centimètre au-dessus, sans jamais remuer après ce moment.","Laissez évaporer à découvert, puis couvrez 20 minutes à feu très doux. Montez le feu 2 minutes à la fin pour former le pegao."],
     en:["Render the salt pork and smoked ham in a cast-iron caldero, until they crisp.","Add the sofrito and annatto, and fry for 5 minutes: the fat should turn orange.","Add the tomato sauce, olives, capers and spices, then the drained pigeon peas.","Pour in the rice and water to one centimetre above it, and never stir after that moment.","Let it evaporate uncovered, then cover for 20 minutes over very low heat. Raise the heat for 2 minutes at the end to form the pegao."]} },

{ id:'soup-joumou', c:'na', lat:18.539, lon:-72.336, base:8, prep:45, cook:120, diff:2, tags:['soup','beef','festive'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'soup',food:['#e0913a','#e8c46a','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Soup joumou',en:'Soup joumou'},
  p:{fr:'Port-au-Prince, Haïti',en:'Port-au-Prince, Haiti'},
  d:{fr:"Une soupe de giraumon et de bœuf que l'on boit chaque 1er janvier. Sous la colonie, elle était interdite aux esclaves ; l'indépendance de 1804 en a fait le symbole de la liberté reconquise, et l'UNESCO l'a inscrite en 2021.",
     en:"A pumpkin and beef soup drunk every 1 January. Under the colony it was forbidden to the enslaved; independence in 1804 made it the symbol of freedom regained, and UNESCO listed it in 2021."},
  i:[['pumpkin',1.5,'kg'],['beef_chuck',800,'g'],['vermicelli',200,'g'],['potato',500,'g'],['carrot',3,'pc'],['cabbage',300,'g'],['turnip',2,'pc'],['celery',3,'stalk'],['epis',5,'tbsp'],['lime',4,'pc'],['scotch_bonnet',1,'pc'],['cloves',5,'pc'],['thyme',4,'sprig'],['peanut_oil',60,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Lavez la viande au citron vert, comme le veut l'usage, puis faites-la mariner 4 heures dans l'épis.","Faites-la cuire 1 heure avec le thym, les clous et le piment entier ; gardez le bouillon.","Faites bouillir le giraumon en morceaux jusqu'à ce qu'il se défasse, puis mixez-le avec son eau en une crème lisse.","Réunissez la purée et le bouillon, ajoutez les légumes par ordre de fermeté et laissez 30 minutes.","Ajoutez les vermicelles pour les huit dernières minutes. La soupe doit napper la cuillère sans être épaisse."],
     en:["Wash the meat with lime, as custom requires, then marinate it for 4 hours in epis.","Cook it for 1 hour with the thyme, cloves and whole chilli; keep the broth.","Boil the pumpkin in pieces until it collapses, then blend it with its water into a smooth cream.","Combine the purée and the broth, add the vegetables in order of firmness and give them 30 minutes.","Add the vermicelli for the last eight minutes. The soup should coat the spoon without being thick."]} },

{ id:'sancocho-dominicano', c:'na', lat:18.486, lon:-69.931, base:10, prep:45, cook:150, diff:2, tags:['soup','sunday','beef'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'soup',food:['#e0913a','#e8c46a','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Sancocho de siete carnes',en:'Sancocho de siete carnes'},
  p:{fr:'Saint-Domingue, République dominicaine',en:'Santo Domingo, Dominican Republic'},
  d:{fr:"Une soupe épaisse de sept viandes et de sept tubercules, servie aux grandes occasions. Chaque viande entre à son heure ; le cuisinier qui les met toutes ensemble se fait montrer la porte.",
     en:"A thick soup of seven meats and seven root vegetables, served on great occasions. Each meat goes in at its own moment; a cook who adds them all at once is shown the door."},
  i:[['beef_chuck',400,'g'],['pork_ribs',400,'g'],['chicken',500,'g'],['goat_meat',400,'g'],['smoked_sausage',200,'g'],['pork_belly',300,'g'],['cassava',500,'g'],['yautia',400,'g'],['yam',400,'g'],['green_plantain',3,'pc'],['pumpkin',400,'g'],['corn_cobs',3,'pc'],['cilantro',2,'bunch'],['garlic',12,'clove'],['oregano',1,'tbsp'],['sour_orange_juice',150,'ml'],['long_grain_rice',600,'g'],['avocado',3,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner chaque viande séparément à l'orange amère, l'ail et l'origan pendant 2 heures.","Saisissez-les l'une après l'autre dans la marmite, en commençant par la chèvre et le bœuf, les plus longs à cuire.","Mouillez de cinq litres d'eau et laissez mijoter 1 heure avant d'ajouter porc, poulet et saucisse.","Ajoutez les tubercules par ordre de fermeté : ñame, yautía, manioc, puis plantain et courge.","Écrasez un peu de courge et de plantain contre la paroi pour lier la soupe. Servez avec riz blanc et avocat."],
     en:["Marinate each meat separately in sour orange, garlic and oregano for 2 hours.","Sear them one after another in the pot, starting with the goat and beef, which take longest.","Add five litres of water and simmer for 1 hour before adding pork, chicken and sausage.","Add the roots in order of firmness: yam, yautía, cassava, then plantain and squash.","Crush a little squash and plantain against the side to thicken the soup. Serve with white rice and avocado."]} },

{ id:'pelau', c:'na', lat:10.667, lon:-61.518, base:6, prep:30, cook:70, diff:2, tags:['rice','poultry','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#8f5a3a','#6f4a2a','#e0913a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pelau',en:'Pelau'},
  p:{fr:'Port-d’Espagne, Trinité-et-Tobago',en:'Port of Spain, Trinidad and Tobago'},
  d:{fr:"Du poulet caramélisé dans du sucre brûlé, puis cuit avec du riz, des pois d'Angole et du lait de coco. Le sucre doit noircir et fumer avant que la viande n'entre : c'est le geste qui définit tout le plat.",
     en:"Chicken caramelised in burnt sugar, then cooked with rice, pigeon peas and coconut milk. The sugar must blacken and smoke before the meat goes in: the gesture that defines the whole dish."},
  i:[['chicken',1.4,'kg'],['long_grain_rice',500,'g'],['pigeon_peas',400,'g'],['coconut_milk',500,'ml'],['brown_sugar',4,'tbsp'],['green_seasoning',5,'tbsp'],['onion',2,'pc'],['carrot',2,'pc'],['pumpkin',300,'g'],['scotch_bonnet',1,'pc'],['ketchup',3,'tbsp'],['thyme',4,'sprig'],['peanut_oil',80,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner le poulet 4 heures dans le green seasoning, ce hachis d'herbes et d'ail trinidadien.","Chauffez l'huile et le sucre roux dans une marmite épaisse, sans remuer, jusqu'à ce que le caramel fume et noircisse.","Jetez le poulet dedans immédiatement et remuez pour l'enrober : il doit prendre une couleur d'acajou.","Ajoutez oignon, carotte, courge, pois d'Angole, thym et ketchup, puis le riz rincé.","Versez le lait de coco et de l'eau à un centimètre au-dessus du riz, posez le piment entier, couvrez et cuisez 25 minutes."],
     en:["Marinate the chicken for 4 hours in green seasoning, the Trinidadian herb and garlic paste.","Heat the oil and brown sugar in a heavy pot, without stirring, until the caramel smokes and blackens.","Drop the chicken in at once and stir to coat: it should take on a mahogany colour.","Add onion, carrot, squash, pigeon peas, thyme and ketchup, then the rinsed rice.","Pour in the coconut milk and water to one centimetre above the rice, set the whole chilli on top, cover and cook for 25 minutes."]} }
,

{ id:'bokit', c:'na', lat:15.866, lon:-61.583, base:4, prep:90, cook:20, diff:2, tags:['street','fry','fast'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'roll',food:['#e8c46a','#f2dfa8','#8f4a3a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Bokit',en:'Bokit'},
  p:{fr:'Terre-de-Haut, Les Saintes, Guadeloupe',en:'Terre-de-Haut, Les Saintes, Guadeloupe'},
  d:{fr:"Un pain plat frit et gonflé, fendu et garni comme un sandwich. Il descend du johnny cake nord-américain arrivé par les Antilles anglophones ; le nom serait une déformation de « bake it », et il se vend aujourd'hui dans des camionnettes le long des routes.",
     en:"A flatbread fried until it puffs, split and filled like a sandwich. It descends from the North American johnny cake by way of the English-speaking Caribbean; the name is said to come from bake it, and it is now sold from vans along the roads."},
  i:[['flour',500,'g'],['baking_powder',15,'g'],['water',280,'ml'],['frying_oil',1,'l'],['salt_cod',300,'g'],['onion',2,'pc'],['tomato',2,'pc'],['lettuce',6,'pc'],['lime',2,'pc'],['scotch_bonnet',1,'pc'],['garlic',4,'clove'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la levure chimique, le sel et l'eau cinq minutes seulement : trop pétrie, la pâte devient élastique et ne gonfle plus.","Laissez-la reposer une heure sous un linge humide, le temps que le gluten se détende.","Abaissez des disques de 15 cm et 5 mm d'épaisseur, réguliers : une épaisseur inégale donne un pain qui gonfle d'un seul côté.","Plongez dans une huile à 180 °C ; le disque doit remonter et se gonfler en quelques secondes, arrosez-le à la louche.","Égouttez, fendez en deux dans l'épaisseur et garnissez de morue effilochée, de crudités et de piment."],
     en:["Knead the flour, baking powder, salt and water for five minutes only: overworked, the dough turns elastic and stops puffing.","Rest it an hour under a damp cloth, so the gluten relaxes.","Roll discs 15 cm across and 5 mm thick, evenly: uneven thickness gives a bread that puffs on one side only.","Slide into oil at 180°C; the disc should rise and balloon within seconds, spoon oil over it.","Drain, split it horizontally and fill with flaked salt cod, salad and chilli."]} },

{ id:'matoutou-de-crabes', c:'na', lat:14.446, lon:-60.874, base:6, prep:180, cook:60, diff:3, tags:['sea','festive','stew'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'rice',food:['#e07a6a','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Matoutou de crabes',en:'Matoutou de crabes'},
  p:{fr:'Sainte-Anne, Martinique',en:'Sainte-Anne, Martinique'},
  d:{fr:"Un riz aux crabes de terre, plat obligatoire du lundi de Pâques aux Antilles. Les crabes sont capturés vivants au Carême et engraissés plusieurs semaines au piment et à la noix de coco dans des cages, pour purger leur chair.",
     en:"Rice with land crabs, the obligatory Easter Monday dish in the French Antilles. The crabs are caught alive during Lent and fattened for several weeks on chilli and coconut in cages, to purge their flesh."},
  i:[['land_crab',8,'pc'],['long_grain_rice',500,'g'],['onion',3,'pc'],['scallion',1,'bunch'],['garlic',8,'clove'],['thyme',1,'bunch'],['parsley',1,'bunch'],['scotch_bonnet',2,'pc'],['lime',4,'pc'],['tomato',300,'g'],['olive_oil',80,'ml'],['clove',4,'pc'],['salt',null,'']],
  s:{fr:["Ébouillantez les crabes vivants une minute, puis brossez-les longuement sous l'eau et retirez les branchies et la poche à sable.","Cassez les pinces d'un coup de dos de couteau pour que le bouillon pénètre et que la chair se mange sans outil.","Faites-les mariner deux heures au citron vert, à l'ail écrasé et au piment, dans un plat non métallique.","Faites revenir les aromates, ajoutez les crabes et laissez-les rendre leur eau vingt minutes à couvert.","Versez le riz sec dessus, mouillez d'une fois et demie son volume et cuisez 20 minutes sans remuer. Se mange à la main."],
     en:["Scald the live crabs for a minute, then scrub them at length under water and remove the gills and sand sac.","Crack the claws with the back of a knife so the broth penetrates and the meat can be eaten without tools.","Marinate them two hours in lime, crushed garlic and chilli, in a non-metallic dish.","Fry the aromatics, add the crabs and let them give up their water for twenty minutes, covered.","Tip the dry rice over them, moisten with one and a half times its volume and cook 20 minutes without stirring. Eaten with the hands."]} },

{ id:'tourment-damour', c:'na', lat:15.870, lon:-61.590, base:8, prep:60, cook:35, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#c9754a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Tourment d\'amour',en:'Tourment d\'amour'},
  p:{fr:'Les Saintes, Guadeloupe',en:'Les Saintes, Guadeloupe'},
  d:{fr:"Une petite tartelette à la confiture de coco recouverte de génoise. Les femmes des Saintes les préparaient pour l'arrivée des pêcheurs partis plusieurs jours : le tourment, c'était l'attente, et le gâteau la récompense du retour.",
     en:"A small tartlet of coconut jam covered with sponge. The women of Les Saintes made them for the return of fishermen gone several days: the torment was the waiting, and the cake the reward for coming home."},
  i:[['flour',300,'g'],['butter',200,'g'],['coconut',300,'g'],['sugar',250,'g'],['egg',4,'pc'],['vanilla',1,'pc'],['rum',30,'ml'],['cinnamon',5,'g'],['salt',null,'']],
  s:{fr:["Sablez la farine et le beurre froid du bout des doigts, liez à l'eau glacée et laissez reposer une heure au froid.","Faites cuire la coco râpée avec le sucre, la vanille et un peu d'eau vingt minutes, jusqu'à ce que la confiture se détache du fond.","Parfumez-la au rhum hors du feu, jamais pendant la cuisson : l'alcool s'évaporerait et il ne resterait rien.","Foncez des moules à tartelettes, garnissez de confiture aux deux tiers seulement — elle gonfle et déborderait.","Couvrez d'une cuillerée de pâte à génoise et cuisez 30 minutes à 180 °C, jusqu'à ce que le dessus dore et bombe."],
     en:["Rub the flour and cold butter together with your fingertips, bind with iced water and rest an hour in the cold.","Cook the grated coconut with the sugar, vanilla and a little water for twenty minutes, until the jam pulls from the base.","Scent it with rum off the heat, never during cooking: the alcohol would flash off and leave nothing.","Line tartlet tins, fill only two-thirds with jam — it swells and would overflow.","Cover with a spoonful of sponge batter and bake 30 minutes at 180°C, until the top browns and domes."]} },

{ id:'sorbet-coco-guadeloupe', c:'na', lat:16.227, lon:-61.383, base:8, prep:40, cook:0, diff:2, tags:['sweet','street','fruit'],
  art:{v:'glass',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#f2dfa8'],garnish:'#6fbf8f'},
  n:{fr:'Sorbet coco',en:'Coconut sorbet'},
  p:{fr:'Sainte-Anne, Guadeloupe',en:'Sainte-Anne, Guadeloupe'},
  d:{fr:"Une glace au coco turbinée à la main dans une sorbetière de bois et de glace pilée. Les marchands la fabriquent devant vous sur la plage, en tournant la manivelle vingt minutes : la texture granuleuse qui en résulte est exactement le but recherché.",
     en:"Coconut ice churned by hand in a wooden bucket packed with crushed ice. Vendors make it in front of you on the beach, turning the crank for twenty minutes: the grainy texture that results is precisely the point."},
  i:[['coconut',400,'g'],['coconut_milk',500,'ml'],['whole_milk',300,'ml'],['sugar',250,'g'],['vanilla',1,'pc'],['cinnamon',5,'g'],['lime',1,'pc'],['coarse_salt',300,'g'],['ice',3,'kg']],
  s:{fr:["Faites infuser la vanille fendue et la cannelle dans le lait chaud une demi-heure, puis laissez refroidir complètement.","Mêlez au lait de coco, à la coco râpée et au sucre, et goûtez : le mélange doit paraître un peu trop sucré, le froid en atténue la perception d'un tiers.","Versez dans le seau intérieur et calez-le dans la glace pilée mêlée de gros sel.","Le sel abaisse le point de fusion de la glace jusqu'à -18 °C : sans lui, la glace fond à zéro et rien ne prend.","Tournez la manivelle sans interruption vingt minutes, en raclant les parois. Servez aussitôt, le sorbet ne se conserve pas."],
     en:["Infuse the split vanilla and cinnamon in hot milk for half an hour, then cool completely.","Mix with the coconut milk, grated coconut and sugar, and taste: it should seem slightly too sweet, cold dulls perception by a third.","Pour into the inner bucket and pack it in crushed ice mixed with coarse salt.","The salt lowers the melting point of the ice to -18°C: without it the ice melts at zero and nothing sets.","Turn the crank without pause for twenty minutes, scraping the sides. Serve at once, it does not keep."]} },

{ id:'dombres-aux-ouassous', c:'na', lat:15.996, lon:-61.732, base:6, prep:60, cook:40, diff:2, tags:['sea','comfort','stew'],
  art:{v:'bowl',bg:'#26485c',plate:'#f0e4c8',style:'stew',food:['#f4f0e6','#e07a6a','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Dombrés aux ouassous',en:'Dombrés with ouassous'},
  p:{fr:'Basse-Terre, Guadeloupe',en:'Basse-Terre, Guadeloupe'},
  d:{fr:"De petites boulettes de farine pochées dans une sauce aux écrevisses de rivière. Le ouassous tient son nom de « roi des sources » ; c'est une grosse crevette d'eau douce qui remonte les rivières de Basse-Terre et se pêche à la nasse.",
     en:"Small flour dumplings poached in a sauce of river crayfish. The ouassou takes its name from king of the springs; it is a large freshwater prawn that climbs the rivers of Basse-Terre and is caught in traps."},
  i:[['river_prawns',1,'kg'],['flour',400,'g'],['water',180,'ml'],['onion',2,'pc'],['garlic',6,'clove'],['scallion',1,'bunch'],['thyme',1,'bunch'],['tomato',300,'g'],['scotch_bonnet',1,'pc'],['lime',3,'pc'],['olive_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, le sel et l'eau jusqu'à obtenir une pâte ferme, puis laissez-la reposer trente minutes.","Roulez des boulettes de la taille d'une bille entre les paumes ; plus grosses, elles restent crues au cœur.","Faites revenir les aromates, ajoutez les ouassous décortiqués, la tomate et de l'eau, et portez à frémissement.","Jetez les dombrés dans le liquide frémissant, jamais bouillant : à gros bouillons ils se délitent et troublent la sauce.","Vingt minutes de cuisson, ils remontent en surface quand ils sont prêts. Rectifiez au citron vert et au piment."],
     en:["Knead the flour, salt and water to a firm dough, then rest it thirty minutes.","Roll marble-sized balls between your palms; any larger and they stay raw at the centre.","Fry the aromatics, add the shelled ouassous, tomato and water, and bring to a tremble.","Drop the dombrés into simmering liquid, never boiling: at a hard boil they disintegrate and cloud the sauce.","Twenty minutes' cooking, they rise to the surface when done. Adjust with lime and chilli."]} },

{ id:'bebele', c:'na', lat:15.930, lon:-61.270, base:8, prep:90, cook:180, diff:3, tags:['slow','stew','comfort'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e8c46a','#7fae5a','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Bébélé',en:'Bébélé'},
  p:{fr:'Marie-Galante, Guadeloupe',en:'Marie-Galante, Guadeloupe'},
  d:{fr:"Le plat emblématique de Marie-Galante : tripes, bananes vertes, fruit à pain et dombrés dans un même bouillon. Il se prépare pour les grandes occasions et mijote une matinée entière ; le nom viendrait d'un mot d'Afrique de l'Ouest désignant un mélange.",
     en:"The emblematic dish of Marie-Galante: tripe, green bananas, breadfruit and dumplings in one broth. It is made for great occasions and simmers a whole morning; the name is said to come from a West African word for a mixture."},
  i:[['beef_tripe',1,'kg'],['green_banana',6,'pc'],['breadfruit',1,'pc'],['flour',300,'g'],['pork_tail',400,'g'],['onion',3,'pc'],['garlic',10,'clove'],['scallion',1,'bunch'],['thyme',1,'bunch'],['scotch_bonnet',1,'pc'],['lime',4,'pc'],['clove',6,'pc'],['salt',null,'']],
  s:{fr:["Nettoyez les tripes au citron vert et au gros sel en les frottant, puis rincez-les et blanchissez-les vingt minutes.","Jetez cette première eau : elle emporte l'odeur forte, et la garder gâcherait tout le bouillon.","Faites cuire les tripes deux heures avec la queue de porc, l'ail, le thym et les clous de girofle.","Ajoutez les bananes vertes pelées et le fruit à pain en gros morceaux, et poursuivez quarante minutes.","Terminez par les dombrés roulés à la main, vingt minutes à frémissement. Le bouillon doit être épais et trouble."],
     en:["Clean the tripe with lime and coarse salt, rubbing, then rinse it and blanch it twenty minutes.","Throw away that first water: it carries off the strong smell, and keeping it would spoil the whole broth.","Cook the tripe two hours with the pork tail, garlic, thyme and cloves.","Add the peeled green bananas and breadfruit in large pieces, and continue forty minutes.","Finish with hand-rolled dumplings, twenty minutes at a tremble. The broth should be thick and cloudy."]} },

{ id:'gratin-de-christophine', c:'na', lat:16.132, lon:-61.766, base:6, prep:40, cook:45, diff:1, tags:['veg','bake','comfort'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e8c46a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Gratin de christophine',en:'Chayote gratin'},
  p:{fr:'Bouillante, Guadeloupe',en:'Bouillante, Guadeloupe'},
  d:{fr:"Un gratin de chayote à la béchamel, doux et légèrement sucré. La christophine est arrivée du Mexique avec les Espagnols ; son goût très neutre en fait un support parfait pour la béchamel, et c'est le gratin de tous les dimanches antillais.",
     en:"A chayote gratin with béchamel, mild and faintly sweet. The chayote came from Mexico with the Spanish; its very neutral flavour makes it a perfect vehicle for béchamel, and it is the Sunday gratin of the Antilles."},
  i:[['chayote',4,'pc'],['whole_milk',500,'ml'],['butter',80,'g'],['flour',60,'g'],['gruyere_cheese',150,'g'],['breadcrumbs',60,'g'],['onion',1,'pc'],['garlic',3,'clove'],['nutmeg',3,'g'],['parsley',1,'bunch'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Faites cuire les christophines entières à l'eau salée trente minutes, jusqu'à ce qu'un couteau les traverse sans résistance.","Coupez-les en deux, retirez le noyau plat central et creusez la chair sans percer la peau.","Égouttez cette chair dans une passoire un quart d'heure en pressant : la christophine est très aqueuse et détremperait le gratin.","Préparez une béchamel épaisse, muscadée, et mêlez-la à la chair écrasée et à l'oignon revenu.","Remplissez les demi-peaux, couvrez de gruyère et de chapelure et gratinez 25 minutes à 200 °C."],
     en:["Boil the chayotes whole in salted water for thirty minutes, until a knife passes through without resistance.","Halve them, remove the flat central stone and scoop out the flesh without piercing the skin.","Drain that flesh in a sieve for a quarter hour, pressing: chayote is very watery and would soak the gratin.","Make a thick béchamel, well nutmegged, and mix it with the crushed flesh and softened onion.","Fill the half shells, cover with gruyère and breadcrumbs and bake 25 minutes at 200°C."]} },

{ id:'feroce-davocat', c:'na', lat:16.241, lon:-61.533, base:6, prep:40, cook:0, diff:1, tags:['sea','fresh','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#7fae5a','#f4f0e6','#e8c46a','#e07a6a'],garnish:'#6fbf8f'},
  n:{fr:'Féroce d\'avocat',en:'Féroce d\'avocat'},
  p:{fr:'Pointe-à-Pitre, Guadeloupe',en:'Pointe-à-Pitre, Guadeloupe'},
  d:{fr:"Une purée d'avocat, de morue grillée et de farine de manioc, très relevée au piment. Le nom vient de là : féroce comme le piment, et la farine de manioc absorbe assez de gras pour qu'on en fasse des boulettes qui se mangent à la main.",
     en:"A purée of avocado, grilled salt cod and cassava flour, fiercely spiced. That is where the name comes from: fierce as the chilli, and the cassava flour absorbs enough fat that it can be rolled into balls and eaten with the hands."},
  i:[['salt_cod',400,'g'],['avocado',4,'pc'],['cassava_flour',200,'g'],['scotch_bonnet',2,'pc'],['lime',4,'pc'],['garlic',5,'clove'],['scallion',1,'bunch'],['olive_oil',80,'ml'],['onion',1,'pc']],
  s:{fr:["Dessalez la morue douze heures en changeant l'eau trois fois, puis grillez-la à la flamme ou au four jusqu'à ce qu'elle dore.","Le grillage n'est pas facultatif : c'est lui qui donne au féroce son goût fumé, et une morue seulement pochée le rend fade.","Effilochez-la finement en retirant peau et arêtes.","Écrasez les avocats à la fourchette avec le citron vert, l'ail pilé et beaucoup de piment — jamais au mixeur, la texture doit rester grossière.","Incorporez la farine de manioc peu à peu jusqu'à ce que la masse se roule en boulettes qui tiennent dans la main."],
     en:["Desalt the cod twelve hours, changing the water three times, then grill it over a flame or in the oven until it colours.","The grilling is not optional: it gives the féroce its smoky taste, and merely poached cod makes it bland.","Flake it finely, removing skin and bones.","Crush the avocados with a fork with lime, crushed garlic and plenty of chilli — never in a blender, the texture must stay coarse.","Work in the cassava flour little by little until the mass rolls into balls that hold in the hand."]} },

{ id:'flan-coco-antillais', c:'na', lat:16.333, lon:-61.351, base:8, prep:30, cook:60, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'cake',food:['#f2dfa8','#c9754a','#f4f0e6','#e8c46a'],garnish:'#c9754a'},
  n:{fr:'Flan coco',en:'Coconut flan'},
  p:{fr:'Le Moule, Guadeloupe',en:'Le Moule, Guadeloupe'},
  d:{fr:"Un flan au lait de coco caramélisé, cuit au bain-marie. Il tient du flan espagnol par le caramel et de la cuisine antillaise par le coco et la vanille locale ; il se sert glacé, ce que sa richesse en gras de coco permet sans qu'il durcisse.",
     en:"A coconut-milk flan with caramel, baked in a water bath. It owes the caramel to the Spanish flan and the coconut and local vanilla to Antillean cooking; it is served chilled, which its coconut fat allows without hardening."},
  i:[['coconut_milk',600,'ml'],['condensed_milk',400,'g'],['egg',6,'pc'],['sugar',200,'g'],['vanilla',2,'pc'],['coconut',80,'g'],['rum',40,'ml'],['lime',1,'pc']],
  s:{fr:["Faites un caramel à sec avec le sucre, sans eau ni cuillère : on incline le moule, on ne remue jamais.","Versez-le brûlant au fond du moule et faites-le tourner aussitôt — refroidi de dix secondes, il ne s'étale plus.","Battez les œufs entiers sans les faire mousser : les bulles remonteraient et perceraient la surface du flan.","Mêlez lait de coco, lait concentré, vanille grattée et rhum, puis passez au chinois pour retirer les chalazes.","Cuisez au bain-marie 60 minutes à 160 °C ; le flan doit encore trembler au centre. Réfrigérez douze heures avant de démouler."],
     en:["Make a dry caramel with the sugar, no water and no spoon: tilt the pan, never stir.","Pour it scalding into the mould and swirl it at once — ten seconds cold and it no longer spreads.","Beat the whole eggs without frothing them: bubbles would rise and pit the flan's surface.","Mix the coconut milk, condensed milk, scraped vanilla and rum, then strain to remove the chalazae.","Bake in a water bath 60 minutes at 160°C; the flan should still tremble at the centre. Chill twelve hours before turning out."]} },

{ id:'chiquetaille-de-morue', c:'na', lat:16.251, lon:-61.271, base:6, prep:40, cook:15, diff:1, tags:['sea','fresh','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4ead4',style:'salad',food:['#f4f0e6','#e8c46a','#e07a6a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Chiquetaille de morue',en:'Chiquetaille de morue'},
  p:{fr:'Saint-François, Guadeloupe',en:'Saint-François, Guadeloupe'},
  d:{fr:"De la morue grillée puis déchiquetée à la main, marinée à l'oignon, au citron vert et au piment. Chiquetailler veut dire mettre en pièces en créole : le poisson se déchire aux doigts et jamais au couteau, la fibre devant rester longue.",
     en:"Salt cod grilled then torn by hand, marinated with onion, lime and chilli. Chiquetailler means to tear to pieces in Creole: the fish is pulled apart with the fingers and never cut, the fibres having to stay long."},
  i:[['salt_cod',600,'g'],['onion',3,'pc'],['scallion',1,'bunch'],['garlic',6,'clove'],['scotch_bonnet',2,'pc'],['lime',5,'pc'],['olive_oil',150,'ml'],['parsley',1,'bunch'],['bell_pepper',1,'pc']],
  s:{fr:["Dessalez la morue douze heures en changeant l'eau quatre fois, et goûtez un fragment avant d'aller plus loin.","Grillez-la sur la braise ou sous le gril jusqu'à ce que la peau noircisse par endroits et que la chair se craquelle.","Déchirez-la aux doigts en longs filaments, en retirant peau et arêtes au passage.","Émincez les oignons très fin et faites-les dégorger dix minutes au sel avant de les rincer — crus, ils dominent tout.","Mêlez le tout à l'huile, au citron vert et au piment, et laissez mariner deux heures au frais. Se sert froid, sur du pain."],
     en:["Desalt the cod twelve hours, changing the water four times, and taste a fragment before going further.","Grill it over coals or under a grill until the skin blackens in places and the flesh cracks.","Tear it into long threads with your fingers, removing skin and bones as you go.","Slice the onions very thinly and salt them for ten minutes before rinsing — raw, they overpower everything.","Mix everything with oil, lime and chilli, and marinate two hours in the cold. Served cold, on bread."]} },

{ id:'lambi-martiniquais', c:'na', lat:14.489, lon:-61.086, base:6, prep:60, cook:120, diff:3, tags:['sea','slow','stew'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'stew',food:['#f4f0e6','#e8c46a','#c9924a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Lambi en fricassée',en:'Conch fricassée'},
  p:{fr:'Les Anses-d\'Arlet, Martinique',en:'Les Anses-d\'Arlet, Martinique'},
  d:{fr:"Le grand mollusque des Caraïbes, longuement mijoté jusqu'à devenir tendre. Le lambi est aujourd'hui protégé et sa pêche réglementée : sa croissance est lente, et les récifs antillais ont failli en être vidés dans les années 1980.",
     en:"The great Caribbean mollusc, long simmered until tender. Conch is now protected and its fishing regulated: it grows slowly, and Antillean reefs were nearly emptied of it in the 1980s."},
  i:[['conch',1.2,'kg'],['onion',3,'pc'],['garlic',10,'clove'],['scallion',1,'bunch'],['thyme',1,'bunch'],['tomato',300,'g'],['scotch_bonnet',1,'pc'],['lime',5,'pc'],['white_wine',200,'ml'],['olive_oil',80,'ml'],['clove',4,'pc'],['salt',null,'']],
  s:{fr:["Battez la chair au maillet jusqu'à l'attendrir visiblement : c'est un muscle très dense, et sans cette étape deux heures de cuisson n'y suffisent pas.","Frottez-la au citron vert et au gros sel pour ôter le mucus, puis rincez abondamment.","Coupez en morceaux réguliers et faites-les blanchir dix minutes ; jetez cette eau.","Faites revenir les aromates, remettez le lambi, mouillez au vin blanc et à l'eau, et laissez mijoter deux heures à couvert.","Vérifiez la tendreté à la fourchette avant de servir : selon l'âge de l'animal, il faut parfois trente minutes de plus."],
     en:["Beat the flesh with a mallet until visibly tenderised: it is a very dense muscle, and without this two hours' cooking will not do.","Rub it with lime and coarse salt to remove the mucus, then rinse thoroughly.","Cut into even pieces and blanch them ten minutes; discard that water.","Fry the aromatics, return the conch, moisten with white wine and water, and simmer two hours covered.","Test with a fork before serving: depending on the animal's age, another thirty minutes is sometimes needed."]} },

{ id:'ti-punch', c:'na', lat:14.616, lon:-61.058, base:1, prep:5, cook:0, diff:1, tags:['drink','fast','fresh'],
  art:{v:'glass',bg:'#26485c',plate:'#f4ead4',style:'drink',food:['#f0e8d0','#e8dcb8','#7fae5a','#f2dfa8'],garnish:'#6fbf8f'},
  n:{fr:'Ti-punch',en:'Ti-punch'},
  p:{fr:'Martinique',en:'Martinique'},
  d:{fr:"Rhum agricole, sucre de canne et un zeste de citron vert, sans glace ni eau. Le rhum agricole de Martinique est distillé à partir du jus de canne frais et non de mélasse, seul rhum au monde à porter une AOC, obtenue en 1996.",
     en:"Agricultural rum, cane sugar and a twist of lime, with no ice and no water. Martinique's rhum agricole is distilled from fresh cane juice rather than molasses, the only rum in the world with an AOC, granted in 1996."},
  i:[['white_rum',60,'ml'],['cane_syrup',10,'ml'],['lime',1,'pc']],
  s:{fr:["Employez un rhum agricole blanc à 50 ou 55 degrés : un rhum de mélasse donne une boisson lourde et sucrée, autre chose entièrement.","Découpez un morceau d'écorce de citron vert avec un peu de chair, jamais une rondelle entière — le jus rendrait le punch acide.","Écrasez à peine l'écorce contre le fond du verre avec le bâton lélé, pour libérer les huiles sans amertume.","Versez le sirop de canne puis le rhum, et remuez lentement quelques secondes.","Ne mettez pas de glace : elle diluerait et refroidirait le rhum, dont les arômes ne se libèrent qu'à température ambiante."],
     en:["Use a white rhum agricole at 50 or 55 degrees: a molasses rum gives a heavy, sweet drink, something else entirely.","Cut a piece of lime peel with a little flesh, never a whole slice — the juice would make the punch sour.","Barely crush the peel against the bottom of the glass with the lélé stick, to release the oils without bitterness.","Pour in the cane syrup then the rum, and stir slowly for a few seconds.","Add no ice: it would dilute and chill the rum, whose aromas only open at room temperature."]} }
,

{ id:'planteur-martiniquais', c:'na', lat:14.741, lon:-61.175, base:6, prep:20, cook:0, diff:1, tags:['drink','fruit','fresh'],
  art:{v:'glass',bg:'#26485c',plate:'#f4ead4',style:'drink',food:['#e8a032','#e07a6a','#e8c46a','#f2dfa8'],garnish:'#6fbf8f'},
  n:{fr:'Punch planteur',en:'Planter\'s punch'},
  p:{fr:'Saint-Pierre, Martinique',en:'Saint-Pierre, Martinique'},
  d:{fr:"Un punch aux jus de fruits, longuement macéré avec le rhum et les épices. La règle mnémotechnique caribéenne dit : un d'acide, deux de sucre, trois de fort, quatre de faible — les proportions se retiennent encore ainsi.",
     en:"A fruit-juice punch, long macerated with rum and spices. The Caribbean mnemonic runs: one of sour, two of sweet, three of strong, four of weak — the proportions are still remembered that way."},
  i:[['amber_rum',400,'ml'],['orange_juice',600,'ml'],['pineapple_juice',400,'ml'],['guava_juice',200,'ml'],['cane_syrup',150,'ml'],['lime',4,'pc'],['cinnamon_stick',2,'pc'],['nutmeg',3,'g'],['vanilla',1,'pc']],
  s:{fr:["Employez des jus pressés ou à défaut sans sucre ajouté : les nectars du commerce déséquilibrent tout et rendent le punch écœurant.","Faites infuser la cannelle, la vanille fendue et la muscade râpée dans le rhum pendant vingt-quatre heures.","Cette infusion préalable change tout : ajoutées au dernier moment, les épices restent en surface et ne parfument rien.","Mêlez les jus, le sirop de canne et le rhum infusé, et goûtez avant d'ajuster l'acidité au citron vert.","Laissez reposer au frais au moins six heures. Servez sur glace, avec une râpée de muscade fraîche."],
     en:["Use pressed juices or at least ones with no added sugar: commercial nectars unbalance everything and make the punch cloying.","Infuse the cinnamon, split vanilla and grated nutmeg in the rum for twenty-four hours.","This prior infusion changes everything: added at the last moment, spices stay on the surface and scent nothing.","Mix the juices, cane syrup and infused rum, and taste before adjusting the acidity with lime.","Rest in the cold at least six hours. Serve over ice, with fresh grated nutmeg."]} },

{ id:'blanc-manger-coco', c:'na', lat:14.610, lon:-61.065, base:8, prep:30, cook:15, diff:1, tags:['sweet','fruit','comfort'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'cake',food:['#f4f0e6','#f0e8d0','#e8dcb8','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Blanc-manger coco',en:'Coconut blancmange'},
  p:{fr:'Fort-de-France, Martinique',en:'Fort-de-France, Martinique'},
  d:{fr:"Une crème de coco prise à l'agar-agar ou à la gélatine, démoulée en couronne. Le blanc-manger est un dessert médiéval européen que les Antilles ont refait au lait de coco : la version créole a complètement supplanté l'originale à l'amande.",
     en:"A coconut cream set with agar or gelatine, turned out as a ring. Blancmange is a medieval European dessert that the Antilles remade with coconut milk: the Creole version has entirely displaced the almond original."},
  i:[['coconut_milk',800,'ml'],['condensed_milk',300,'g'],['agar_agar',6,'g'],['sugar',100,'g'],['vanilla',2,'pc'],['cinnamon_stick',1,'pc'],['lime',1,'pc'],['rum',30,'ml']],
  s:{fr:["Faites chauffer le lait de coco avec la vanille fendue et la cannelle sans jamais le faire bouillir : bouilli, il se sépare et rend son huile.","Délayez l'agar-agar dans un peu de lait froid avant de l'incorporer, sinon il forme des grains qui ne fondent plus.","Portez à frémissement une minute exactement : l'agar-agar a besoin de 90 °C pour s'activer, mais pas davantage.","Ajoutez le lait concentré et le rhum hors du feu, et passez au chinois.","Versez dans un moule à savarin mouillé et réfrigérez quatre heures. L'agar-agar prend à température ambiante, mais le froid affine la texture."],
     en:["Heat the coconut milk with the split vanilla and cinnamon without ever boiling it: boiled, it splits and releases its oil.","Slake the agar in a little cold milk before adding it, or it forms grains that never dissolve.","Bring to a tremble for exactly one minute: agar needs 90°C to activate, but no more.","Add the condensed milk and rum off the heat, and strain.","Pour into a wetted ring mould and chill four hours. Agar sets at room temperature, but cold refines the texture."]} },

{ id:'accras-de-crevettes', c:'na', lat:14.677, lon:-60.939, base:6, prep:60, cook:20, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#e8c46a','#e07a6a','#c9924a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Accras de crevettes',en:'Shrimp accras'},
  p:{fr:'Le Robert, Martinique',en:'Le Robert, Martinique'},
  d:{fr:"Des beignets de crevettes hachées, plus fins que ceux à la morue. Le mot accra vient du yoruba akara, un beignet de haricots d'Afrique de l'Ouest ; la traversée a remplacé le haricot par la farine et le poisson.",
     en:"Fritters of chopped shrimp, more delicate than the salt-cod kind. The word accra comes from the Yoruba akara, a West African bean fritter; the crossing replaced the bean with flour and fish."},
  i:[['shrimp',500,'g'],['flour',250,'g'],['egg',2,'pc'],['baking_powder',8,'g'],['scallion',1,'bunch'],['parsley',1,'bunch'],['garlic',5,'clove'],['scotch_bonnet',1,'pc'],['lime',2,'pc'],['whole_milk',150,'ml'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Décortiquez les crevettes et hachez-les au couteau, gros : mixées, elles rendent leur eau et la pâte devient liquide.","Préparez la pâte en mêlant farine, œufs, lait et levure, et laissez-la reposer une heure — le repos donne des beignets légers.","Incorporez les crevettes, les herbes hachées et le piment juste avant de frire, jamais à l'avance.","Chauffez l'huile à 175 °C exactement : plus chaude, l'extérieur brunit avant que le centre cuise.","Déposez à la petite cuillère et frites trois minutes en retournant une fois. Égouttez sur papier et servez brûlant."],
     en:["Shell the shrimp and chop them coarsely by knife: blended, they release their water and the batter goes thin.","Make the batter with flour, eggs, milk and baking powder, and rest it an hour — resting gives light fritters.","Fold in the shrimp, chopped herbs and chilli just before frying, never in advance.","Heat the oil to exactly 175°C: hotter, the outside browns before the centre cooks.","Drop by teaspoonfuls and fry three minutes, turning once. Drain on paper and serve scalding."]} },

{ id:'boudin-creole', c:'na', lat:14.740, lon:-60.964, base:10, prep:120, cook:60, diff:3, tags:['pork','street','festive'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#3a1a1a','#5a2a2a','#8f4a3a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Boudin créole',en:'Creole blood sausage'},
  p:{fr:'Trinité, Martinique',en:'Trinité, Martinique'},
  d:{fr:"Un boudin noir au pain trempé, très relevé au piment et aux herbes. Il se mange en apéritif avec les accras, coupé en petits tronçons, et forme avec eux le duo obligatoire de tout début de repas antillais.",
     en:"A blood sausage with soaked bread, heavily seasoned with chilli and herbs. It is eaten as an appetiser with accras, cut into short lengths, and together they form the obligatory opening of any Antillean meal."},
  i:[['pork_blood',1.5,'l'],['white_bread',400,'g'],['whole_milk',400,'ml'],['onion',500,'g'],['scallion',2,'bunch'],['garlic',12,'clove'],['thyme',2,'bunch'],['scotch_bonnet',3,'pc'],['parsley',1,'bunch'],['clove',8,'pc'],['sausage_casings',3,'pc'],['nutmeg',5,'g'],['salt',null,'']],
  s:{fr:["Battez le sang dès sa collecte et filtrez-le à l'étamine pour retirer les caillots — un seul caillot suffit à faire éclater le boyau.","Faites tremper le pain rassis dans le lait, pressez-le et émiettez-le.","Hachez très fin oignons, cives, ail, thym et piment : le boudin créole se distingue par la quantité d'herbes, presque autant que de sang.","Mêlez le tout, goûtez en faisant cuire une cuillerée à la poêle, et rectifiez avant d'embosser.","Remplissez les boyaux aux trois quarts seulement et pochez à 80 °C pendant vingt minutes, sans jamais laisser bouillir."],
     en:["Beat the blood as soon as it is collected and strain it through muslin to remove clots — a single clot will burst the casing.","Soak the stale bread in the milk, press it out and crumble it.","Chop the onions, chives, garlic, thyme and chilli very finely: Creole boudin is marked by the quantity of herbs, almost as much as blood.","Mix everything, taste by frying a spoonful, and adjust before filling.","Fill the casings only three-quarters full and poach at 80°C for twenty minutes, never letting it boil."]} },

{ id:'pimentade-de-poisson', c:'sa', lat:5.503, lon:-54.028, base:6, prep:40, cook:40, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#2c3440',plate:'#f0e4c8',style:'fish',food:['#e07a6a','#e8a032','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Pimentade de poisson',en:'Fish pimentade'},
  p:{fr:'Saint-Laurent-du-Maroni, Guyane',en:'Saint-Laurent-du-Maroni, French Guiana'},
  d:{fr:"Un court-bouillon de poisson au roucou et au piment, très rouge. Le roucou vient de l'urucum amérindien, une graine dont la pulpe colore sans presque aucun goût ; les Wayana s'en peignaient le corps bien avant qu'il n'entre en cuisine.",
     en:"A fish court-bouillon with annatto and chilli, deeply red. Annatto comes from Amerindian urucum, a seed whose pulp colours with almost no flavour; the Wayana painted their bodies with it long before it entered the kitchen."},
  i:[['white_fish',1.2,'kg'],['annatto',20,'g'],['onion',3,'pc'],['garlic',8,'clove'],['tomato',400,'g'],['scallion',1,'bunch'],['scotch_bonnet',2,'pc'],['lime',4,'pc'],['thyme',1,'bunch'],['olive_oil',80,'ml'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Faites mariner les darnes de poisson une demi-heure au citron vert, à l'ail et au sel.","Faites infuser le roucou dans l'huile chaude à feu doux cinq minutes, puis filtrez : l'huile devient orange vif et c'est elle qui colore, pas la graine.","Ne laissez pas le roucou brûler — il vire au brun amer en quelques secondes de trop.","Faites revenir oignons, tomates et piment dans l'huile colorée, et mouillez d'eau bouillante.","Pochez le poisson dix minutes dans ce bouillon frémissant, sans le remuer. Servez avec du riz blanc."],
     en:["Marinate the fish steaks half an hour in lime, garlic and salt.","Infuse the annatto in hot oil over low heat for five minutes, then strain: the oil turns bright orange and it is the oil that colours, not the seed.","Do not let the annatto burn — a few seconds too long and it turns bitter brown.","Fry onions, tomatoes and chilli in the coloured oil, and moisten with boiling water.","Poach the fish ten minutes in this simmering broth, without stirring. Serve with white rice."]} },

{ id:'riz-colle-guyanais', c:'sa', lat:5.660, lon:-53.783, base:6, prep:30, cook:50, diff:2, tags:['rice','legume','comfort'],
  art:{v:'pot',bg:'#2c3440',plate:'#f0e4c8',style:'rice',food:['#4a2a1a','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Riz collé',en:'Riz collé'},
  p:{fr:'Mana, Guyane',en:'Mana, French Guiana'},
  d:{fr:"Du riz cuit avec des haricots rouges et du lait de coco, jusqu'à ce que les grains se lient. Il se prépare dans toute la Caraïbe sous des noms différents ; en Guyane il accompagne le poisson boucané et se sert à la Toussaint.",
     en:"Rice cooked with red beans and coconut milk until the grains bind together. It is made throughout the Caribbean under different names; in Guiana it accompanies smoked fish and is served at All Saints."},
  i:[['red_kidney_beans',300,'g'],['long_grain_rice',500,'g'],['coconut_milk',500,'ml'],['smoked_bacon',200,'g'],['onion',2,'pc'],['garlic',6,'clove'],['thyme',1,'bunch'],['scallion',1,'bunch'],['scotch_bonnet',1,'pc'],['clove',4,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper les haricots rouges une nuit, puis cuisez-les une heure dans leur eau avec le thym et les clous de girofle.","Gardez cette eau de cuisson : c'est elle qui donne au riz sa couleur brune et son goût, et la jeter est l'erreur la plus courante.","Faites fondre le lard, ajoutez oignons et ail, puis le riz que vous nacrez deux minutes.","Mouillez de l'eau des haricots complétée au lait de coco, ajoutez les haricots et le piment entier non percé.","Cuisez 20 minutes à couvert, feu très doux, sans remuer. Retirez le piment avant de servir."],
     en:["Soak the red beans overnight, then cook them an hour in their water with the thyme and cloves.","Keep that cooking water: it gives the rice its brown colour and its flavour, and throwing it away is the commonest mistake.","Render the bacon, add onions and garlic, then the rice, pearled for two minutes.","Moisten with the bean water made up with coconut milk, add the beans and the whole unpierced chilli.","Cook 20 minutes covered over very low heat, without stirring. Remove the chilli before serving."]} },

{ id:'couac', c:'sa', lat:5.744, lon:-53.937, base:8, prep:2880, cook:60, diff:3, tags:['veg','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9a878','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Couac',en:'Couac'},
  p:{fr:'Awala-Yalimapo, Guyane',en:'Awala-Yalimapo, French Guiana'},
  d:{fr:"Une semoule de manioc amer, râpée, pressée puis grillée, base de l'alimentation amérindienne guyanaise. Le manioc amer est toxique cru : la presse traditionnelle en vannerie, le couleuvre, en exprime le jus cyanhydrique avant la cuisson.",
     en:"A semolina of bitter cassava, grated, pressed then toasted, the staple of Amerindian Guiana. Bitter cassava is toxic raw: the traditional woven press, the couleuvre, squeezes out the cyanogenic juice before cooking."},
  i:[['bitter_cassava',5,'kg'],['water',2,'l'],['salt',null,'']],
  s:{fr:["Pelez et râpez le manioc amer très finement — c'est le râpage qui libère les enzymes détruisant les composés cyanogènes.","Bourrez la pulpe dans le couleuvre, un long tube de vannerie souple, et suspendez-le en tirant vers le bas.","Le tube s'allonge et se resserre, et le jus toxique s'écoule : laissez presser plusieurs heures, jusqu'à ce que la pulpe soit sèche.","Tamisez la pulpe pour l'aérer, puis grillez-la sur une platine brûlante en remuant sans arrêt, une heure durant.","Le couac est prêt quand il est doré, sec et croustillant. Il se conserve des mois et se mange avec tout."],
     en:["Peel and grate the bitter cassava very finely — grating releases the enzymes that destroy the cyanogenic compounds.","Pack the pulp into the couleuvre, a long tube of flexible basketry, and hang it, pulling downwards.","The tube lengthens and tightens, and the toxic juice runs out: let it press for several hours, until the pulp is dry.","Sieve the pulp to aerate it, then toast it on a scalding plate, stirring without pause, for a full hour.","Couac is ready when golden, dry and crisp. It keeps for months and is eaten with everything."]} },

{ id:'wassai-bowl', c:'sa', lat:4.567, lon:-52.467, base:4, prep:30, cook:20, diff:2, tags:['fruit','fresh','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ead4',style:'other',food:['#3a2a4a','#5a3a5a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Wassaï au couac',en:'Wassaï with couac'},
  p:{fr:'Cacao, Guyane',en:'Cacao, French Guiana'},
  d:{fr:"La pulpe de wassaï, l'açaï guyanais, servie salée avec du couac et du poisson. Le wassaï se cueille sur un palmier de vingt mètres qu'on grimpe pieds nus à l'aide d'un anneau de liane ; la pulpe s'oxyde en quelques heures et se travaille le jour même.",
     en:"The pulp of wassaï, Guiana's açaí, served savoury with couac and fish. Wassaï is picked from a twenty-metre palm climbed barefoot with a liana loop; the pulp oxidises within hours and must be worked the same day."},
  i:[['acai_pulp',600,'g'],['cassava_flour',150,'g'],['smoked_fish',400,'g'],['scallion',1,'bunch'],['scotch_bonnet',1,'pc'],['lime',2,'pc'],['salt',null,'']],
  s:{fr:["Faites tremper les baies de wassaï dans l'eau tiède une demi-heure : la pulpe est une pellicule mince autour d'un gros noyau et ne se détache pas à froid.","Frottez-les à la main dans l'eau jusqu'à ce que la pulpe s'en aille, puis filtrez et jetez les noyaux.","Ne sucrez pas : en Guyane le wassaï est salé, et le servir en dessert glacé est un usage étranger.","Effilochez le poisson boucané et mêlez-le aux cives et au piment.","Servez la pulpe à peine fraîche, avec le poisson et le couac à saupoudrer soi-même."],
     en:["Soak the wassaï berries in warm water for half an hour: the pulp is a thin film around a large stone and will not come away cold.","Rub them by hand in the water until the pulp releases, then strain and discard the stones.","Do not sweeten: in Guiana wassaï is savoury, and serving it as a frozen dessert is a foreign habit.","Flake the smoked fish and mix it with the chives and chilli.","Serve the pulp barely cool, with the fish and couac to dust over it yourself."]} },

{ id:'kalawang', c:'sa', lat:3.165, lon:-52.336, base:6, prep:40, cook:90, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#8f5a3a','#c9754a','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kalawang',en:'Kalawang'},
  p:{fr:'Camopi, Guyane',en:'Camopi, French Guiana'},
  d:{fr:"Une soupe wayãpi de poisson au jus de manioc réduit, brun et épais. Le jus de manioc amer, toxique cru, devient inoffensif après une longue ébullition : réduit des heures, il donne une sauce sombre au goût de fumé qu'on appelle aussi tucupi noir.",
     en:"A Wayãpi fish soup with reduced cassava juice, brown and thick. The bitter cassava juice, toxic raw, becomes harmless after long boiling: reduced for hours it gives a dark, smoky sauce also known as black tucupi."},
  i:[['cassava_juice',1.5,'l'],['freshwater_fish',1,'kg'],['scotch_bonnet',3,'pc'],['scallion',1,'bunch'],['garlic',4,'clove'],['salt',null,'']],
  s:{fr:["Récupérez le jus pressé du manioc amer et laissez-le décanter : l'amidon tombe au fond et se garde à part.","Faites bouillir le jus à découvert pendant au moins deux heures — cette ébullition prolongée est ce qui le rend comestible, il n'y a pas de raccourci.","Il réduit de moitié, brunit et prend une consistance sirupeuse et un goût fumé.","Ajoutez les piments entiers et laissez encore vingt minutes, puis le poisson en morceaux.","Dix minutes de pochage suffisent. Servez avec du couac, dans lequel on trempe la sauce."],
     en:["Collect the pressed juice of bitter cassava and let it settle: the starch falls to the bottom and is kept separately.","Boil the juice uncovered for at least two hours — that prolonged boiling is what makes it edible, and there is no shortcut.","It reduces by half, browns and takes on a syrupy body and a smoky taste.","Add the whole chillies and give it another twenty minutes, then the fish in pieces.","Ten minutes' poaching is enough. Serve with couac, dipped into the sauce."]} },

{ id:'punch-coco-guyanais', c:'sa', lat:5.160, lon:-52.650, base:8, prep:30, cook:20, diff:1, tags:['drink','sweet','festive'],
  art:{v:'glass',bg:'#2c3440',plate:'#f4ead4',style:'drink',food:['#f4f0e6','#f0e8d0','#e8dcb8','#c9a878'],garnish:'#c9754a'},
  n:{fr:'Punch coco',en:'Coconut punch'},
  p:{fr:'Kourou, Guyane',en:'Kourou, French Guiana'},
  d:{fr:"Une liqueur crémeuse de lait de coco, lait concentré et rhum, servie glacée à Noël. Chaque famille guyanaise a sa proportion et la garde ; les bouteilles s'échangent en cadeau pendant tout le mois de décembre.",
     en:"A creamy liqueur of coconut milk, condensed milk and rum, served iced at Christmas. Every Guianese family has its own proportions and keeps them; bottles are exchanged as gifts throughout December."},
  i:[['coconut_milk',500,'ml'],['condensed_milk',400,'g'],['evaporated_milk',300,'ml'],['white_rum',400,'ml'],['vanilla',2,'pc'],['cinnamon_stick',2,'pc'],['nutmeg',5,'g'],['lime',1,'pc']],
  s:{fr:["Faites chauffer doucement le lait de coco avec la vanille fendue et la cannelle, sans bouillir, puis laissez infuser une heure.","Filtrez et mêlez aux laits concentré et évaporé en fouettant, jusqu'à ce que le mélange soit parfaitement lisse.","Laissez refroidir complètement avant d'ajouter le rhum : versé dans un liquide chaud, il s'évapore en partie et le punch perd sa force.","Ajoutez la muscade râpée et un zeste de citron vert, et mettez en bouteille.","Laissez reposer une semaine au frais en secouant chaque jour. Il se garde plusieurs mois et s'améliore."],
     en:["Warm the coconut milk gently with the split vanilla and cinnamon, without boiling, then infuse for an hour.","Strain and whisk into the condensed and evaporated milks, until perfectly smooth.","Cool completely before adding the rum: poured into hot liquid it partly evaporates and the punch loses its strength.","Add grated nutmeg and a twist of lime, and bottle.","Rest a week in the cold, shaking daily. It keeps for months and improves."]} },

{ id:'samoussas-reunionnais', c:'af', lat:-20.882, lon:55.450, base:8, prep:90, cook:25, diff:2, tags:['street','fry','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Samoussas réunionnais',en:'Réunion samosas'},
  p:{fr:'Saint-Denis, La Réunion',en:'Saint-Denis, Réunion'},
  d:{fr:"De petits triangles frits à la farce épicée, apéritif universel de l'île. Ils sont arrivés avec les engagés indiens du XIXe siècle mais ont beaucoup rétréci : le samoussa réunionnais tient dans une bouchée, contre trois ou quatre pour l'indien.",
     en:"Small fried triangles with a spiced filling, the island's universal appetiser. They arrived with nineteenth-century Indian indentured workers but have shrunk considerably: the Réunion samosa is a single mouthful, against three or four for the Indian."},
  i:[['flour',400,'g'],['water',200,'ml'],['sunflower_oil',60,'ml'],['ground_beef',400,'g'],['onion',3,'pc'],['garlic',6,'clove'],['ginger',30,'g'],['turmeric',10,'g'],['curry_powder',15,'g'],['scallion',1,'bunch'],['chili_pepper',2,'pc'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte ferme, abaissez-la très fin et découpez des bandes de 5 cm ; huilez-les et empilez-les avant de les cuire brièvement à sec.","Cette cuisson préalable des bandes est ce qui donne la finesse : frites crues, elles épaississent et deviennent cassantes.","Faites revenir la viande avec oignon, ail, gingembre et épices jusqu'à ce qu'elle soit sèche — une farce humide décolle la pâte à la friture.","Pliez en triangles en repliant la bande sur elle-même, et scellez à la pâte de farine et d'eau.","Frites à 170 °C, trois minutes, jusqu'à ce qu'ils dorent uniformément. Se mangent brûlants."],
     en:["Knead a firm dough, roll it very thin and cut 5 cm strips; oil them and stack them before briefly cooking them dry.","This pre-cooking of the strips is what gives the fineness: fried raw, they thicken and turn brittle.","Fry the meat with onion, garlic, ginger and spices until dry — a wet filling unsticks the pastry in the fryer.","Fold into triangles by turning the strip on itself, and seal with a flour-and-water paste.","Fry at 170°C for three minutes, until evenly golden. Eaten scalding."]} }
,

{ id:'bonbon-piment', c:'af', lat:-21.010, lon:55.270, base:8, prep:720, cook:20, diff:2, tags:['street','fry','legume'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bonbon piment',en:'Bonbon piment'},
  p:{fr:'Saint-Paul, La Réunion',en:'Saint-Paul, Réunion'},
  d:{fr:"Des beignets de pois du Cap ou de lentilles, très relevés, vendus au marché forain. Ils descendent du vada indien et se mangent tièdes, souvent glissés dans un pain, en attendant le repas.",
     en:"Fritters of Cape peas or lentils, sharply spiced, sold at the open-air market. They descend from the Indian vada and are eaten warm, often slipped into a roll, while waiting for a meal."},
  i:[['split_peas',500,'g'],['onion',2,'pc'],['garlic',6,'clove'],['ginger',30,'g'],['turmeric',10,'g'],['cumin',10,'g'],['chili_pepper',4,'pc'],['scallion',1,'bunch'],['cilantro',1,'bunch'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Faites tremper les pois douze heures : ils doivent se casser net sous l'ongle, sans être mous.","Égouttez-les parfaitement et broyez-les au moulin sans ajouter d'eau — c'est le point le plus important, l'eau empêche la pâte de tenir.","La pâte doit rester granuleuse : trop lisse, les bonbons deviennent compacts au lieu d'être aérés.","Mêlez les épices, l'oignon, l'ail et le piment hachés très fin, et laissez reposer une heure.","Formez des boulettes à la cuillère et frites à 170 °C, quatre minutes, jusqu'à ce qu'elles remontent et dorent."],
     en:["Soak the peas twelve hours: they should snap cleanly under a nail without being soft.","Drain them perfectly and grind them without adding water — this is the crucial point, water stops the paste holding.","The paste must stay grainy: too smooth, and the fritters turn compact instead of airy.","Mix in the spices, onion, garlic and finely chopped chilli, and rest an hour.","Shape balls with a spoon and fry at 170°C for four minutes, until they rise and colour."]} },

{ id:'achards-de-legumes', c:'af', lat:-20.962, lon:55.650, base:8, prep:60, cook:15, diff:1, tags:['veg','fresh','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'salad',food:['#e8c46a','#7fae5a','#e07a6a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Achards de légumes',en:'Vegetable achards'},
  p:{fr:'Saint-André, La Réunion',en:'Saint-André, Réunion'},
  d:{fr:"Des légumes taillés en fins bâtonnets, blanchis et confits à l'huile safranée. Le mot vient du persan achar par l'Inde ; à La Réunion l'achard n'est pas un condiment mais une entrée à part entière, servie en montagne dans les assiettes.",
     en:"Vegetables cut into fine batons, blanched and preserved in turmeric oil. The word comes from Persian achar by way of India; on Réunion achard is not a condiment but an entrée in its own right, served in bowls."},
  i:[['carrot',400,'g'],['green_beans',300,'g'],['cabbage',300,'g'],['chayote',2,'pc'],['onion',3,'pc'],['garlic',8,'clove'],['ginger',40,'g'],['turmeric',15,'g'],['sunflower_oil',200,'ml'],['white_wine_vinegar',100,'ml'],['chili_pepper',3,'pc'],['salt',null,'']],
  s:{fr:["Taillez tous les légumes en bâtonnets de même épaisseur, fins comme des allumettes, pour qu'ils cuisent au même rythme.","Blanchissez-les trente secondes à peine dans l'eau bouillante salée, puis plongez-les aussitôt dans l'eau glacée.","Ce choc thermique fixe la couleur et le croquant ; sans lui, l'achard devient mou en une journée.","Égouttez et séchez très soigneusement sur un linge — la moindre eau résiduelle fait tourner la préparation.","Faites chauffer l'huile avec le safran, l'ail et le gingembre, versez sur les légumes, ajoutez le vinaigre et laissez macérer une nuit."],
     en:["Cut all the vegetables into batons of the same thickness, fine as matchsticks, so they cook at the same rate.","Blanch them barely thirty seconds in boiling salted water, then plunge them straight into iced water.","This thermal shock fixes the colour and the crunch; without it, achard goes soft within a day.","Drain and dry very thoroughly on a cloth — the least residual water will turn the preparation.","Heat the oil with the turmeric, garlic and ginger, pour it over the vegetables, add the vinegar and macerate overnight."]} },

{ id:'gateau-patate-douce', c:'af', lat:-21.028, lon:55.538, base:8, prep:40, cook:60, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9754a','#e8a032','#f2dfa8','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Gâteau patate douce',en:'Sweet potato cake'},
  p:{fr:'Salazie, La Réunion',en:'Salazie, Réunion'},
  d:{fr:"Un gâteau dense de patate douce, sans farine, parfumé à la vanille Bourbon. C'est le gâteau des cirques de l'intérieur, où la patate pousse bien et la farine coûtait cher ; il se garde plusieurs jours et se transporte en randonnée.",
     en:"A dense sweet potato cake without flour, scented with Bourbon vanilla. It is the cake of the inland cirques, where sweet potato grows well and flour was costly; it keeps for days and travels well on a hike."},
  i:[['sweet_potato',1,'kg'],['sugar',200,'g'],['butter',120,'g'],['egg',4,'pc'],['vanilla',2,'pc'],['coconut_milk',150,'ml'],['rum',40,'ml'],['cinnamon',5,'g'],['salt',null,'']],
  s:{fr:["Faites cuire les patates entières avec la peau, au four ou à la vapeur : bouillies pelées, elles se gorgent d'eau et le gâteau ne prend pas.","Pelez-les chaudes et écrasez-les au presse-purée, jamais au mixeur, qui rendrait la chair élastique.","Mêlez le beurre fondu, le sucre, les jaunes, la vanille grattée, le rhum et le lait de coco.","Montez les blancs en neige et incorporez-les délicatement : c'est la seule chose qui allège un gâteau sans farine.","Cuisez une heure à 170 °C. Le gâteau doit rester moelleux au centre ; il se raffermit en refroidissant."],
     en:["Cook the potatoes whole in their skins, in the oven or steamed: boiled peeled, they take on water and the cake will not set.","Peel them hot and mash them with a ricer, never a blender, which would make the flesh elastic.","Mix in the melted butter, sugar, yolks, scraped vanilla, rum and coconut milk.","Whip the whites and fold them in gently: it is the only thing that lightens a flourless cake.","Bake an hour at 170°C. The cake should stay moist at the centre; it firms as it cools."]} },

{ id:'rhum-arrange', c:'af', lat:-21.133, lon:55.633, base:12, prep:30, cook:0, diff:1, tags:['drink','fruit','slow'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#c9754a','#e8a032','#8f5a3a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Rhum arrangé',en:'Rhum arrangé'},
  p:{fr:'La Plaine-des-Palmistes, La Réunion',en:'La Plaine-des-Palmistes, Réunion'},
  d:{fr:"Du rhum macéré des mois avec des fruits, des épices ou des écorces. Chaque famille réunionnaise garde ses bonbonnes et ses recettes ; le faham, une orchidée endémique des hauts, donne l'arrangé le plus recherché et le plus difficile à trouver.",
     en:"Rum macerated for months with fruit, spices or bark. Every Réunion family keeps its demijohns and its recipes; faham, an orchid endemic to the highlands, gives the most sought-after and hardest to find arrangé."},
  i:[['white_rum',3,'l'],['vanilla',6,'pc'],['pineapple',1,'pc'],['lychee',500,'g'],['ginger',80,'g'],['cinnamon_stick',4,'pc'],['cane_syrup',300,'ml'],['clove',10,'pc'],['lime',2,'pc']],
  s:{fr:["Employez un rhum blanc traditionnel à 49 degrés au moins : en dessous, la macération se trouble et le fruit fermente au lieu d'infuser.","Fendez les gousses de vanille dans la longueur et grattez-les à moitié seulement, pour que le parfum sorte lentement.","Épluchez et coupez les fruits en gros morceaux ; en petits dés, ils se délitent et troublent l'arrangé.","Emplissez la bonbonne, couvrez de rhum et ajoutez le sirop de canne, puis fermez hermétiquement.","Laissez macérer au moins trois mois à l'abri de la lumière, en retournant la bonbonne chaque semaine. Un an vaut mieux."],
     en:["Use a traditional white rum of at least 49 degrees: below that, the maceration clouds and the fruit ferments instead of infusing.","Split the vanilla pods lengthways and scrape them only half out, so the scent releases slowly.","Peel and cut the fruit into large pieces; finely diced, it disintegrates and clouds the arrangé.","Fill the demijohn, cover with rum and add the cane syrup, then seal tightly.","Macerate at least three months away from light, turning the jar weekly. A year is better."]} },

{ id:'rougail-morue', c:'af', lat:-21.339, lon:55.478, base:6, prep:60, cook:40, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e07a6a','#f4f0e6','#e8a032','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rougail morue',en:'Salt cod rougail'},
  p:{fr:'Saint-Pierre, La Réunion',en:'Saint-Pierre, Réunion'},
  d:{fr:"De la morue effilochée mijotée à la tomate, l'oignon et le curcuma. La morue est arrivée à La Réunion par les navires de la Compagnie des Indes, qui la chargeaient à Terre-Neuve : un poisson de l'Atlantique nord devenu l'un des plats les plus créoles qui soient.",
     en:"Flaked salt cod stewed with tomato, onion and turmeric. Salt cod reached Réunion on the ships of the Compagnie des Indes, loaded in Newfoundland: a North Atlantic fish that became one of the most Creole dishes there is."},
  i:[['salt_cod',700,'g'],['tomato',600,'g'],['onion',4,'pc'],['garlic',8,'clove'],['ginger',30,'g'],['turmeric',10,'g'],['thyme',1,'bunch'],['scallion',1,'bunch'],['chili_pepper',3,'pc'],['sunflower_oil',80,'ml'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Dessalez la morue douze heures en changeant l'eau quatre fois, puis pochez-la dix minutes et effilochez-la.","Faites-la revenir seule dans l'huile chaude jusqu'à ce qu'elle dore par endroits — c'est cette coloration qui distingue un rougail réussi d'un plat fade.","Faites fondre les oignons longuement, dix bonnes minutes, jusqu'à ce qu'ils blondissent et sucrent.","Ajoutez ail, gingembre, curcuma et tomates concassées, et laissez réduire vingt minutes à découvert.","Remettez la morue, mêlez sans écraser et laissez encore dix minutes. Servez avec du riz et des grains."],
     en:["Desalt the cod twelve hours, changing the water four times, then poach it ten minutes and flake it.","Fry it alone in hot oil until it browns in places — that colouring is what separates a good rougail from a bland dish.","Melt the onions at length, a good ten minutes, until they turn golden and sweeten.","Add garlic, ginger, turmeric and crushed tomatoes, and reduce twenty minutes uncovered.","Return the cod, fold it in without crushing and give it ten more minutes. Serve with rice and pulses."]} },

{ id:'carry-bichiques', c:'af', lat:-21.005, lon:55.265, base:4, prep:40, cook:25, diff:2, tags:['sea','stew','festive'],
  art:{v:'pot',bg:'#2c3440',plate:'#f0e4c8',style:'fish',food:['#e8a032','#f4f0e6','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Carry de bichiques',en:'Bichique curry'},
  p:{fr:'Embouchure de Saint-Paul, La Réunion',en:'Saint-Paul river mouth, Réunion'},
  d:{fr:"Des alevins de gobies pêchés à l'embouchure des rivières, mijotés en carry. On les appelle le caviar de La Réunion : ils ne remontent qu'à certaines lunes, quelques semaines par an, et se vendent à des prix qui dépassent ceux du homard.",
     en:"Goby fry caught at river mouths, stewed as a curry. They are called Réunion's caviar: they run only on certain moons, a few weeks a year, and fetch prices above lobster."},
  i:[['whitebait',600,'g'],['tomato',300,'g'],['onion',3,'pc'],['garlic',6,'clove'],['ginger',30,'g'],['turmeric',10,'g'],['thyme',1,'bunch'],['chili_pepper',2,'pc'],['sunflower_oil',60,'ml'],['long_grain_rice',300,'g'],['lime',2,'pc'],['salt',null,'']],
  s:{fr:["Rincez les bichiques à l'eau claire avec une extrême douceur : ce sont des alevins de deux centimètres qui s'écrasent entre les doigts.","Ne les videz pas et ne les étêtez pas — on les mange entiers, c'est tout l'intérêt.","Faites le massalé de base : oignons fondus, ail, gingembre, curcuma et tomates, réduits vingt minutes.","Ajoutez les bichiques en une seule fois et ne remuez plus du tout ; secouez la casserole si nécessaire.","Cinq minutes suffisent. Trop cuits, ils se défont en bouillie et le plat perd sa raison d'être."],
     en:["Rinse the bichiques in clear water with extreme gentleness: they are two-centimetre fry that crush between the fingers.","Do not gut or behead them — they are eaten whole, and that is the whole point.","Make the base massalé: melted onions, garlic, ginger, turmeric and tomatoes, reduced for twenty minutes.","Add the bichiques all at once and do not stir at all; shake the pan if you must.","Five minutes is enough. Overcooked, they collapse into mush and the dish loses its reason to exist."]} },

{ id:'rougail-dakatine', c:'af', lat:-21.171, lon:55.288, base:6, prep:20, cook:0, diff:1, tags:['veg','fresh','fast'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#e07a6a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Rougail dakatine',en:'Peanut rougail'},
  p:{fr:'Saint-Leu, La Réunion',en:'Saint-Leu, Réunion'},
  d:{fr:"Un condiment de pâte d'arachide, tomate et piment, servi à côté du plat. Dakatine est une marque de beurre de cacahuète devenue nom commun à La Réunion, comme frigidaire ailleurs : personne n'appelle plus cela autrement.",
     en:"A condiment of peanut paste, tomato and chilli, served alongside the main dish. Dakatine is a peanut butter brand that became a common noun on Réunion, as hoover did elsewhere: no one calls it anything else now."},
  i:[['peanut_butter',200,'g'],['tomato',300,'g'],['onion',2,'pc'],['chili_pepper',4,'pc'],['ginger',20,'g'],['garlic',3,'clove'],['scallion',1,'bunch'],['lime',2,'pc'],['sunflower_oil',40,'ml'],['salt',null,'']],
  s:{fr:["Employez une pâte d'arachide non sucrée : les beurres de cacahuète sucrés donnent un condiment écœurant qui ne se marie à rien.","Pilez au mortier le piment, le sel et le gingembre jusqu'à obtenir une pâte lisse — c'est l'ordre qui compte, le sel sert d'abrasif.","Ajoutez l'ail puis l'oignon, en continuant de piler, et enfin les tomates épépinées.","Incorporez la pâte d'arachide peu à peu, en détendant à l'eau tiède jusqu'à la consistance d'une crème épaisse.","Rectifiez au citron vert et laissez reposer une heure. Se sert froid, en petite quantité, à côté d'un carry."],
     en:["Use unsweetened peanut paste: sweetened peanut butters give a cloying condiment that goes with nothing.","Pound the chilli, salt and ginger in a mortar to a smooth paste — the order matters, the salt acts as an abrasive.","Add the garlic then the onion, continuing to pound, and finally the seeded tomatoes.","Work in the peanut paste little by little, loosening with warm water to the consistency of a thick cream.","Adjust with lime and rest an hour. Served cold, in small quantity, beside a curry."]} },

{ id:'massale-cabri', c:'af', lat:-21.286, lon:55.412, base:6, prep:60, cook:100, diff:2, tags:['lamb','stew','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e8a032','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Massalé de cabri',en:'Goat massalé'},
  p:{fr:'Saint-Louis, La Réunion',en:'Saint-Louis, Réunion'},
  d:{fr:"Du cabri mijoté au massalé, mélange d'épices grillées et moulues à la demande. Le massalé réunionnais se distingue du curry par la coriandre grillée qui y domine, et chaque famille fait moudre le sien au moulin du quartier.",
     en:"Goat stewed with massalé, a blend of spices toasted and ground to order. Réunion massalé differs from curry in the toasted coriander that dominates it, and each family has its own ground at the neighbourhood mill."},
  i:[['goat_shoulder',1.5,'kg'],['coriander_seeds',30,'g'],['cumin',15,'g'],['fennel_seed',10,'g'],['mustard_seeds',8,'g'],['turmeric',15,'g'],['onion',4,'pc'],['garlic',10,'clove'],['ginger',40,'g'],['tomato',400,'g'],['thyme',1,'bunch'],['chili_pepper',3,'pc'],['sunflower_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Grillez à sec les graines de coriandre, de cumin, de fenouil et de moutarde jusqu'à ce qu'elles crépitent et embaument, puis moulez-les.","Le grillage est ce qui fait le massalé : les mêmes épices non grillées donnent un curry ordinaire.","Faites mariner le cabri deux heures avec la moitié du massalé, l'ail et le gingembre pilés.","Faites dorer la viande, ajoutez les oignons fondus, le reste du massalé et les tomates, puis mouillez à hauteur.","Laissez mijoter une heure et demie à couvert, très doucement. Servez avec riz, grains et rougail."],
     en:["Dry-toast the coriander, cumin, fennel and mustard seeds until they crackle and fill the room, then grind them.","The toasting is what makes massalé: the same spices untoasted give an ordinary curry.","Marinate the goat two hours with half the massalé and the crushed garlic and ginger.","Brown the meat, add the softened onions, the rest of the massalé and the tomatoes, then moisten to cover.","Simmer an hour and a half covered, very gently. Serve with rice, pulses and rougail."]} },

{ id:'mataba', c:'af', lat:-12.780, lon:45.228, base:6, prep:120, cook:90, diff:2, tags:['veg','slow','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#2a3a1a','#4f6f3a','#f4f0e6','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Mataba',en:'Mataba'},
  p:{fr:'Mamoudzou, Mayotte',en:'Mamoudzou, Mayotte'},
  d:{fr:"Des feuilles de manioc pilées et mijotées au lait de coco, plat quotidien de Mayotte. Comme au Brésil et en Afrique centrale, le pilage et la longue cuisson sont ce qui rend la feuille comestible : crue, elle est toxique.",
     en:"Cassava leaves pounded and stewed in coconut milk, the everyday dish of Mayotte. As in Brazil and central Africa, the pounding and long cooking are what make the leaf edible: raw, it is toxic."},
  i:[['cassava_leaves',1,'kg'],['coconut_milk',600,'ml'],['dried_fish',300,'g'],['onion',2,'pc'],['garlic',6,'clove'],['tomato',200,'g'],['chili_pepper',2,'pc'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Retirez les tiges et les nervures dures, puis pilez les feuilles au mortier jusqu'à obtenir une pâte verte homogène.","Le pilage n'est pas seulement une texture : il rompt les cellules et libère l'enzyme qui neutralise les composés cyanogènes à la cuisson.","Faites bouillir la pâte à l'eau une bonne heure, en écumant, avant d'ajouter quoi que ce soit d'autre.","Ajoutez le poisson séché dessalé, les tomates et le lait de coco, et laissez encore trente minutes.","La mataba est prête quand elle nappe la cuillère et a perdu toute amertume. Servez avec du riz."],
     en:["Remove the stems and tough ribs, then pound the leaves in a mortar to a uniform green paste.","The pounding is not just texture: it ruptures the cells and releases the enzyme that neutralises the cyanogenic compounds during cooking.","Boil the paste in water for a good hour, skimming, before adding anything else.","Add the desalted dried fish, tomatoes and coconut milk, and give it another thirty minutes.","Mataba is ready when it coats the spoon and has lost all bitterness. Serve with rice."]} },

{ id:'pilao-mahorais', c:'af', lat:-12.789, lon:45.267, base:8, prep:40, cook:60, diff:2, tags:['rice','poultry','festive'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#c9924a','#e8c46a','#8f5a3a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Pilao',en:'Pilao'},
  p:{fr:'Dzaoudzi, Mayotte',en:'Dzaoudzi, Mayotte'},
  d:{fr:"Un riz parfumé aux épices et à la viande, servi aux grands mariages mahorais. Le manzaraka, le mariage traditionnel, dure plusieurs jours et le pilao s'y cuit en marmites de cent litres, pour des villages entiers.",
     en:"Rice scented with spices and meat, served at Mahoran grand weddings. The manzaraka, the traditional wedding, lasts several days and pilao is cooked there in hundred-litre pots, for whole villages."},
  i:[['chicken',1.5,'kg'],['long_grain_rice',700,'g'],['onion',4,'pc'],['garlic',10,'clove'],['ginger',40,'g'],['cinnamon_stick',3,'pc'],['cardamom',10,'pc'],['clove',10,'pc'],['cumin',10,'g'],['black_peppercorns',10,'g'],['tomato',300,'g'],['sunflower_oil',100,'ml'],['salt',null,'']],
  s:{fr:["Faites brunir les oignons émincés très longuement dans l'huile, vingt minutes, jusqu'à ce qu'ils soient franchement bruns.","C'est cette caramélisation poussée qui donne au pilao sa couleur et sa profondeur ; des oignons blonds donnent un riz pâle et fade.","Ajoutez les épices entières et laissez-les crépiter trente secondes avant de mettre la viande.","Faites dorer le poulet, mouillez, laissez cuire quarante minutes, puis retirez la viande et mesurez le bouillon.","Cuisez le riz dans ce bouillon, un volume et demi pour un, vingt minutes à couvert, en remettant la viande sur le dessus."],
     en:["Brown the sliced onions at great length in the oil, twenty minutes, until they are frankly brown.","That deep caramelisation gives pilao its colour and depth; pale gold onions give a pallid, flat rice.","Add the whole spices and let them crackle thirty seconds before the meat goes in.","Brown the chicken, moisten, cook forty minutes, then remove the meat and measure the broth.","Cook the rice in that broth, one and a half parts to one, twenty minutes covered, with the meat replaced on top."]} },

{ id:'mkatra-foutra', c:'af', lat:-12.851, lon:45.099, base:8, prep:120, cook:20, diff:2, tags:['bake','comfort','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#f2dfa8','#e8c46a','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Mkatra foutra',en:'Mkatra foutra'},
  p:{fr:'Sada, Mayotte',en:'Sada, Mayotte'},
  d:{fr:"Un pain plat au lait de coco, cuit à la poêle et parsemé de sésame. Il accompagne le thé du matin et se déchire à la main ; sa pâte contient de la semoule de riz, qui lui donne un grain particulier qu'aucune farine de blé ne reproduit.",
     en:"A flatbread with coconut milk, cooked in a pan and scattered with sesame. It accompanies morning tea and is torn by hand; its dough contains rice semolina, which gives a particular grain no wheat flour reproduces."},
  i:[['rice_flour',300,'g'],['flour',200,'g'],['coconut_milk',400,'ml'],['fresh_yeast',15,'g'],['sugar',60,'g'],['egg',2,'pc'],['sesame_seeds',40,'g'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait de coco tiède avec le sucre et attendez qu'elle mousse, quinze minutes.","Mêlez les deux farines et versez le liquide en fouettant : la pâte doit rester coulante, comme une pâte à crêpes épaisse.","Laissez lever une heure et demie dans un endroit chaud, sans y toucher — elle se couvre de bulles.","Versez une louche dans une poêle beurrée à feu doux, couvrez et laissez cuire huit minutes sans retourner.","Parsemez de sésame en cours de cuisson. Le dessous doit dorer, le dessus rester pâle et alvéolé."],
     en:["Slake the yeast in warm coconut milk with the sugar and wait fifteen minutes for it to froth.","Mix the two flours and pour in the liquid, whisking: the batter should stay pourable, like a thick pancake batter.","Let it rise an hour and a half somewhere warm, untouched — it covers itself in bubbles.","Pour a ladleful into a buttered pan over low heat, cover and cook eight minutes without turning.","Scatter sesame during cooking. The underside should brown, the top stay pale and honeycombed."]} },

{ id:'mkatra-sinia', c:'af', lat:-12.930, lon:45.153, base:8, prep:150, cook:40, diff:2, tags:['bake','sweet','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Mkatra sinia',en:'Mkatra sinia'},
  p:{fr:'Chirongui, Mayotte',en:'Chirongui, Mayotte'},
  d:{fr:"Un gâteau de riz au lait de coco cuit dans un grand plat rond, le sinia. Il se prépare pour les fêtes religieuses et se découpe en losanges ; la pâte fermente une nuit, ce qui lui donne une légère acidité et une mie très aérée.",
     en:"A rice cake with coconut milk baked in a large round dish, the sinia. It is made for religious feasts and cut into diamonds; the batter ferments overnight, which gives it a slight acidity and a very open crumb."},
  i:[['rice_flour',500,'g'],['coconut_milk',700,'ml'],['fresh_yeast',20,'g'],['sugar',200,'g'],['egg',3,'pc'],['cardamom',8,'pc'],['vanilla',1,'pc'],['sesame_seeds',40,'g'],['salt',null,'']],
  s:{fr:["Délayez la farine de riz dans le lait de coco tiède avec la levure et le sucre, et fouettez jusqu'à obtenir une pâte lisse.","Laissez fermenter huit heures à couvert, à température ambiante : c'est cette longue fermentation qui donne le goût, et l'écourter donne un gâteau plat et sourd.","Ajoutez les œufs battus, la cardamome pilée et la vanille juste avant la cuisson.","Versez dans un grand plat beurré, sur trois centimètres d'épaisseur, et parsemez de sésame.","Cuisez 40 minutes à 180 °C. Le gâteau doit être doré et sec en surface, moelleux au centre. Se découpe en losanges."],
     en:["Slake the rice flour in warm coconut milk with the yeast and sugar, and whisk to a smooth batter.","Ferment eight hours covered at room temperature: that long fermentation gives the flavour, and shortening it gives a flat, dull cake.","Add the beaten eggs, crushed cardamom and vanilla just before baking.","Pour into a large buttered dish, three centimetres deep, and scatter with sesame.","Bake 40 minutes at 180°C. It should be golden and dry on the surface, moist at the centre. Cut into diamonds."]} }
,

{ id:'brochettes-de-zebu', c:'af', lat:-12.784, lon:45.232, base:6, prep:120, cook:15, diff:1, tags:['beef','grill','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'skewer',food:['#8f4a3a','#c9924a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Brochettes de zébu',en:'Zebu skewers'},
  p:{fr:'Marché de Mamoudzou, Mayotte',en:'Mamoudzou market, Mayotte'},
  d:{fr:"Des dés de zébu marinés aux épices et grillés au charbon, vendus le soir au marché. Le zébu mahorais vit en liberté et sa viande est ferme et maigre : la marinade longue n'est pas un raffinement mais une nécessité.",
     en:"Cubes of zebu marinated in spices and grilled over charcoal, sold in the evening at the market. Mahoran zebu roams free and its meat is firm and lean: the long marinade is not a refinement but a necessity."},
  i:[['beef_rump',1,'kg'],['garlic',8,'clove'],['ginger',40,'g'],['turmeric',10,'g'],['cumin',10,'g'],['curry_powder',15,'g'],['lime',4,'pc'],['sunflower_oil',80,'ml'],['onion',2,'pc'],['chili_pepper',2,'pc'],['salt',null,'']],
  s:{fr:["Coupez la viande en dés de deux centimètres en travers de la fibre : dans le sens de la fibre, le zébu reste coriace même mariné.","Pilez l'ail, le gingembre, le piment et les épices avec le citron vert et l'huile jusqu'à obtenir une pâte.","Faites mariner deux heures au moins, quatre de préférence, en massant la viande pour faire pénétrer.","Enfilez sur des brochettes en serrant les morceaux — espacés, ils sèchent au lieu de rester juteux.","Grillez sur des braises vives, trois minutes par face, en badigeonnant de marinade à chaque retournement."],
     en:["Cut the meat into two-centimetre cubes across the grain: with the grain, zebu stays tough even marinated.","Pound the garlic, ginger, chilli and spices with the lime and oil to a paste.","Marinate at least two hours, four for preference, massaging the meat to help it penetrate.","Thread onto skewers, packing the pieces close — spaced out, they dry instead of staying juicy.","Grill over hot coals, three minutes a side, brushing with marinade at each turn."]} },

{ id:'kakamkou', c:'af', lat:-12.905, lon:45.083, base:6, prep:40, cook:60, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#2c3440',plate:'#f0e4c8',style:'fish',food:['#f4f0e6','#e8c46a','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kakamkou',en:'Kakamkou'},
  p:{fr:'Bouéni, Mayotte',en:'Bouéni, Mayotte'},
  d:{fr:"Un poisson mijoté au lait de coco avec des bananes vertes et du manioc. C'est le plat de la côte ouest de Mayotte, où les pirogues rentrent en fin de matinée : le poisson y est cuit dans l'heure qui suit son débarquement.",
     en:"Fish stewed in coconut milk with green bananas and cassava. It is the dish of Mayotte's west coast, where the pirogues come in late morning: the fish is cooked within an hour of landing."},
  i:[['white_fish',1.2,'kg'],['coconut_milk',600,'ml'],['green_banana',6,'pc'],['cassava',600,'g'],['onion',2,'pc'],['garlic',6,'clove'],['ginger',30,'g'],['tomato',300,'g'],['chili_pepper',2,'pc'],['lime',3,'pc'],['salt',null,'']],
  s:{fr:["Pelez les bananes vertes sous l'eau et frottez-vous les mains d'huile : leur latex tache la peau d'un brun qui tient plusieurs jours.","Faites cuire les bananes et le manioc vingt minutes à l'eau salée avant d'ajouter le reste — ils sont bien plus longs que le poisson.","Faites revenir oignon, ail, gingembre et tomate, puis versez le lait de coco.","Ne le faites jamais bouillir : à gros bouillons il tranche et l'huile remonte en surface.","Ajoutez les darnes de poisson et laissez pocher dix minutes à frémissement. Citron vert au moment de servir."],
     en:["Peel the green bananas under water and oil your hands: their latex stains the skin a brown that lasts days.","Cook the bananas and cassava twenty minutes in salted water before adding anything else — they take far longer than the fish.","Fry onion, garlic, ginger and tomato, then pour in the coconut milk.","Never let it boil: at a rolling boil it splits and the oil rises to the surface.","Add the fish steaks and poach ten minutes at a tremble. Lime as you serve."]} },

{ id:'morue-a-la-saint-pierraise', c:'na', lat:47.095, lon:-56.383, base:6, prep:720, cook:50, diff:2, tags:['sea','bake','comfort'],
  art:{v:'plate',bg:'#2c3440',plate:'#f0e4c8',style:'fish',food:['#f4f0e6','#e8c46a','#f0e8d0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Morue à la saint-pierraise',en:'Saint-Pierre-style cod'},
  p:{fr:'Miquelon, Saint-Pierre-et-Miquelon',en:'Miquelon, Saint-Pierre and Miquelon'},
  d:{fr:"De la morue dessalée gratinée à la crème, aux pommes de terre et aux oignons. L'archipel a vécu de la morue pendant quatre siècles ; le moratoire canadien de 1992 a mis fin à la pêche industrielle, et la recette est devenue un souvenir autant qu'un plat.",
     en:"Desalted cod baked with cream, potatoes and onions. The archipelago lived on cod for four centuries; the Canadian moratorium of 1992 ended industrial fishing, and the recipe has become a memory as much as a dish."},
  i:[['salt_cod',800,'g'],['potato',1,'kg'],['onion',4,'pc'],['heavy_cream',400,'ml'],['whole_milk',300,'ml'],['butter',100,'g'],['gruyere_cheese',150,'g'],['parsley',1,'bunch'],['bay_leaf',2,'pc'],['nutmeg',3,'g'],['pepper',null,'']],
  s:{fr:["Dessalez la morue vingt-quatre heures au réfrigérateur, peau vers le haut, en changeant l'eau cinq fois.","La peau vers le haut n'est pas un détail : le sel descend, et posée à l'envers la morue se dessale bien plus lentement.","Pochez-la dix minutes dans du lait aromatisé au laurier, puis effeuillez-la en gros morceaux.","Faites fondre les oignons au beurre sans les colorer et cuisez les pommes de terre en rondelles à demi.","Montez en couches, nappez de crème, couvrez de gruyère et gratinez 35 minutes à 190 °C."],
     en:["Desalt the cod twenty-four hours in the refrigerator, skin up, changing the water five times.","Skin up is not a detail: salt sinks, and laid the other way the cod desalts far more slowly.","Poach it ten minutes in bay-scented milk, then flake it into large pieces.","Melt the onions in butter without colouring them and half-cook the sliced potatoes.","Build in layers, coat with cream, cover with gruyère and bake 35 minutes at 190°C."]} },

{ id:'beignets-de-moules', c:'na', lat:46.775, lon:-56.155, base:6, prep:40, cook:20, diff:2, tags:['sea','fry','fast'],
  art:{v:'board',bg:'#2c3440',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Beignets de moules',en:'Mussel fritters'},
  p:{fr:'Île aux Marins, Saint-Pierre-et-Miquelon',en:'Île aux Marins, Saint-Pierre and Miquelon'},
  d:{fr:"Des moules de l'archipel enrobées de pâte et frites, servies à l'apéritif. Les moules de Saint-Pierre poussent dans une eau à six degrés : elles grandissent lentement et leur chair est plus dense et plus iodée que celle des moules de l'Atlantique tempéré.",
     en:"Archipelago mussels coated in batter and fried, served as an appetiser. Saint-Pierre mussels grow in water at six degrees: they grow slowly and their flesh is denser and more briny than that of temperate Atlantic mussels."},
  i:[['mussels',1.5,'kg'],['flour',250,'g'],['egg',3,'pc'],['beer',200,'ml'],['baking_powder',6,'g'],['white_wine',200,'ml'],['shallot',3,'pc'],['parsley',1,'bunch'],['frying_oil',1,'l'],['lemon',2,'pc'],['pepper',null,'']],
  s:{fr:["Faites ouvrir les moules au vin blanc avec les échalotes, deux minutes à peine, et retirez-les dès qu'elles s'entrebâillent.","Décoquillez-les et laissez-les refroidir sur un linge : humides, elles font glisser la pâte et le beignet reste nu.","Préparez une pâte à la bière et laissez-la reposer une heure — le gaz de la bière la rend légère et croustillante.","N'ajoutez pas de sel : les moules en apportent assez, et la pâte salée dessèche à la friture.","Trempez et frites à 180 °C, deux minutes, jusqu'à ce que les beignets remontent et dorent. Servez avec du citron."],
     en:["Open the mussels in white wine with the shallots, barely two minutes, and take them out as soon as they gape.","Shell them and cool them on a cloth: damp, they make the batter slide off and the fritter comes out bare.","Make a beer batter and rest it an hour — the gas in the beer makes it light and crisp.","Add no salt: the mussels bring enough, and salted batter dries out in the fryer.","Dip and fry at 180°C for two minutes, until the fritters rise and colour. Serve with lemon."]} },

{ id:'pua-roti-tahitien', c:'oc', lat:-17.535, lon:-149.570, base:12, prep:180, cook:240, diff:3, tags:['pork','slow','festive'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'grill',food:['#8f4a3a','#c9754a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pua roti au four tahitien',en:'Pua roti in the Tahitian oven'},
  p:{fr:'Tahiti, Polynésie française',en:'Tahiti, French Polynesia'},
  d:{fr:"Un cochon entier cuit dans l'ahima'a, le four enterré tahitien, sur des pierres volcaniques brûlantes. La pierre volcanique poreuse retient la chaleur des heures sans éclater ; toute autre pierre exploserait sous l'effet de la vapeur emprisonnée.",
     en:"A whole pig cooked in the ahima'a, the Tahitian earth oven, on scalding volcanic stones. Porous volcanic rock holds heat for hours without shattering; any other stone would explode from the trapped steam."},
  i:[['pork_shoulder',6,'kg'],['coarse_salt',200,'g'],['garlic',15,'clove'],['ginger',60,'g'],['banana_leaf',30,'pc'],['taro_root',2,'kg'],['sweet_potato',2,'kg'],['breadfruit',2,'pc'],['coconut_milk',500,'ml'],['pepper',null,'']],
  s:{fr:["Creusez une fosse d'un mètre, remplissez-la de bois et de pierres volcaniques, et laissez brûler trois heures.","Les pierres doivent devenir rouges : c'est leur chaleur accumulée qui cuit, le feu étant éteint avant qu'on enfourne.","Frottez le cochon de sel, d'ail et de gingembre, et laissez-le reposer une nuit.","Étalez des feuilles de bananier sur les pierres, posez le cochon et les tubercules, couvrez de feuilles puis de sacs mouillés et de terre.","Quatre heures plus tard, ouvrez. La viande se détache d'elle-même ; servez avec du lait de coco frais."],
     en:["Dig a metre-deep pit, fill it with wood and volcanic stones, and let it burn for three hours.","The stones must glow red: it is their stored heat that cooks, the fire being out before the food goes in.","Rub the pig with salt, garlic and ginger, and leave it overnight.","Spread banana leaves on the stones, lay in the pig and the root vegetables, cover with leaves then wet sacking and earth.","Four hours later, open it. The meat falls apart by itself; serve with fresh coconut milk."]} },

{ id:'firifiri', c:'oc', lat:-17.540, lon:-149.566, base:8, prep:120, cook:20, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Firifiri',en:'Firifiri'},
  p:{fr:'Papeete, Polynésie française',en:'Papeete, French Polynesia'},
  d:{fr:"Un beignet en forme de huit, au lait de coco, vendu au petit matin sur les marchés. La forme n'est pas décorative : elle double la longueur de croûte pour une même quantité de pâte, et le beignet cuit plus vite et plus régulièrement.",
     en:"A figure-of-eight doughnut with coconut milk, sold at dawn in the markets. The shape is not decorative: it doubles the length of crust for the same quantity of dough, and the doughnut cooks faster and more evenly."},
  i:[['flour',500,'g'],['coconut_milk',250,'ml'],['fresh_yeast',20,'g'],['sugar',120,'g'],['egg',2,'pc'],['butter',60,'g'],['vanilla',1,'pc'],['frying_oil',1.5,'l'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait de coco tiède avec une cuillerée de sucre et attendez qu'elle mousse.","Pétrissez avec la farine, les œufs, le beurre et la vanille dix minutes, jusqu'à ce que la pâte devienne souple et non collante.","Laissez lever une heure et demie, puis roulez des boudins de vingt centimètres et croisez-les en huit.","Faites lever une seconde fois trente minutes sur le plan de travail fariné, sans les manipuler ensuite.","Frites à 170 °C, deux minutes par face. Roulez-les tièdes dans le sucre et mangez-les dans l'heure."],
     en:["Slake the yeast in warm coconut milk with a spoonful of sugar and wait for it to froth.","Knead with the flour, eggs, butter and vanilla for ten minutes, until the dough turns supple and stops sticking.","Rise for an hour and a half, then roll twenty-centimetre ropes and cross them into figures of eight.","Prove a second time for thirty minutes on the floured worktop, without handling them afterwards.","Fry at 170°C, two minutes a side. Roll them warm in sugar and eat them within the hour."]} },

{ id:'poe-tarua', c:'oc', lat:-16.500, lon:-151.741, base:8, prep:40, cook:60, diff:2, tags:['sweet','fruit','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#e8a032','#c9754a','#f4f0e6','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Poe tarua',en:'Poe tarua'},
  p:{fr:'Bora Bora, Polynésie française',en:'Bora Bora, French Polynesia'},
  d:{fr:"Un pudding de fruits et d'amidon de manioc, cuit en feuille et nappé de lait de coco. Le poe se décline selon les fruits de saison — banane, papaye, citrouille, taro — et se mange tiède, à la cuillère, arrosé de lait de coco pressé le jour même.",
     en:"A pudding of fruit and cassava starch, cooked in leaves and topped with coconut milk. Poe varies with the season's fruit — banana, papaya, pumpkin, taro — and is eaten warm, with a spoon, doused in coconut milk pressed the same day."},
  i:[['taro_root',800,'g'],['banana',4,'pc'],['tapioca_starch',200,'g'],['sugar',150,'g'],['coconut_milk',500,'ml'],['vanilla',1,'pc'],['banana_leaf',8,'pc'],['lime',1,'pc']],
  s:{fr:["Faites cuire le taro à l'eau jusqu'à ce qu'il s'écrase, et manipulez-le avec des gants : cru, il irrite fortement la peau.","Écrasez-le avec les bananes mûres et le sucre, en purée épaisse et sans grumeaux.","Incorporez l'amidon de manioc peu à peu : c'est lui qui fait prendre le poe, et il en faut assez pour que la pâte se tienne à la cuillère.","Étalez sur des feuilles de bananier passées à la flamme et cuisez une heure à la vapeur ou au four doux.","Laissez tiédir, découpez en carrés et nappez de lait de coco frais, jamais chauffé."],
     en:["Boil the taro until it crushes, and handle it with gloves: raw, it strongly irritates the skin.","Mash it with the ripe bananas and sugar, to a thick, lump-free purée.","Work in the cassava starch little by little: it is what sets the poe, and there must be enough for the paste to hold on a spoon.","Spread on banana leaves passed through a flame and cook an hour, steamed or in a low oven.","Cool to warm, cut into squares and top with fresh coconut milk, never heated."]} },

{ id:'chevrettes-vanille', c:'oc', lat:-17.537, lon:-149.830, base:4, prep:30, cook:20, diff:2, tags:['sea','fast','festive'],
  art:{v:'plate',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#e07a6a','#e8c46a','#f4f0e6','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Chevrettes à la vanille',en:'Prawns in vanilla'},
  p:{fr:'Moorea, Polynésie française',en:'Moorea, French Polynesia'},
  d:{fr:"Des crevettes d'eau douce à la crème de coco et à la vanille de Tahiti. La vanille tahitensis n'est pas la même espèce que la vanille de Madagascar : plus florale et moins boisée, elle supporte les plats salés là où l'autre les écrase.",
     en:"Freshwater prawns in coconut cream with Tahitian vanilla. Vanilla tahitensis is not the same species as Madagascar vanilla: more floral and less woody, it stands up to savoury dishes where the other overwhelms them."},
  i:[['river_prawns',800,'g'],['vanilla',3,'pc'],['coconut_milk',400,'ml'],['heavy_cream',150,'ml'],['shallot',3,'pc'],['garlic',4,'clove'],['white_wine',150,'ml'],['butter',60,'g'],['lime',2,'pc'],['long_grain_rice',300,'g'],['pepper',null,'']],
  s:{fr:["Décortiquez les chevrettes en gardant les têtes et les carapaces, et faites-les revenir à part pour en tirer un fumet.","Fendez les gousses de vanille et grattez les graines ; faites infuser les gousses vides dans le fumet vingt minutes.","Faites suer les échalotes au beurre, déglacez au vin blanc et ajoutez le fumet filtré, puis réduisez de moitié.","Versez le lait de coco et la crème, ajoutez les graines de vanille et laissez épaissir dix minutes sans bouillir.","Jetez les chevrettes dans la sauce et comptez trois minutes exactement. Au-delà, elles deviennent caoutchouteuses."],
     en:["Shell the prawns keeping the heads and shells, and fry them separately to draw a stock.","Split the vanilla pods and scrape out the seeds; infuse the empty pods in the stock for twenty minutes.","Sweat the shallots in butter, deglaze with white wine and add the strained stock, then reduce by half.","Pour in the coconut milk and cream, add the vanilla seeds and thicken ten minutes without boiling.","Drop the prawns into the sauce and give them exactly three minutes. Beyond that they turn rubbery."]} }
,

{ id:'salade-de-benitiers', c:'oc', lat:-22.617, lon:167.483, base:4, prep:40, cook:0, diff:1, tags:['sea','fresh','fast'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4ead4',style:'salad',food:['#f4f0e6','#7fae5a','#e07a6a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Salade de bénitiers',en:'Giant clam salad'},
  p:{fr:'Île des Pins, Nouvelle-Calédonie',en:'Isle of Pines, New Caledonia'},
  d:{fr:"Du bénitier cru coupé fin, mariné au citron vert et au lait de coco. Le bénitier est un coquillage géant qui vit en symbiose avec des algues logées dans son manteau : il tire d'elles une part de sa nourriture, comme un corail.",
     en:"Raw giant clam cut fine, marinated in lime and coconut milk. The giant clam lives in symbiosis with algae lodged in its mantle: it draws part of its food from them, like a coral."},
  i:[['giant_clam',600,'g'],['lime',8,'pc'],['coconut_milk',300,'ml'],['onion',2,'pc'],['tomato',300,'g'],['cucumber',1,'pc'],['scallion',1,'bunch'],['chili_pepper',1,'pc'],['salt',null,'']],
  s:{fr:["N'employez que du bénitier vivant, acheté le jour même : cru, il ne pardonne aucune approximation de fraîcheur.","Détachez le muscle et retirez le manteau coloré, plus ferme et amer, puis rincez à l'eau de mer ou à l'eau salée.","Coupez en lamelles très fines en travers de la fibre — épaisses, elles restent élastiques quel que soit le temps de marinade.","Faites mariner vingt minutes au citron vert seulement, jusqu'à ce que la chair blanchisse et raffermisse.","Ajoutez ensuite le lait de coco et les légumes, et servez aussitôt. Marinée plus longtemps, la chair durcit."],
     en:["Use only live clam bought the same day: raw, it forgives no approximation of freshness.","Detach the muscle and remove the coloured mantle, firmer and bitter, then rinse in seawater or salted water.","Cut into very thin slices across the grain — thick, they stay rubbery however long they marinate.","Marinate twenty minutes in lime alone, until the flesh whitens and firms.","Then add the coconut milk and vegetables, and serve at once. Marinated longer, the flesh hardens."]} },

{ id:'cerf-saute-caledonien', c:'oc', lat:-21.566, lon:165.494, base:6, prep:60, cook:100, diff:2, tags:['stew','slow','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#5a3020','#8f4a3a','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Cerf sauté',en:'Sautéed venison'},
  p:{fr:'Bourail, Nouvelle-Calédonie',en:'Bourail, New Caledonia'},
  d:{fr:"Du cerf rusa mijoté au vin et aux aromates, plat des broussards calédoniens. Le cerf rusa a été introduit de Java en 1870 et s'est multiplié jusqu'à devenir une nuisance : le chasser est un service rendu à la brousse autant qu'un plaisir de table.",
     en:"Rusa deer stewed in wine with aromatics, the dish of the Caledonian bush settlers. Rusa deer were introduced from Java in 1870 and multiplied until they became a pest: hunting them is a service to the bush as much as a pleasure at table."},
  i:[['venison',1.5,'kg'],['red_wine',500,'ml'],['onion',3,'pc'],['carrot',3,'pc'],['garlic',8,'clove'],['bay_leaf',3,'pc'],['thyme',1,'bunch'],['juniper_berries',10,'pc'],['smoked_bacon',150,'g'],['flour',40,'g'],['sweet_potato',800,'g'],['butter',60,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Faites mariner le cerf vingt-quatre heures au vin rouge avec les carottes, les oignons et le genièvre.","Égouttez et épongez soigneusement la viande : mouillée, elle bout au lieu de dorer et la sauce reste grise.","Faites-la saisir par petites quantités dans le gras de lard fondu, puis singez à la farine et laissez-la cuire deux minutes.","Mouillez avec la marinade filtrée, portée à ébullition et écumée au préalable — non bouillie, elle donne un goût cru et âpre.","Laissez mijoter une heure et demie à couvert. Servez avec des patates douces écrasées au beurre."],
     en:["Marinate the venison twenty-four hours in red wine with the carrots, onions and juniper.","Drain and blot the meat thoroughly: wet, it boils instead of browning and the sauce stays grey.","Sear it in small batches in the rendered bacon fat, then dust with flour and cook it two minutes.","Moisten with the strained marinade, boiled and skimmed beforehand — unboiled, it gives a raw, harsh taste.","Simmer an hour and a half covered. Serve with sweet potatoes mashed with butter."]} },

{ id:'gateau-de-manioc-caledonien', c:'oc', lat:-20.912, lon:167.240, base:8, prep:40, cook:70, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#c9754a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Gâteau de manioc',en:'Cassava cake'},
  p:{fr:'Lifou, Nouvelle-Calédonie',en:'Lifou, New Caledonia'},
  d:{fr:"Un gâteau dense de manioc râpé au lait de coco, cuit lentement. Il se prépare dans les tribus des Loyauté pour les fêtes coutumières et se partage en parts épaisses ; sans farine ni levure, il tient tout entier sur l'amidon du manioc.",
     en:"A dense cake of grated cassava with coconut milk, slowly baked. It is made in the Loyalty Islands tribes for customary feasts and shared in thick slices; with no flour and no raising agent, it holds together entirely on cassava starch."},
  i:[['cassava',1.2,'kg'],['coconut_milk',500,'ml'],['sugar',250,'g'],['butter',100,'g'],['egg',3,'pc'],['vanilla',1,'pc'],['coconut',100,'g'],['salt',null,'']],
  s:{fr:["Pelez le manioc et retirez le fil ligneux central, qui reste dur quelle que soit la cuisson.","Râpez-le finement et pressez-le dans un linge pour en extraire l'eau — mais gardez cette eau une heure.","L'amidon se dépose au fond ; jetez l'eau claire et récupérez le dépôt blanc, qui retourne dans la pâte : c'est lui qui lie le gâteau.","Mêlez manioc, amidon, lait de coco, sucre, œufs et beurre fondu, et versez dans un moule beurré.","Cuisez 70 minutes à 170 °C. Le gâteau doit être doré et ferme ; il se tranche mieux le lendemain."],
     en:["Peel the cassava and remove the woody central thread, which stays hard however long it cooks.","Grate it finely and press it in a cloth to extract the water — but keep that water for an hour.","The starch settles at the bottom; pour off the clear water and recover the white deposit, which goes back into the batter: it is what binds the cake.","Mix cassava, starch, coconut milk, sugar, eggs and melted butter, and pour into a buttered tin.","Bake 70 minutes at 170°C. It should be golden and firm; it slices better the next day."]} },

{ id:'kava-wallisien', c:'oc', lat:-13.282, lon:-176.176, base:12, prep:60, cook:0, diff:2, tags:['drink','fresh','festive'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ead4',style:'drink',food:['#8f7a5a','#c9a878','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Kava',en:'Kava'},
  p:{fr:'Mata-Utu, Wallis-et-Futuna',en:'Mata-Utu, Wallis and Futuna'},
  d:{fr:"Une boisson de racine de poivrier pilée et infusée à l'eau froide, bue lors des cérémonies coutumières. Le kava n'est pas alcoolisé : ses kavalactones agissent sur le système nerveux et engourdissent la bouche, sans jamais troubler la parole.",
     en:"A drink of pounded pepper root steeped in cold water, taken at customary ceremonies. Kava is not alcoholic: its kavalactones act on the nervous system and numb the mouth, without ever slurring speech."},
  i:[['kava_root',500,'g'],['water',5,'l']],
  s:{fr:["Employez la racine séchée d'un plant d'au moins quatre ans : plus jeune, elle contient peu de kavalactones et l'effet est nul.","Pilez-la longuement au mortier jusqu'à obtenir une poudre fibreuse et grossière.","Enveloppez-la dans un tissu à mailles serrées et malaxez-la dans l'eau froide, en pressant et relâchant, un quart d'heure durant.","N'employez jamais d'eau chaude : la chaleur dégrade les kavalactones et ne laisse qu'un liquide amer et inerte.","Filtrez, servez dans la coupe cérémonielle et buvez d'un trait. La coupe circule selon un ordre fixé par le rang."],
     en:["Use dried root from a plant at least four years old: younger, it holds few kavalactones and the effect is nil.","Pound it at length in a mortar to a coarse, fibrous powder.","Wrap it in a tight-woven cloth and knead it in cold water, squeezing and releasing, for a good quarter hour.","Never use hot water: heat degrades the kavalactones and leaves only a bitter, inert liquid.","Strain, serve in the ceremonial bowl and drink in one draught. The bowl passes in an order fixed by rank."]} },

{ id:'faikakai-taro-coco', c:'oc', lat:-13.290, lon:-176.185, base:8, prep:40, cook:50, diff:2, tags:['sweet','comfort','fruit'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#c9754a','#f4f0e6','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Faikakai au taro',en:'Taro faikakai'},
  p:{fr:'Wallis, Wallis-et-Futuna',en:'Wallis, Wallis and Futuna'},
  d:{fr:"Des boulettes de taro pochées dans un caramel de lait de coco. Le faikakai est le dessert des dimanches et des fêtes de village dans tout le Pacifique polynésien ; le caramel se fait sans sucre raffiné dans la version ancienne, uniquement à la crème de coco réduite.",
     en:"Taro dumplings poached in a coconut caramel. Faikakai is the Sunday and village-feast dessert throughout Polynesia; in the older version the caramel is made with no refined sugar, only reduced coconut cream."},
  i:[['taro_root',1,'kg'],['coconut_milk',700,'ml'],['brown_sugar',250,'g'],['tapioca_starch',80,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire le taro à l'eau salée quarante minutes et écrasez-le chaud, gants aux mains, en purée lisse.","Incorporez l'amidon de manioc jusqu'à ce que la pâte se roule sans coller aux paumes.","Roulez des boulettes de la taille d'une noix : plus grosses, elles restent crues au cœur et se défont dans le caramel.","Faites réduire le lait de coco et le sucre brun vingt minutes, en remuant, jusqu'à ce qu'il brunisse et nappe la cuillère.","Pochez les boulettes dix minutes dans ce caramel frémissant, à découvert. Servez tiède, dans le caramel."],
     en:["Boil the taro forty minutes in salted water and mash it hot, wearing gloves, to a smooth purée.","Work in the cassava starch until the paste rolls without sticking to your palms.","Roll walnut-sized balls: any larger and they stay raw at the centre and break up in the caramel.","Reduce the coconut milk and brown sugar for twenty minutes, stirring, until it browns and coats the spoon.","Poach the dumplings ten minutes in that simmering caramel, uncovered. Serve warm, in the caramel."]} },

{ id:'accras-de-lambi', c:'na', lat:17.897, lon:-62.850, base:6, prep:90, cook:20, diff:2, tags:['sea','fry','street'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Accras de lambi',en:'Conch accras'},
  p:{fr:'Gustavia, Saint-Barthélemy',en:'Gustavia, Saint Barthélemy'},
  d:{fr:"Des beignets au lambi haché, plus fermes et plus iodés que ceux à la morue. Saint-Barthélemy a été suédoise pendant près d'un siècle, de 1784 à 1878 ; sa cuisine est pourtant restée entièrement créole, sans la moindre trace scandinave.",
     en:"Fritters of chopped conch, firmer and brinier than the salt-cod kind. Saint Barthélemy was Swedish for almost a century, from 1784 to 1878; its cooking nonetheless stayed entirely Creole, without a trace of Scandinavia."},
  i:[['conch',500,'g'],['flour',250,'g'],['egg',2,'pc'],['baking_powder',8,'g'],['whole_milk',150,'ml'],['scallion',1,'bunch'],['garlic',5,'clove'],['thyme',1,'bunch'],['scotch_bonnet',1,'pc'],['lime',3,'pc'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Battez le lambi au maillet puis faites-le cuire une heure à l'eau frémissante : cru, il resterait dur comme du caoutchouc.","Hachez-le au couteau une fois refroidi, gros — c'est un muscle dense qui doit se sentir sous la dent.","Préparez la pâte et laissez-la reposer une heure, le temps que la farine s'hydrate complètement.","Incorporez le lambi, les herbes et le piment juste avant de frire, et goûtez la pâte crue pour le sel.","Frites à 175 °C, trois minutes en retournant. Servez brûlant, avec du citron vert."],
     en:["Beat the conch with a mallet then simmer it an hour: raw, it would stay hard as rubber.","Chop it coarsely by knife once cooled — it is a dense muscle that must be felt under the tooth.","Make the batter and rest it an hour, so the flour hydrates completely.","Fold in the conch, herbs and chilli just before frying, and taste the raw batter for salt.","Fry at 175°C for three minutes, turning. Serve scalding, with lime."]} },

{ id:'court-bouillon-saint-martin', c:'na', lat:18.100, lon:-63.050, base:6, prep:40, cook:35, diff:2, tags:['sea','stew','fresh'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'fish',food:['#e07a6a','#e8a032','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Court-bouillon de poisson',en:'Fish court-bouillon'},
  p:{fr:'Grand-Case, Saint-Martin',en:'Grand-Case, Saint Martin'},
  d:{fr:"Un poisson de récif poché dans un bouillon tomaté relevé au piment et au citron vert. Grand-Case s'est fait une réputation de capitale gastronomique des Antilles avec ses lolos, ces gargotes de bord de plage où le court-bouillon se sert dans des assiettes en carton.",
     en:"Reef fish poached in a tomato broth sharpened with chilli and lime. Grand-Case built a reputation as the Antilles' gastronomic capital on its lolos, beachside shacks where court-bouillon is served on paper plates."},
  i:[['red_snapper',1.4,'kg'],['tomato',500,'g'],['onion',3,'pc'],['garlic',8,'clove'],['scallion',1,'bunch'],['thyme',1,'bunch'],['scotch_bonnet',2,'pc'],['lime',5,'pc'],['olive_oil',80,'ml'],['bell_pepper',1,'pc'],['long_grain_rice',300,'g'],['clove',3,'pc'],['salt',null,'']],
  s:{fr:["Écaillez et videz le poisson, puis entaillez-le en croisillons de chaque côté et frottez-le au citron vert et à l'ail.","Laissez-le mariner une demi-heure au frais : au-delà, le citron commence à cuire la chair en surface et elle se défait ensuite.","Faites revenir les aromates et la tomate dans l'huile jusqu'à obtenir une sauce épaisse, quinze minutes.","Mouillez d'eau bouillante, ajoutez le piment entier non percé et laissez frémir dix minutes.","Couchez le poisson dans le bouillon et pochez douze minutes à découvert, sans le retourner. Servez avec du riz."],
     en:["Scale and gut the fish, then score it in a lattice on both sides and rub it with lime and garlic.","Marinate half an hour in the cold: beyond that, the lime starts cooking the surface and the flesh falls apart later.","Fry the aromatics and tomato in the oil to a thick sauce, fifteen minutes.","Moisten with boiling water, add the whole unpierced chilli and simmer ten minutes.","Lay the fish in the broth and poach twelve minutes uncovered, without turning it. Serve with rice."]} },

{ id:'tarte-coco-saint-martin', c:'na', lat:18.026, lon:-63.045, base:8, prep:60, cook:45, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#f4f0e6','#c9754a'],garnish:'#c9754a'},
  n:{fr:'Tarte à la coco',en:'Coconut tart'},
  p:{fr:'Philipsburg, Saint-Martin',en:'Philipsburg, Sint Maarten'},
  d:{fr:"Une tarte à la crème de coco parfumée à la muscade, servie des deux côtés de l'île. Saint-Martin est partagée entre la France et les Pays-Bas depuis 1648 sans qu'aucune frontière n'ait jamais été matérialisée : la recette circule librement, comme les habitants.",
     en:"A coconut cream tart scented with nutmeg, served on both sides of the island. Saint Martin has been shared between France and the Netherlands since 1648 with no border ever marked on the ground: the recipe circulates as freely as the residents."},
  i:[['flour',300,'g'],['butter',180,'g'],['sugar',220,'g'],['coconut',300,'g'],['coconut_milk',300,'ml'],['egg',4,'pc'],['nutmeg',5,'g'],['vanilla',1,'pc'],['rum',30,'ml'],['salt',null,'']],
  s:{fr:["Sablez la farine, le beurre froid et une cuillerée de sucre, liez à l'eau glacée et laissez reposer une heure au froid.","Foncez le moule, piquez le fond et faites-le cuire à blanc quinze minutes avec des poids — sans cuisson à blanc, la garniture détrempe la pâte.","Faites tiédir le lait de coco avec la vanille et la muscade, puis versez-le sur les œufs battus au sucre, en filet et en fouettant.","Ajoutez la coco râpée et le rhum, et laissez reposer dix minutes que la coco boive le liquide.","Garnissez et cuisez 30 minutes à 170 °C. Le centre doit encore trembler légèrement à la sortie du four."],
     en:["Rub the flour, cold butter and a spoonful of sugar together, bind with iced water and rest an hour in the cold.","Line the tin, prick the base and blind bake fifteen minutes with weights — without blind baking, the filling soaks the pastry.","Warm the coconut milk with the vanilla and nutmeg, then pour it onto the sugar-beaten eggs in a stream, whisking.","Add the grated coconut and rum, and rest ten minutes for the coconut to drink the liquid.","Fill and bake 30 minutes at 170°C. The centre should still tremble slightly as it leaves the oven."]} }
,

{ id:'jocon', c:'na', lat:15.319, lon:-91.471, base:6, prep:40, cook:60, diff:2, tags:['poultry','stew','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#4f6f3a','#7fae5a','#f4f0e6','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Jocón',en:'Jocón'},
  p:{fr:'Huehuetenango, Guatemala',en:'Huehuetenango, Guatemala'},
  d:{fr:"Un poulet mijoté dans une sauce verte de tomatilles, coriandre et graines de courge grillées. Le vert n'est pas une décoration : c'est la couleur d'un des quatre recados mayas, ces sauces de base classées par teinte que la cuisine guatémaltèque distingue depuis l'époque précolombienne.",
     en:"Chicken stewed in a green sauce of tomatillos, coriander and toasted pumpkin seeds. The green is not decoration: it is the colour of one of the four Mayan recados, base sauces classed by hue that Guatemalan cooking has distinguished since pre-Columbian times."},
  i:[['chicken',1.4,'kg'],['tomatillo',600,'g'],['cilantro',2,'bunch'],['pumpkin_seeds',150,'g'],['sesame_seeds',60,'g'],['scallion',1,'bunch'],['garlic',8,'clove'],['corn_tortillas',2,'pc'],['onion',2,'pc'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Pochez le poulet en morceaux dans l'eau salée avec l'oignon et l'ail, quarante minutes, et gardez le bouillon.","Grillez à sec les graines de courge et de sésame jusqu'à ce qu'elles éclatent, puis moulez-les encore tièdes.","Grillez aussi les tomatilles et les cives à sec, à la plancha, jusqu'à ce que la peau noircisse par endroits : c'est ce grillage qui donne la profondeur, et des tomatilles crues donnent une sauce acide et plate.","Mixez tomatilles, coriandre, graines moulues et deux tortillas trempées — la tortilla est le seul épaississant, il n'y a ni farine ni crème.","Versez sur le poulet, ajoutez du bouillon jusqu'à napper et laissez mijoter vingt minutes sans couvrir. Servez avec du riz blanc."],
     en:["Poach the jointed chicken in salted water with the onion and garlic for forty minutes, and keep the broth.","Dry-toast the pumpkin and sesame seeds until they pop, then grind them while still warm.","Dry-char the tomatillos and spring onions on a griddle until the skin blackens in places: that charring gives the depth, and raw tomatillos give a sharp, flat sauce.","Blend tomatillos, coriander, ground seeds and two soaked tortillas — the tortilla is the only thickener, there is no flour and no cream.","Pour over the chicken, add broth to coat and simmer twenty minutes uncovered. Serve with white rice."]} },

{ id:'tamales-colorados', c:'na', lat:14.834, lon:-91.518, base:10, prep:180, cook:180, diff:3, tags:['festive','slow','poultry'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#c9302a','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tamales colorados',en:'Tamales colorados'},
  p:{fr:'Quetzaltenango, Guatemala',en:'Quetzaltenango, Guatemala'},
  d:{fr:"De grands tamales à la pâte de maïs teintée de recado rouge, cuits dans la feuille de bananier. Au Guatemala le tamal du samedi soir est une institution familiale : on en prépare cinquante d'un coup, et la journée entière y passe.",
     en:"Large tamales with corn dough tinted by red recado, cooked in banana leaf. In Guatemala the Saturday night tamal is a family institution: fifty are made at once, and the whole day goes into it."},
  i:[['corn_masa',1.5,'kg'],['lard',400,'g'],['chicken',1.5,'kg'],['ripe_tomato',800,'g'],['guajillo_chili',8,'pc'],['pumpkin_seeds',100,'g'],['sesame_seeds',60,'g'],['bell_pepper',2,'pc'],['olives',150,'g'],['raisins',100,'g'],['banana_leaf',20,'pc'],['chicken_broth',1.5,'l'],['salt',null,'']],
  s:{fr:["Faites griller les piments guajillo à sec quelques secondes par face, puis faites-les tremper vingt minutes dans l'eau chaude.","Grillez tomates, graines et poivrons à la plancha, mixez le tout avec les piments et passez au chinois : le recado doit être parfaitement lisse.","Délayez la masa dans le bouillon chaud et faites-la cuire à feu doux en remuant sans arrêt, quarante minutes, jusqu'à ce qu'elle se décolle du fond.","Cette cuisson préalable de la pâte est ce qui distingue le tamal guatémaltèque du mexicain : elle donne une texture lisse et fondante plutôt que granuleuse.","Passez les feuilles à la flamme, étalez la pâte, garnissez de poulet, de recado, d'olive et de raisin, pliez en paquets et cuisez trois heures à la vapeur."],
     en:["Toast the guajillo chillies dry for a few seconds a side, then soak them twenty minutes in hot water.","Char tomatoes, seeds and peppers on a griddle, blend everything with the chillies and strain: the recado must be perfectly smooth.","Slake the masa in hot broth and cook it over low heat, stirring without pause, for forty minutes, until it pulls from the base.","This pre-cooking of the dough is what sets the Guatemalan tamal apart from the Mexican: it gives a smooth, melting texture rather than a grainy one.","Pass the leaves through a flame, spread the dough, fill with chicken, recado, olive and raisin, fold into parcels and steam three hours."]} },

{ id:'fiambre', c:'na', lat:14.634, lon:-90.507, base:12, prep:480, cook:120, diff:3, tags:['festive','fresh','slow'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'salad',food:['#7fae5a','#e07a6a','#e8c46a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Fiambre',en:'Fiambre'},
  p:{fr:'Guatemala, Guatemala',en:'Guatemala City, Guatemala'},
  d:{fr:"Une salade froide de cinquante ingrédients ou plus, préparée une seule fois par an, pour la Toussaint. Chaque famille garde sa liste et la transmet ; on la mange au cimetière, sur les tombes, et il est entendu qu'on n'en prépare jamais un autre jour de l'année.",
     en:"A cold salad of fifty ingredients or more, made once a year, for All Saints. Each family keeps its own list and passes it down; it is eaten in the cemetery, on the graves, and it is understood that it is never made on any other day."},
  i:[['beetroot',400,'g'],['carrot',400,'g'],['green_beans',300,'g'],['cauliflower',400,'g'],['peas',200,'g'],['pickled_onions',200,'g'],['capers',80,'g'],['olives',200,'g'],['chorizo',300,'g'],['ham',300,'g'],['salami',200,'g'],['sardines',200,'g'],['queso_fresco',300,'g'],['egg',6,'pc'],['white_wine_vinegar',300,'ml'],['olive_oil',200,'ml'],['oregano',10,'g'],['lettuce',12,'pc'],['salt',null,'']],
  s:{fr:["Préparez le caldillo la veille : vinaigre, huile, oignon, câpres, origan et épices, laissé reposer douze heures.","Cuisez chaque légume séparément et à son point exact, puis refroidissez-les et laissez-les mariner à part dans le caldillo.","Séparément est le mot : cuits ensemble, les couleurs déteignent et la betterave rougit tout le plat.","Le lendemain, dressez un lit de laitue et disposez les légumes marinés en couronne, par couleurs.","Couvrez de charcuteries, de fromage, d'œufs durs et de sardines. Se mange froid, jamais réchauffé."],
     en:["Make the caldillo the day before: vinegar, oil, onion, capers, oregano and spices, left to stand twelve hours.","Cook each vegetable separately and to its own exact point, then cool them and marinate them apart in the caldillo.","Separately is the word: cooked together, the colours bleed and the beetroot reddens the whole dish.","Next day, lay a bed of lettuce and arrange the marinated vegetables in a crown, by colour.","Cover with cured meats, cheese, hard-boiled eggs and sardines. Eaten cold, never reheated."]} },

{ id:'hilachas', c:'na', lat:14.628, lon:-90.514, base:6, prep:60, cook:150, diff:2, tags:['beef','stew','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f4a3a','#c9302a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hilachas',en:'Hilachas'},
  p:{fr:'Guatemala, Guatemala',en:'Guatemala City, Guatemala'},
  d:{fr:"Du bœuf effiloché mijoté dans un recado de tomate et de piment, avec pommes de terre et carottes. Hilacha veut dire « fil effiloché » : la viande est déchirée à la main dans le sens de la fibre, jamais coupée, et c'est ce qui lui permet de boire la sauce.",
     en:"Shredded beef stewed in a tomato and chilli recado, with potatoes and carrots. Hilacha means loose thread: the meat is torn by hand along the grain, never cut, and that is what lets it drink up the sauce."},
  i:[['flank_steak',1,'kg'],['ripe_tomato',800,'g'],['tomatillo',300,'g'],['guajillo_chili',4,'pc'],['potato',600,'g'],['carrot',3,'pc'],['onion',2,'pc'],['garlic',8,'clove'],['bay_leaf',3,'pc'],['corn_tortillas',2,'pc'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir le flanchet deux heures avec laurier, oignon et ail, jusqu'à ce qu'il se déchire sans résistance.","Laissez-le tiédir dans son bouillon avant de l'effilocher : sorti brûlant, il sèche en surface et devient impossible à défaire proprement.","Grillez tomates, tomatilles et piments à la plancha jusqu'à ce qu'ils noircissent, puis mixez-les avec une tortilla trempée.","Passez le recado au chinois — les peaux de piment restent en filaments et gâchent la texture.","Réunissez viande, sauce et légumes en dés et laissez mijoter trente minutes. Servez avec riz et tortillas."],
     en:["Boil the flank two hours with bay, onion and garlic, until it tears without resistance.","Let it cool in its broth before shredding: taken out scalding, it dries on the surface and becomes impossible to pull apart cleanly.","Char tomatoes, tomatillos and chillies on a griddle until they blacken, then blend them with a soaked tortilla.","Strain the recado — chilli skins stay as threads and spoil the texture.","Bring meat, sauce and diced vegetables together and simmer thirty minutes. Serve with rice and tortillas."]} },

{ id:'subanik', c:'na', lat:14.786, lon:-90.797, base:8, prep:90, cook:120, diff:3, tags:['festive','slow','stew'],
  art:{v:'leaf',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#c9302a','#8f4a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Subanik',en:'Subanik'},
  p:{fr:'San Martín Jilotepeque, Guatemala',en:'San Martín Jilotepeque, Guatemala'},
  d:{fr:"Trois viandes cuites à la vapeur dans une feuille de mashán, avec un recado de trois piments. C'est un plat cérémoniel kaqchikel réservé aux mariages et aux naissances ; le nom vient d'un verbe maya signifiant cuire à l'étouffée.",
     en:"Three meats steamed in a mashán leaf with a three-chilli recado. It is a Kaqchikel ceremonial dish reserved for weddings and births; the name comes from a Mayan verb meaning to cook smothered."},
  i:[['chicken',600,'g'],['pork_shoulder',600,'g'],['beef_shank',600,'g'],['guajillo_chili',6,'pc'],['pasilla_chili',4,'pc'],['chile_de_arbol',4,'pc'],['ripe_tomato',600,'g'],['tomatillo',300,'g'],['sesame_seeds',80,'g'],['pumpkin_seeds',80,'g'],['banana_leaf',12,'pc'],['garlic',8,'clove'],['onion',2,'pc'],['salt',null,'']],
  s:{fr:["Grillez les trois piments à sec, très brièvement : quelques secondes de trop et ils virent à l'amer, sans retour possible.","Faites-les tremper vingt minutes, puis mixez-les avec les tomates et tomatilles grillées et les graines moulues.","Coupez les trois viandes en morceaux de même taille pour qu'elles cuisent au même rythme.","Tapissez un grand plat de feuilles de bananier, versez viandes et recado, et refermez les feuilles en paquet hermétique.","Cuisez deux heures à la vapeur sans jamais ouvrir. Le paquet retient toute la vapeur des viandes : c'est là toute la technique."],
     en:["Toast the three chillies dry, very briefly: a few seconds too long and they turn bitter, with no way back.","Soak them twenty minutes, then blend them with the charred tomatoes and tomatillos and the ground seeds.","Cut the three meats into pieces of the same size so they cook at the same rate.","Line a large dish with banana leaves, pour in meats and recado, and close the leaves into a sealed parcel.","Steam two hours without ever opening it. The parcel holds all the steam from the meats: that is the whole technique."]} },

{ id:'chiles-rellenos-guatemaltecos', c:'na', lat:14.556, lon:-90.734, base:6, prep:90, cook:30, diff:3, tags:['veg','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#4f6f3a','#e8c46a','#c9302a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Chiles rellenos guatémaltèques',en:'Guatemalan chiles rellenos'},
  p:{fr:'Antigua Guatemala, Guatemala',en:'Antigua Guatemala, Guatemala'},
  d:{fr:"Des poivrons farcis à la viande et aux légumes, enrobés d'œuf battu et frits. La version guatémaltèque se distingue de la mexicaine par la farce : ici ni fromage ni fruits secs, mais un hachis de viande et de légumes marinés au vinaigre.",
     en:"Peppers stuffed with meat and vegetables, coated in beaten egg and fried. The Guatemalan version differs from the Mexican in the filling: no cheese and no dried fruit here, but a hash of meat and vegetables marinated in vinegar."},
  i:[['bell_pepper',6,'pc'],['ground_pork',300,'g'],['ground_beef',300,'g'],['carrot',2,'pc'],['green_beans',150,'g'],['peas',100,'g'],['ripe_tomato',400,'g'],['onion',2,'pc'],['egg',6,'pc'],['flour',100,'g'],['white_wine_vinegar',60,'ml'],['frying_oil',800,'ml'],['bread_roll',6,'pc'],['salt',null,'']],
  s:{fr:["Grillez les poivrons entiers à la flamme jusqu'à ce que la peau cloque, puis enfermez-les dix minutes dans un sac fermé.","La vapeur emprisonnée décolle la peau toute seule ; sans cette étape, la peler revient à déchirer le poivron.","Fendez-les sur un côté, retirez les graines en gardant la tige, et faites-les mariner une heure au vinaigre.","Faites revenir les viandes et les légumes en petits dés, égouttez la farce et laissez-la refroidir avant de garnir.","Montez les blancs en neige, incorporez les jaunes, farinez les poivrons, trempez-les et frites-les à 175 °C en les arrosant."],
     en:["Char the whole peppers over a flame until the skin blisters, then seal them ten minutes in a closed bag.","The trapped steam lifts the skin by itself; without this step, peeling them means tearing them.","Slit them down one side, remove the seeds keeping the stalk, and marinate them an hour in vinegar.","Fry the meats and finely diced vegetables, drain the filling and cool it before stuffing.","Whip the whites, fold in the yolks, flour the peppers, dip them and fry at 175°C, spooning oil over them."]} },

{ id:'rellenitos', c:'na', lat:14.640, lon:-90.512, base:8, prep:90, cook:25, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#8f5a3a','#3a2018','#c9924a','#e8c46a'],garnish:'#c9754a'},
  n:{fr:'Rellenitos',en:'Rellenitos'},
  p:{fr:'Guatemala, Guatemala',en:'Guatemala City, Guatemala'},
  d:{fr:"Des croquettes de banane plantain farcies de purée de haricots noirs sucrée, frites et roulées dans le sucre. L'association du haricot et du sucre déroute les visiteurs ; au Guatemala elle est aussi ordinaire que celle du chocolat et de la noisette ailleurs.",
     en:"Plantain croquettes filled with sweetened black bean purée, fried and rolled in sugar. Pairing beans with sugar puzzles visitors; in Guatemala it is as ordinary as chocolate and hazelnut elsewhere."},
  i:[['plantain',6,'pc'],['black_beans',400,'g'],['sugar',200,'g'],['cinnamon',8,'g'],['dark_chocolate',60,'g'],['lard',60,'g'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Faites bouillir les plantains très mûrs avec la peau vingt minutes, puis pelez-les chauds et écrasez-les en purée ferme.","Choisissez des plantains à la peau noire : jaunes, ils manquent de sucre et la pâte ne se tient pas.","Faites revenir les haricots cuits au saindoux avec le sucre, la cannelle et le chocolat, jusqu'à obtenir une pâte qui se roule.","Laissez refroidir les deux préparations complètement — chaudes, elles collent aux mains et la croquette ne se ferme pas.","Formez des boules de plantain autour de la farce, aplatissez en ovale et frites à 175 °C, trois minutes. Roulez dans le sucre."],
     en:["Boil very ripe plantains in their skins for twenty minutes, then peel them hot and mash to a firm purée.","Choose plantains with black skins: yellow ones lack sugar and the dough will not hold.","Fry the cooked beans in lard with the sugar, cinnamon and chocolate, to a paste that can be rolled.","Cool both preparations completely — warm, they stick to the hands and the croquette will not close.","Form plantain balls around the filling, flatten into ovals and fry at 175°C for three minutes. Roll in sugar."]} },

{ id:'tapado-garifuna', c:'na', lat:15.828, lon:-88.750, base:6, prep:60, cook:50, diff:2, tags:['sea','stew','comfort'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#e8c46a','#7fae5a','#e07a6a'],garnish:'#6fbf8f'},
  n:{fr:'Tapado garífuna',en:'Garífuna tapado'},
  p:{fr:'Livingston, Izabal, Guatemala',en:'Livingston, Izabal, Guatemala'},
  d:{fr:"Une soupe de poisson et de fruits de mer au lait de coco, avec banane verte et manioc. Les Garífunas descendent de naufragés africains et d'Arawaks de Saint-Vincent, déportés au Honduras en 1797 ; leur cuisine est la seule d'Amérique centrale à ignorer le piment et le maïs.",
     en:"A fish and seafood soup in coconut milk with green banana and cassava. The Garífuna descend from African castaways and Arawaks of Saint Vincent, deported to Honduras in 1797; theirs is the only Central American cooking to ignore chilli and corn."},
  i:[['white_fish',800,'g'],['shrimp',300,'g'],['crab_claws',8,'pc'],['coconut_milk',800,'ml'],['green_banana',4,'pc'],['cassava',500,'g'],['plantain',2,'pc'],['onion',2,'pc'],['garlic',6,'clove'],['cilantro',1,'bunch'],['lime',3,'pc'],['bell_pepper',1,'pc'],['salt',null,'']],
  s:{fr:["Râpez la noix de coco fraîche et pressez-la deux fois : la première pression donne le lait épais, la seconde le lait clair.","Cuisez les tubercules et bananes vertes dans le lait clair d'abord — le lait épais tournerait sur une cuisson aussi longue.","Ajoutez le lait épais seulement en fin de cuisson, et ne le laissez jamais bouillir.","Couchez le poisson en darnes et les fruits de mer par-dessus, et pochez dix minutes à frémissement sans remuer.","Citron vert et coriandre hors du feu. Il n'y a pas de piment dans ce plat, et l'ajouter serait le dénaturer."],
     en:["Grate fresh coconut and press it twice: the first pressing gives thick milk, the second thin.","Cook the roots and green bananas in the thin milk first — thick milk would split over so long a cooking.","Add the thick milk only at the end, and never let it boil.","Lay the fish steaks and seafood on top and poach ten minutes at a tremble without stirring.","Lime and coriander off the heat. There is no chilli in this dish, and adding it would distort it."]} },

{ id:'chuchitos', c:'na', lat:14.644, lon:-90.500, base:10, prep:120, cook:75, diff:2, tags:['street','comfort','slow'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9302a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chuchitos',en:'Chuchitos'},
  p:{fr:'Guatemala, Guatemala',en:'Guatemala City, Guatemala'},
  d:{fr:"De petits tamales serrés, cuits dans la feuille de maïs et non de bananier. Ils se vendent le soir dans la rue, à l'unité, enveloppe comprise : on la déroule debout et on la jette, ce qui en fait le seul tamal vraiment nomade du Guatemala.",
     en:"Small tight tamales, cooked in corn husk rather than banana leaf. They are sold on the street in the evening, singly, husk included: you unroll it standing up and throw it away, which makes them Guatemala's only truly portable tamal."},
  i:[['corn_masa',1,'kg'],['lard',250,'g'],['pork_shoulder',600,'g'],['ripe_tomato',600,'g'],['guajillo_chili',4,'pc'],['pumpkin_seeds',80,'g'],['corn_husks',30,'pc'],['chicken_broth',800,'ml'],['onion',1,'pc'],['garlic',5,'clove'],['queso_fresco',150,'g'],['salt',null,'']],
  s:{fr:["Faites tremper les feuilles de maïs séchées une heure dans l'eau chaude pour les assouplir sans les déchirer.","Battez le saindoux jusqu'à ce qu'il blanchisse, puis incorporez la masa et le bouillon peu à peu.","La pâte du chuchito reste plus ferme que celle du tamal : c'est ce qui lui permet de tenir sans support une fois déroulé.","Grillez tomates et piments, mixez-les avec les graines et faites réduire ce recado dix minutes.","Étalez la pâte sur la feuille, ajoutez le porc et une cuillerée de recado, roulez serré et cuisez une heure à la vapeur, debout."],
     en:["Soak the dried corn husks an hour in hot water to soften them without tearing.","Beat the lard until it whitens, then work in the masa and broth little by little.","Chuchito dough stays firmer than tamal dough: that is what lets it stand up unsupported once unwrapped.","Char tomatoes and chillies, blend them with the seeds and reduce this recado for ten minutes.","Spread the dough on the husk, add pork and a spoonful of recado, roll tightly and steam an hour, standing upright."]} },

{ id:'caldo-de-pata', c:'na', lat:14.840, lon:-91.510, base:6, prep:60, cook:240, diff:2, tags:['soup','slow','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f0e4c8',style:'soup',food:['#e8c46a','#f4f0e6','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Caldo de pata',en:'Caldo de pata'},
  p:{fr:'Quetzaltenango, Guatemala',en:'Quetzaltenango, Guatemala'},
  d:{fr:"Un bouillon de pieds de bœuf, long et gélatineux, servi le matin sur les marchés des hauts plateaux. Le collagène des pieds se dissout en gélatine après quatre heures : le bouillon prend en gelée en refroidissant, et c'est le signe qu'il est réussi.",
     en:"A long, gelatinous broth of ox feet, served in the morning at highland markets. The collagen in the feet dissolves into gelatine after four hours: the broth sets to a jelly as it cools, which is the sign it has been made properly."},
  i:[['beef_trotters',2,'kg'],['chickpeas',200,'g'],['carrot',3,'pc'],['cabbage',400,'g'],['potato',500,'g'],['onion',2,'pc'],['garlic',10,'clove'],['mint',1,'bunch'],['cilantro',1,'bunch'],['lime',4,'pc'],['corn_tortillas',12,'pc'],['salt',null,'']],
  s:{fr:["Faites blanchir les pieds dix minutes et jetez cette eau : elle emporte l'écume grise et l'odeur forte.","Repartez à l'eau froide avec l'oignon, l'ail et les pois chiches trempés, et laissez frémir quatre heures.","Écumez régulièrement pendant la première heure ; au-delà, le bouillon se clarifie tout seul.","Ne salez qu'après trois heures : le sel précoce raffermit le collagène et ralentit sa transformation en gélatine.","Ajoutez les légumes pour la dernière demi-heure. Servez avec citron vert, menthe fraîche et tortillas chaudes."],
     en:["Blanch the feet ten minutes and discard that water: it carries off the grey scum and the strong smell.","Start again in cold water with the onion, garlic and soaked chickpeas, and simmer four hours.","Skim regularly during the first hour; after that the broth clears by itself.","Salt only after three hours: early salt firms the collagen and slows its turning into gelatine.","Add the vegetables for the last half hour. Serve with lime, fresh mint and hot tortillas."]} },

{ id:'revolcado', c:'na', lat:14.630, lon:-90.520, base:6, prep:90, cook:120, diff:3, tags:['pork','stew','slow'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#c9302a','#8f4a3a','#5a2a2a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Revolcado',en:'Revolcado'},
  p:{fr:'Guatemala, Guatemala',en:'Guatemala City, Guatemala'},
  d:{fr:"Un ragoût rouge d'abats de porc — tête, foie, cœur, rognons — dans un recado de tomate et de piment. Le nom vient de revolcar, remuer, retourner : tous les morceaux sont mêlés dans la même sauce épaisse, et rien de la tête du cochon n'est écarté.",
     en:"A red stew of pork offal — head, liver, heart, kidneys — in a tomato and chilli recado. The name comes from revolcar, to tumble about: every piece is mixed into the same thick sauce, and nothing of the pig's head is set aside."},
  i:[['pork_head',1.5,'kg'],['pork_liver',300,'g'],['pork_heart',300,'g'],['pork_kidney',250,'g'],['ripe_tomato',800,'g'],['tomatillo',300,'g'],['guajillo_chili',6,'pc'],['pumpkin_seeds',100,'g'],['sesame_seeds',60,'g'],['corn_tortillas',3,'pc'],['bay_leaf',3,'pc'],['onion',2,'pc'],['garlic',8,'clove'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Faites dégorger tous les abats deux heures à l'eau vinaigrée, en changeant l'eau une fois.","Pochez la tête deux heures avec le laurier, désossez-la chaude et coupez tout en dés d'un centimètre.","Pochez le foie et les rognons à part, quinze minutes seulement : cuits avec la tête, ils deviendraient farineux.","Grillez tomates, tomatilles et piments, mixez avec les graines grillées et les tortillas, et passez au chinois.","Réunissez tout, mouillez du bouillon de tête et laissez mijoter trente minutes. La sauce doit être épaisse et brillante."],
     en:["Soak all the offal two hours in acidulated water, changing it once.","Poach the head two hours with the bay, bone it hot and dice everything to one centimetre.","Poach the liver and kidneys separately, fifteen minutes only: cooked with the head they would turn mealy.","Char tomatoes, tomatillos and chillies, blend with the toasted seeds and tortillas, and strain.","Bring everything together, moisten with the head broth and simmer thirty minutes. The sauce should be thick and glossy."]} },

{ id:'atol-de-elote', c:'na', lat:14.560, lon:-90.730, base:6, prep:30, cook:35, diff:1, tags:['drink','sweet','comfort'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#e8c46a','#f2dfa8','#f4f0e6','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Atol de elote',en:'Atol de elote'},
  p:{fr:'Antigua Guatemala, Guatemala',en:'Antigua Guatemala, Guatemala'},
  d:{fr:"Une boisson chaude et épaisse de maïs frais broyé, sucrée à la cannelle. L'atol descend de l'atolli nahuatl, boisson de maïs antérieure à la conquête ; on le boit dans la rue, au petit matin, dans des gobelets qu'on rend au vendeur.",
     en:"A thick hot drink of ground fresh corn, sweetened with cinnamon. Atol descends from Nahuatl atolli, a corn drink older than the conquest; it is drunk in the street at dawn, from cups handed back to the vendor."},
  i:[['sweetcorn',8,'pc'],['whole_milk',1,'l'],['sugar',180,'g'],['cinnamon_stick',2,'pc'],['butter',40,'g'],['salt',null,'']],
  s:{fr:["Choisissez des épis à grain laiteux : percé à l'ongle, le grain doit rendre du liquide blanc et non de l'eau claire.","Égrenez-les et mixez les grains avec le lait froid, puis passez au chinois en pressant fort pour retenir les peaux.","Ces peaux sont indigestes et donnent une texture sableuse ; les laisser passer est l'erreur la plus courante.","Faites cuire à feu doux avec la cannelle et le sucre, en remuant sans arrêt vingt minutes — l'amidon attache instantanément.","L'atol est prêt quand il nappe la cuillère. Ajoutez le beurre hors du feu et servez brûlant."],
     en:["Choose ears with milky kernels: pierced with a nail, the kernel should give white liquid and not clear water.","Strip them and blend the kernels with the cold milk, then strain, pressing hard to hold back the skins.","Those skins are indigestible and give a sandy texture; letting them through is the commonest mistake.","Cook over low heat with the cinnamon and sugar, stirring without pause for twenty minutes — the starch catches instantly.","The atol is ready when it coats the spoon. Add the butter off the heat and serve scalding."]} }
,

{ id:'fry-jacks', c:'na', lat:17.158, lon:-89.070, base:4, prep:60, cook:15, diff:1, tags:['bread','fry','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Fry jacks',en:'Fry jacks'},
  p:{fr:'San Ignacio, Belize',en:'San Ignacio, Belize'},
  d:{fr:"Des triangles de pâte frits et gonflés, servis au petit-déjeuner avec haricots et œufs. On les fend d'un coup de couteau pour y glisser la garniture : l'air emprisonné en fait une poche naturelle, et c'est pour cela qu'on les incise avant de frire.",
     en:"Triangles of dough fried until they puff, served at breakfast with beans and eggs. They are slit with a knife to slip in a filling: the trapped air makes a natural pocket, which is why they are scored before frying."},
  i:[['flour',500,'g'],['baking_powder',15,'g'],['shortening',60,'g'],['whole_milk',280,'ml'],['frying_oil',1,'l'],['refried_beans',400,'g'],['egg',6,'pc'],['cheddar_cheese',150,'g'],['salt',null,'']],
  s:{fr:["Sablez la farine, la levure chimique et la matière grasse, puis liez au lait sans pétrir plus d'une minute.","Un pétrissage long développe le gluten et le fry jack devient élastique au lieu de gonfler.","Laissez reposer trente minutes, abaissez à 4 mm et découpez des triangles de dix centimètres.","Incisez chaque triangle de deux entailles courtes au centre : c'est par là que la vapeur s'installe et soulève la pâte.","Frites à 190 °C, quarante secondes par face. Ils doivent gonfler immédiatement ; s'ils restent plats, l'huile n'est pas assez chaude."],
     en:["Rub the flour, baking powder and fat together, then bind with milk without kneading more than a minute.","Long kneading develops the gluten and the fry jack turns elastic instead of puffing.","Rest thirty minutes, roll to 4 mm and cut ten-centimetre triangles.","Score each triangle with two short cuts at the centre: that is where the steam gathers and lifts the dough.","Fry at 190°C, forty seconds a side. They should puff at once; if they stay flat, the oil is not hot enough."]} },

{ id:'hudut', c:'na', lat:16.970, lon:-88.233, base:6, prep:60, cook:45, diff:2, tags:['sea','comfort','stew'],
  art:{v:'bowl',bg:'#26485c',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#e8c46a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Hudut',en:'Hudut'},
  p:{fr:'Dangriga, Belize',en:'Dangriga, Belize'},
  d:{fr:"Du poisson au lait de coco servi avec une purée de banane plantain pilée au mortier. Le pilon garífuna, le hana, est un mortier de bois d'un mètre de haut : la purée s'y travaille debout, à deux, et sa texture élastique ne s'obtient d'aucune autre manière.",
     en:"Fish in coconut milk served with plantain pounded in a mortar. The Garífuna hana is a metre-tall wooden mortar: the mash is worked standing, by two people, and its elastic texture cannot be got any other way."},
  i:[['white_fish',1,'kg'],['plantain',4,'pc'],['green_banana',4,'pc'],['coconut_milk',800,'ml'],['onion',2,'pc'],['garlic',6,'clove'],['okra',150,'g'],['cilantro',1,'bunch'],['lime',3,'pc'],['bell_pepper',1,'pc'],['salt',null,'']],
  s:{fr:["Faites bouillir séparément les bananes vertes et les plantains mûrs, vingt minutes, jusqu'à ce qu'ils s'écrasent.","Pilez-les ensemble, chauds, en frappant régulièrement : c'est le pilage répété qui rend la pâte élastique, et un mixeur la rend collante.","La proportion de vert et de mûr fait le goût : deux tiers vert pour un tiers mûr est l'équilibre habituel.","Faites revenir oignon, ail et poivron, versez le lait de coco et laissez frémir dix minutes sans bouillir.","Pochez le poisson en darnes huit minutes dans ce lait. Servez la purée à part, en boule, dans le bouillon."],
     en:["Boil the green bananas and ripe plantains separately, twenty minutes, until they crush easily.","Pound them together while hot, striking steadily: it is the repeated pounding that makes the mash elastic, and a blender makes it gluey.","The ratio of green to ripe makes the flavour: two-thirds green to one-third ripe is the usual balance.","Fry onion, garlic and pepper, pour in the coconut milk and simmer ten minutes without boiling.","Poach the fish steaks eight minutes in that milk. Serve the mash separately, as a ball, in the broth."]} },

{ id:'stew-chicken-belize', c:'na', lat:17.251, lon:-88.759, base:6, prep:40, cook:60, diff:2, tags:['poultry','stew','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Stew chicken',en:'Stew chicken'},
  p:{fr:'Belmopan, Belize',en:'Belmopan, Belize'},
  d:{fr:"Du poulet caramélisé au sucre brûlé puis mijoté au recado rouge, plat national du Belize. Le recado rojo est une pâte d'annatto et d'épices héritée des Mayas du Yucatán : c'est elle qui donne au poulet sa couleur brique et son parfum poivré.",
     en:"Chicken caramelised in burnt sugar then stewed with red recado, Belize's national dish. Recado rojo is an annatto and spice paste inherited from the Yucatán Maya: it gives the chicken its brick colour and peppery scent."},
  i:[['chicken',1.5,'kg'],['annatto',30,'g'],['brown_sugar',60,'g'],['onion',2,'pc'],['garlic',8,'clove'],['bell_pepper',1,'pc'],['thyme',1,'bunch'],['cumin',8,'g'],['oregano',5,'g'],['white_wine_vinegar',60,'ml'],['red_kidney_beans',300,'g'],['coconut_milk',400,'ml'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites mariner le poulet quatre heures au recado délayé de vinaigre, à l'ail, au cumin et à l'origan.","Chauffez l'huile et le sucre brun dans une marmite épaisse, sans remuer, jusqu'à ce que le caramel fume et noircisse.","C'est le moment décisif : trop clair, le poulet reste pâle ; trop poussé, tout le plat devient amer. Quelques secondes séparent les deux.","Jetez le poulet égoutté dans le caramel et remuez pour l'enrober — il doit prendre une couleur d'acajou.","Mouillez d'eau, laissez mijoter quarante minutes, et servez avec un riz aux haricots rouges cuit au lait de coco."],
     en:["Marinate the chicken four hours in recado slaked with vinegar, garlic, cumin and oregano.","Heat oil and brown sugar in a heavy pot, without stirring, until the caramel smokes and blackens.","This is the decisive moment: too pale and the chicken stays light; too far and the whole dish turns bitter. Seconds separate the two.","Drop the drained chicken into the caramel and stir to coat — it should take on a mahogany colour.","Moisten with water, simmer forty minutes, and serve with rice and red beans cooked in coconut milk."]} },

{ id:'johnny-cakes-belize', c:'na', lat:17.504, lon:-88.197, base:8, prep:60, cook:25, diff:1, tags:['bread','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8c46a','#f4f0e6','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Johnny cakes',en:'Johnny cakes'},
  p:{fr:'Belize City, Belize',en:'Belize City, Belize'},
  d:{fr:"De petits pains ronds au lait de coco, cuits au four et fendus pour être garnis. Le nom viendrait de journey cake, le pain qui se transportait : sans œuf ni levure de boulanger, il se garde deux jours sans durcir grâce à la graisse de coco.",
     en:"Small round rolls made with coconut milk, baked and split for filling. The name is said to come from journey cake, the bread that travelled: with no egg and no baker's yeast, it keeps two days without hardening thanks to the coconut fat."},
  i:[['flour',600,'g'],['baking_powder',20,'g'],['coconut_milk',300,'ml'],['shortening',120,'g'],['sugar',30,'g'],['salt',null,'']],
  s:{fr:["Sablez la farine, la levure chimique, le sel et la graisse végétale jusqu'à obtenir une semoule grossière.","Liez au lait de coco d'un seul coup et rassemblez la pâte sans la pétrir plus de trente secondes.","Roulez des boules de la taille d'un œuf, aplatissez-les légèrement et piquez-les à la fourchette.","Ces piqûres laissent la vapeur s'échapper ; sans elles, le pain gonfle en dôme et retombe creux.","Cuisez 20 minutes à 200 °C. Servez tièdes, fendus, avec du fromage, des haricots ou du poisson."],
     en:["Rub the flour, baking powder, salt and shortening together to a coarse meal.","Bind with the coconut milk all at once and gather the dough without kneading more than thirty seconds.","Roll egg-sized balls, flatten them slightly and prick them with a fork.","Those holes let the steam out; without them the bread domes and collapses hollow.","Bake 20 minutes at 200°C. Serve warm, split, with cheese, beans or fish."]} },

{ id:'chimole', c:'na', lat:18.081, lon:-88.560, base:6, prep:60, cook:90, diff:3, tags:['soup','festive','poultry'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f0e4c8',style:'soup',food:['#1a1a1a','#3a2a2a','#f4f0e6','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Chimole',en:'Chimole'},
  p:{fr:'Orange Walk, Belize',en:'Orange Walk, Belize'},
  d:{fr:"Une soupe noire de dinde et de boulettes, colorée par des piments volontairement brûlés. Le recado negro s'obtient en calcinant les piments jusqu'au charbon, puis en les rinçant : la suie donne la couleur, le rinçage retire l'amertume.",
     en:"A black turkey and dumpling soup, coloured by deliberately burnt chillies. Recado negro is made by charring chillies to charcoal then rinsing them: the soot gives the colour, the rinsing removes the bitterness."},
  i:[['turkey',1.5,'kg'],['recado_negro',80,'g'],['ground_pork',300,'g'],['egg',4,'pc'],['corn_masa',150,'g'],['ripe_tomato',400,'g'],['onion',2,'pc'],['garlic',8,'clove'],['bell_pepper',1,'pc'],['cilantro',1,'bunch'],['corn_tortillas',12,'pc'],['salt',null,'']],
  s:{fr:["Si vous faites le recado vous-même, brûlez les piments secs entiers jusqu'à ce qu'ils soient noirs et cassants, en plein air : la fumée est irritante.","Rincez-les longuement à l'eau froide avant de les broyer — sans rinçage, la soupe est immangeable d'amertume.","Faites bouillir la dinde en morceaux une heure avec les aromates, puis délayez le recado dans un peu de bouillon chaud.","Formez des boulettes de porc haché avec un œuf dur entier au centre, et liez-les à la masa.","Pochez-les vingt minutes dans le bouillon noir, à frémissement. Servez avec des tortillas chaudes."],
     en:["If you make the recado yourself, burn the whole dried chillies until black and brittle, in the open air: the smoke is an irritant.","Rinse them at length in cold water before grinding — unrinsed, the soup is inedibly bitter.","Boil the jointed turkey an hour with the aromatics, then slake the recado in a little hot broth.","Shape pork dumplings around a whole hard-boiled egg, and bind them with masa.","Poach them twenty minutes in the black broth, at a tremble. Serve with hot tortillas."]} },

{ id:'curtido', c:'na', lat:13.699, lon:-89.191, base:8, prep:30, cook:0, diff:1, tags:['veg','fresh','fast'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ead4',style:'salad',food:['#f4f0e6','#7fae5a','#e8a032','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Curtido',en:'Curtido'},
  p:{fr:'San Salvador, Salvador',en:'San Salvador, El Salvador'},
  d:{fr:"Un chou mariné au vinaigre et à l'origan, obligatoire à côté des pupusas. Il n'est jamais servi seul : sa fonction est de couper le gras de la pupusa, et une pupuseria qui n'en poserait pas le bocal sur la table serait aussitôt jugée.",
     en:"Cabbage pickled with vinegar and oregano, obligatory beside pupusas. It is never served alone: its job is to cut the richness of the pupusa, and a pupusería that failed to put the jar on the table would be judged at once."},
  i:[['cabbage',800,'g'],['carrot',3,'pc'],['onion',2,'pc'],['white_wine_vinegar',300,'ml'],['oregano',10,'g'],['chili_pepper',2,'pc'],['water',200,'ml'],['sugar',20,'g'],['salt',null,'']],
  s:{fr:["Émincez le chou très fin et râpez les carottes en longs filaments, sans les couper court.","Ébouillantez-les trente secondes puis égouttez-les aussitôt : c'est ce qui les attendrit sans leur ôter le croquant.","Cru, le chou reste dur et n'absorbe pas la marinade ; cuit davantage, il devient mou en une nuit.","Mêlez au vinaigre coupé d'eau, à l'origan écrasé entre les doigts et au piment émincé.","Laissez macérer vingt-quatre heures au frais avant de servir. Se garde deux semaines et gagne les premiers jours."],
     en:["Shred the cabbage very finely and grate the carrots into long threads, not short pieces.","Scald them thirty seconds then drain at once: this softens them without taking away the crunch.","Raw, the cabbage stays hard and will not take the marinade; cooked longer, it goes limp overnight.","Mix with the vinegar cut with water, the oregano crushed between the fingers and the sliced chilli.","Macerate twenty-four hours in the cold before serving. Keeps two weeks and improves over the first days."]} },

{ id:'yuca-frita-salvadorena', c:'na', lat:13.705, lon:-89.200, base:6, prep:40, cook:40, diff:2, tags:['street','fry','veg'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Yuca frita',en:'Yuca frita'},
  p:{fr:'San Salvador, Salvador',en:'San Salvador, El Salvador'},
  d:{fr:"Du manioc bouilli puis frit, servi avec du curtido et des couennes de porc. On le vend le soir dans les parcs, sur une feuille de bananier, et le manioc est toujours bouilli avant d'être frit — jamais frit cru, contrairement à la pomme de terre.",
     en:"Cassava boiled then fried, served with curtido and pork crackling. It is sold in the evening in the parks, on a banana leaf, and the cassava is always boiled before frying — never fried raw, unlike potato."},
  i:[['cassava',1.2,'kg'],['pork_rinds',300,'g'],['cabbage',400,'g'],['white_wine_vinegar',150,'ml'],['ripe_tomato',300,'g'],['onion',2,'pc'],['frying_oil',1,'l'],['lime',3,'pc'],['oregano',5,'g'],['salt',null,'']],
  s:{fr:["Pelez le manioc et retirez le fil ligneux central, qui reste dur quelle que soit la cuisson.","Faites-le bouillir en tronçons trente minutes, jusqu'à ce qu'il se fende de lui-même, puis égouttez-le et laissez-le sécher.","Cette étape n'est pas facultative : le manioc cru contient des composés cyanogènes que l'ébullition détruit, et la friture seule n'y suffit pas.","Laissez refroidir complètement — chaud, il éclate violemment dans l'huile.","Frites à 180 °C jusqu'à ce que les bords dorent, et servez avec curtido, sauce tomate et chicharrón."],
     en:["Peel the cassava and remove the woody central thread, which stays hard however long it cooks.","Boil it in lengths for thirty minutes, until it splits by itself, then drain and let it dry.","This step is not optional: raw cassava holds cyanogenic compounds that boiling destroys, and frying alone will not do it.","Cool completely — hot, it spits violently in the oil.","Fry at 180°C until the edges colour, and serve with curtido, tomato sauce and chicharrón."]} },

{ id:'panes-con-pavo', c:'na', lat:13.692, lon:-89.185, base:8, prep:180, cook:180, diff:3, tags:['festive','poultry','slow'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#e8c46a','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Panes con pavo',en:'Panes con pavo'},
  p:{fr:'San Salvador, Salvador',en:'San Salvador, El Salvador'},
  d:{fr:"Un sandwich de dinde braisée dans une sauce épicée, arrosé de son jus. C'est le plat des fêtes de fin d'année au Salvador : la dinde marine deux jours dans un recado de graines grillées, et le pain est trempé dans la sauce avant d'être refermé.",
     en:"A sandwich of turkey braised in a spiced sauce, soaked in its own juices. It is the Salvadoran year-end feast dish: the turkey marinates for two days in a recado of toasted seeds, and the bread is dipped in the sauce before closing."},
  i:[['turkey',3,'kg'],['sesame_seeds',100,'g'],['pumpkin_seeds',100,'g'],['ripe_tomato',800,'g'],['guajillo_chili',6,'pc'],['baguette',8,'pc'],['radish',150,'g'],['lettuce',12,'pc'],['cucumber',1,'pc'],['watercress',1,'bunch'],['mustard',40,'g'],['bay_leaf',4,'pc'],['thyme',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites mariner la dinde deux jours au réfrigérateur avec la moutarde, le thym, le laurier et l'ail pilé.","Grillez à sec les graines de sésame et de courge jusqu'à ce qu'elles brunissent, puis moulez-les finement.","Grillez tomates et piments, mixez avec les graines, et passez au chinois : la sauce doit être veloutée.","Braisez la dinde trois heures à couvert dans cette sauce, à 160 °C, en l'arrosant toutes les demi-heures.","Effilochez la viande, garnissez les pains de crudités et de dinde, et arrosez généreusement de sauce avant de refermer."],
     en:["Marinate the turkey two days in the refrigerator with mustard, thyme, bay and crushed garlic.","Dry-toast the sesame and pumpkin seeds until they brown, then grind them finely.","Char tomatoes and chillies, blend with the seeds, and strain: the sauce must be velvety.","Braise the turkey three hours covered in that sauce at 160°C, basting every half hour.","Shred the meat, fill the rolls with salad and turkey, and spoon over sauce generously before closing."]} },

{ id:'pasteles-salvadorenos', c:'na', lat:13.688, lon:-89.196, base:8, prep:90, cook:30, diff:2, tags:['street','fry','beef'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#8f4a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pasteles salvadoriens',en:'Salvadoran pasteles'},
  p:{fr:'San Salvador, Salvador',en:'San Salvador, El Salvador'},
  d:{fr:"Des chaussons de masa de maïs farcis de viande et de légumes, frits en demi-lune. À ne pas confondre avec les pasteles portoricains, cuits à la feuille : ici la pâte est de maïs nixtamalisé et le chausson est frit, jamais bouilli.",
     en:"Turnovers of corn masa filled with meat and vegetables, fried in half-moons. Not to be confused with Puerto Rican pasteles, cooked in leaves: here the dough is nixtamalised corn and the turnover is fried, never boiled."},
  i:[['corn_masa',700,'g'],['ground_beef',400,'g'],['potato',300,'g'],['carrot',2,'pc'],['green_beans',150,'g'],['ripe_tomato',300,'g'],['onion',2,'pc'],['garlic',5,'clove'],['annatto',10,'g'],['frying_oil',1,'l'],['cabbage',300,'g'],['white_wine_vinegar',100,'ml'],['salt',null,'']],
  s:{fr:["Faites revenir la viande avec les légumes en très petits dés, jusqu'à ce que la farce soit sèche.","Une farce humide traverse la masa à la friture et fait éclater le chausson dans l'huile.","Pétrissez la masa avec de l'eau tiède et le roucou jusqu'à ce qu'elle ne se fende plus quand on la plie.","Formez des galettes entre deux feuilles de plastique, garnissez et repliez en demi-lune en scellant au bord.","Frites à 175 °C, quatre minutes en retournant. Servez avec du curtido, toujours."],
     en:["Fry the meat with very finely diced vegetables until the filling is dry.","A wet filling soaks through the masa in the fryer and bursts the turnover in the oil.","Knead the masa with warm water and annatto until it no longer cracks when folded.","Press discs between two sheets of plastic, fill and fold into half-moons, sealing the edge.","Fry at 175°C for four minutes, turning. Serve with curtido, always."]} },

{ id:'empanadas-de-platano', c:'na', lat:13.994, lon:-89.560, base:8, prep:90, cook:25, diff:2, tags:['sweet','fry','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f4f0e6','#c9924a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Empanadas de plátano',en:'Plantain empanadas'},
  p:{fr:'Santa Ana, Salvador',en:'Santa Ana, El Salvador'},
  d:{fr:"Des chaussons de purée de plantain farcis de crème pâtissière ou de haricots, frits et sucrés. Ils se mangent au petit-déjeuner ou à la nuit tombée, et la version aux haricots noirs surprend autant les visiteurs que les rellenitos guatémaltèques.",
     en:"Turnovers of plantain purée filled with pastry cream or beans, fried and sugared. They are eaten at breakfast or after dark, and the black bean version surprises visitors as much as Guatemalan rellenitos do."},
  i:[['plantain',6,'pc'],['whole_milk',500,'ml'],['egg_yolk',3,'pc'],['cornstarch',50,'g'],['sugar',180,'g'],['cinnamon',8,'g'],['vanilla',1,'pc'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Faites bouillir les plantains très mûrs avec la peau, puis pelez-les chauds et écrasez-les au presse-purée.","Travaillez la purée à la main jusqu'à ce qu'elle devienne lisse et malléable, sans ajouter de farine.","Préparez une crème pâtissière épaisse à la maïzena et laissez-la refroidir complètement, filmée au contact.","Formez des disques de purée dans la paume, garnissez d'une cuillerée de crème et refermez en scellant bien.","Frites à 175 °C, deux minutes par face, puis roulez dans le sucre à la cannelle pendant qu'elles sont chaudes."],
     en:["Boil very ripe plantains in their skins, then peel them hot and mash with a ricer.","Work the mash by hand until it turns smooth and pliable, without adding flour.","Make a thick cornflour pastry cream and cool it completely, covered on the surface.","Shape discs of mash in your palm, fill with a spoonful of cream and close, sealing well.","Fry at 175°C, two minutes a side, then roll in cinnamon sugar while still hot."]} },

{ id:'riguas', c:'na', lat:13.777, lon:-89.737, base:6, prep:40, cook:30, diff:1, tags:['street','veg','comfort'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#f2dfa8','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Riguas',en:'Riguas'},
  p:{fr:'Nahuizalco, Salvador',en:'Nahuizalco, El Salvador'},
  d:{fr:"Des galettes de maïs frais broyé, cuites entre deux feuilles de maïs sur la plaque. La feuille n'est pas un emballage mais un ustensile : elle empêche la pâte très humide de coller à la plaque et lui donne son parfum végétal.",
     en:"Cakes of ground fresh corn, cooked between two corn husks on a griddle. The husk is not a wrapper but a tool: it keeps the very wet batter from sticking to the plate and gives it a green scent."},
  i:[['sweetcorn',8,'pc'],['corn_husks',24,'pc'],['queso_fresco',200,'g'],['sour_cream',200,'ml'],['sugar',40,'g'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Égrenez les épis et broyez les grains au moulin ou au mixeur sans ajouter une goutte d'eau.","Le maïs frais contient assez d'humidité ; en ajouter donne une pâte qui coule et ne prend jamais.","Assaisonnez de sel et d'un peu de sucre, et laissez reposer un quart d'heure.","Étalez deux cuillerées sur une feuille de maïs verte, couvrez d'une seconde feuille et posez sur la plaque.","Cuisez dix minutes par face à feu doux. Servez avec de la crème et du fromage frais."],
     en:["Strip the ears and grind the kernels in a mill or blender without adding a drop of water.","Fresh corn holds enough moisture; adding any gives a batter that runs and never sets.","Season with salt and a little sugar, and rest a quarter of an hour.","Spread two spoonfuls on a green corn husk, cover with a second husk and set on the griddle.","Cook ten minutes a side over low heat. Serve with cream and fresh cheese."]} },

{ id:'tamales-de-elote', c:'na', lat:13.641, lon:-88.784, base:10, prep:90, cook:75, diff:2, tags:['sweet','comfort','slow'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tamales de elote',en:'Tamales de elote'},
  p:{fr:'San Vicente, Salvador',en:'San Vicente, El Salvador'},
  d:{fr:"Des tamales de maïs frais, légèrement sucrés, sans farce. Ils ne se préparent que pendant les trois mois de récolte : le maïs sec ne convient pas, il lui manque le sucre et l'humidité qui font tout leur intérêt.",
     en:"Tamales of fresh corn, lightly sweetened, with no filling. They are made only during the three-month harvest: dried corn will not do, lacking the sugar and moisture that make them what they are."},
  i:[['sweetcorn',12,'pc'],['corn_husks',30,'pc'],['sugar',150,'g'],['butter',150,'g'],['sour_cream',200,'ml'],['whole_milk',150,'ml'],['baking_powder',8,'g'],['salt',null,'']],
  s:{fr:["Décollez les feuilles entières sans les déchirer et gardez les plus larges pour l'emballage.","Égrenez et broyez les grains sans eau, puis mêlez au beurre battu, au sucre et à la crème.","Battez la pâte cinq minutes : l'air incorporé est la seule chose qui allège le tamal, il n'y a pas de levure.","Remplissez les feuilles aux deux tiers seulement — la pâte gonfle et déborderait.","Cuisez une heure à la vapeur, debout et serrés. Laissez tiédir avant d'ouvrir : chauds, ils se défont."],
     en:["Peel off whole husks without tearing them and keep the widest for wrapping.","Strip and grind the kernels without water, then mix with beaten butter, sugar and cream.","Beat the batter five minutes: the air worked in is the only thing that lightens the tamal, there is no yeast.","Fill the husks only two-thirds full — the batter swells and would overflow.","Steam an hour, standing upright and packed close. Cool slightly before opening: hot, they fall apart."]} }
,

{ id:'carneada', c:'na', lat:14.072, lon:-87.192, base:12, prep:180, cook:120, diff:2, tags:['beef','grill','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'grill',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Carneada',en:'Carneada'},
  p:{fr:'Tegucigalpa, Honduras',en:'Tegucigalpa, Honduras'},
  d:{fr:"Un grand barbecue hondurien où le bœuf mariné à l'orange amère est grillé au charbon. Ce n'est pas un plat mais une occasion : la carneada réunit la famille tout un dimanche, et le mot désigne autant le repas que la fête.",
     en:"A large Honduran barbecue where beef marinated in sour orange is grilled over charcoal. It is not a dish but an occasion: a carneada gathers the family for a whole Sunday, and the word means the party as much as the meal.'"},
  i:[['flank_steak',2.5,'kg'],['sour_orange_juice',400,'ml'],['garlic',15,'clove'],['onion',4,'pc'],['cumin',15,'g'],['oregano',10,'g'],['worcestershire',80,'ml'],['plantain',6,'pc'],['queso_fresco',400,'g'],['refried_beans',600,'g'],['corn_tortillas',24,'pc'],['chimol',400,'g'],['salt',null,'']],
  s:{fr:["Aplatissez la viande au maillet jusqu'à un centimètre : le flanchet est fibreux et une pièce épaisse reste coriace au gril.","Faites-la mariner trois heures à l'orange amère, à l'ail pilé, au cumin et à l'origan.","N'allez pas au-delà de quatre heures : l'acide de l'agrume finit par cuire la surface et la viande devient farineuse.","Grillez sur des braises vives, trois minutes par face, et laissez reposer cinq minutes avant de trancher en travers de la fibre.","Servez avec tortillas, haricots frits, fromage frais, plantains et chimol — la salade de tomate crue qui accompagne tout au Honduras."],
     en:["Flatten the meat with a mallet to a centimetre: flank is fibrous and a thick piece stays tough on the grill.","Marinate it three hours in sour orange, crushed garlic, cumin and oregano.","Do not go beyond four hours: the citrus acid eventually cooks the surface and the meat turns mealy.","Grill over hot coals, three minutes a side, and rest five minutes before slicing across the grain.","Serve with tortillas, refried beans, fresh cheese, plantains and chimol — the raw tomato salad that accompanies everything in Honduras."]} },

{ id:'anafre', c:'na', lat:14.065, lon:-87.185, base:6, prep:30, cook:30, diff:1, tags:['legume','comfort','cheese'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#3a2018','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Anafre',en:'Anafre'},
  p:{fr:'Tegucigalpa, Honduras',en:'Tegucigalpa, Honduras'},
  d:{fr:"Une fondue de haricots noirs et de fromage servie brûlante dans un brasero de terre cuite. L'anafre est d'abord le nom du récipient : un petit réchaud à charbon que l'on pose sur la table, et le plat a fini par prendre le nom de son support.",
     en:"A fondue of black beans and cheese served scalding in a clay brazier. Anafre is first the name of the vessel: a small charcoal burner set on the table, and the dish ended up taking the name of its holder."},
  i:[['refried_beans',600,'g'],['queso_fresco',300,'g'],['mozzarella',200,'g'],['chorizo',200,'g'],['sour_cream',150,'ml'],['onion',1,'pc'],['jalapeno',2,'pc'],['tortilla_chips',300,'g'],['lard',40,'g'],['salt',null,'']],
  s:{fr:["Faites revenir le chorizo émietté et l'oignon dans le saindoux jusqu'à ce que le gras rouge se libère.","Ajoutez les haricots refrits et détendez-les à l'eau chaude : ils doivent couler lentement de la cuillère.","Trop épais, l'anafre durcit en croûte au contact du feu ; trop liquide, il ne tient pas sur la tortilla.","Versez dans le récipient de terre, couvrez de fromage et laissez fondre sur la braise ou au four.","Servez sans attendre, le fromage encore filant, avec des tortillas frites pour tremper."],
     en:["Fry the crumbled chorizo and onion in lard until the red fat runs.","Add the refried beans and loosen them with hot water: they should fall slowly from the spoon.","Too thick, the anafre sets into a crust over the fire; too thin, it will not sit on the tortilla.","Pour into the clay vessel, cover with cheese and let it melt over coals or in the oven.","Serve at once, the cheese still stretching, with fried tortillas for dipping."]} },

{ id:'yuca-con-chicharron', c:'na', lat:15.505, lon:-88.025, base:6, prep:60, cook:60, diff:2, tags:['pork','street','comfort'],
  art:{v:'leaf',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#c9754a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Yuca con chicharrón',en:'Yuca con chicharrón'},
  p:{fr:'San Pedro Sula, Honduras',en:'San Pedro Sula, Honduras'},
  d:{fr:"Du manioc bouilli servi avec des couennes de porc croustillantes et une salade de chou. Le plat se sert sur une feuille de bananier et se mange à la main : la feuille tient lieu d'assiette, et rien ne se lave après.",
     en:"Boiled cassava served with crisp pork crackling and a cabbage salad. It is served on a banana leaf and eaten with the hands: the leaf is the plate, and nothing needs washing afterwards."},
  i:[['cassava',1.2,'kg'],['pork_belly',800,'g'],['cabbage',400,'g'],['ripe_tomato',300,'g'],['onion',2,'pc'],['white_wine_vinegar',100,'ml'],['sour_orange_juice',100,'ml'],['banana_leaf',6,'pc'],['lard',200,'g'],['oregano',5,'g'],['salt',null,'']],
  s:{fr:["Coupez la poitrine en bâtonnets avec la couenne et faites-la cuire à couvert dans son propre gras, à feu très doux, quarante minutes.","Découvrez ensuite et montez le feu : la graisse rendue devient le bain de friture, et il n'en faut pas d'autre.","Le chicharrón est prêt quand il cesse de crépiter — le bruit s'arrête parce que toute l'eau s'est évaporée.","Faites bouillir le manioc trente minutes, égouttez-le et retirez le fil central.","Dressez sur la feuille : manioc, chicharrón, chou au vinaigre et tomate. Arrosez d'orange amère."],
     en:["Cut the belly into batons with the rind and cook it covered in its own fat, over very low heat, for forty minutes.","Then uncover and raise the heat: the rendered fat becomes the frying bath, and no other is needed.","The chicharrón is ready when it stops crackling — the noise stops because all the water has gone.","Boil the cassava thirty minutes, drain it and remove the central thread.","Plate on the leaf: cassava, chicharrón, vinegared cabbage and tomato. Douse with sour orange."]} },

{ id:'pollo-chuco', c:'na', lat:15.512, lon:-88.030, base:4, prep:60, cook:40, diff:2, tags:['poultry','street','fry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#c9924a','#3a2018','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pollo chuco',en:'Pollo chuco'},
  p:{fr:'San Pedro Sula, Honduras',en:'San Pedro Sula, Honduras'},
  d:{fr:"Du poulet frit sur un lit de bananes plantain frites et de haricots noirs, couvert de chou et de crème. Chuco veut dire « sale » en argot hondurien : le plat est nommé d'après son apparence, tout mêlé et débordant de l'assiette.",
     en:"Fried chicken on a bed of fried plantain and black beans, topped with cabbage and cream. Chuco means dirty in Honduran slang: the dish is named for its look, all jumbled and spilling off the plate."},
  i:[['chicken_legs',6,'pc'],['plantain',6,'pc'],['refried_beans',500,'g'],['cabbage',300,'g'],['sour_cream',200,'ml'],['queso_fresco',150,'g'],['flour',150,'g'],['frying_oil',1.5,'l'],['garlic',6,'clove'],['cumin',8,'g'],['white_wine_vinegar',80,'ml'],['salt',null,'']],
  s:{fr:["Faites mariner le poulet une heure à l'ail, au cumin et au sel, puis farinez-le légèrement.","Coupez les plantains verts en fines lamelles dans la longueur, à l'économe, pour obtenir des chips et non des rondelles.","Frites d'abord les plantains à 160 °C, égouttez-les, puis montez à 190 °C et frites-les une seconde fois pour les rendre cassants.","Frites le poulet à 170 °C, douze minutes, jusqu'à ce que le jus qui perle soit clair.","Montez l'assiette dans l'ordre : plantains, haricots, poulet, chou vinaigré, crème, fromage. On ne mélange pas avant de servir."],
     en:["Marinate the chicken an hour in garlic, cumin and salt, then flour it lightly.","Cut green plantains into thin lengthways slices with a peeler, to get crisps rather than coins.","Fry the plantains first at 160°C, drain them, then raise to 190°C and fry again to make them brittle.","Fry the chicken at 170°C for twelve minutes, until the juices run clear.","Build the plate in order: plantains, beans, chicken, vinegared cabbage, cream, cheese. It is not mixed before serving."]} },

{ id:'vigoron', c:'na', lat:11.930, lon:-85.956, base:6, prep:60, cook:60, diff:2, tags:['pork','street','fresh'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'salad',food:['#f4f0e6','#c9754a','#7fae5a','#e07a6a'],garnish:'#7fae6a'},
  n:{fr:'Vigorón',en:'Vigorón'},
  p:{fr:'Granada, Nicaragua',en:'Granada, Nicaragua'},
  d:{fr:"Du manioc bouilli, du chicharrón et une salade de chou au vinaigre, servis sur feuille de bananier. Il a été inventé en 1914 par une vendeuse du marché de Granada, qui lui a donné le nom d'un fortifiant en vogue à l'époque.",
     en:"Boiled cassava, chicharrón and a vinegared cabbage salad, served on a banana leaf. It was invented in 1914 by a vendor in Granada market, who named it after a tonic then in fashion."},
  i:[['cassava',1,'kg'],['pork_belly',700,'g'],['cabbage',500,'g'],['ripe_tomato',300,'g'],['onion',2,'pc'],['white_wine_vinegar',150,'ml'],['chili_pepper',2,'pc'],['banana_leaf',6,'pc'],['lime',3,'pc'],['salt',null,'']],
  s:{fr:["Préparez la salade de chou au moins deux heures à l'avance : elle doit être franchement acide, c'est elle qui équilibre le gras.","Émincez le chou finement, salez-le dix minutes puis pressez-le avant d'ajouter le vinaigre — sans cela il rend son eau et dilue tout.","Faites cuire la poitrine de porc dans son gras, à couvert puis à découvert, jusqu'à ce que la couenne cloque.","Faites bouillir le manioc en gros tronçons, sans le laisser se défaire : il doit rester en morceaux qu'on prend à la main.","Dressez sur la feuille : manioc, chicharrón cassé en morceaux, salade par-dessus. Se mange sans couverts."],
     en:["Make the cabbage salad at least two hours ahead: it must be frankly sour, that is what balances the fat.","Shred the cabbage finely, salt it ten minutes then press it before adding the vinegar — otherwise it weeps and dilutes everything.","Cook the pork belly in its own fat, covered then uncovered, until the rind blisters.","Boil the cassava in large lengths without letting it collapse: it must stay in pieces you can pick up.","Plate on the leaf: cassava, chicharrón broken into pieces, salad over the top. Eaten without cutlery."]} },

{ id:'baho', c:'na', lat:11.974, lon:-86.094, base:10, prep:720, cook:300, diff:3, tags:['beef','slow','festive'],
  art:{v:'leaf',bg:'#28331f',plate:'#f0e4c8',style:'other',food:['#8f4a3a','#e8c46a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bahó',en:'Bahó'},
  p:{fr:'Masaya, Nicaragua',en:'Masaya, Nicaragua'},
  d:{fr:"Du bœuf, du plantain et du manioc cuits cinq heures à l'étouffée dans des feuilles de bananier. Bahó vient de vaho, la vapeur : rien n'est ajouté au fond de la marmite, et toute la cuisson se fait dans l'eau rendue par les ingrédients eux-mêmes.",
     en:"Beef, plantain and cassava smothered for five hours in banana leaves. Bahó comes from vaho, steam: nothing is added to the bottom of the pot, and all the cooking is done in the water the ingredients release."},
  i:[['beef_brisket',1.5,'kg'],['plantain',6,'pc'],['green_banana',6,'pc'],['cassava',1,'kg'],['onion',4,'pc'],['bell_pepper',3,'pc'],['ripe_tomato',500,'g'],['sour_orange_juice',300,'ml'],['garlic',12,'clove'],['banana_leaf',30,'pc'],['cabbage',400,'g'],['white_wine_vinegar',150,'ml'],['salt',null,'']],
  s:{fr:["Faites mariner la poitrine de bœuf douze heures à l'orange amère, à l'ail et à l'oignon — l'acide attendrit un morceau très fibreux.","Tapissez une grande marmite de feuilles de bananier passées à la flamme, en les laissant largement déborder.","Empilez par couches : bœuf en bas, puis plantains verts, puis mûrs, puis manioc, en salant chaque étage.","Rabattez les feuilles par-dessus et fermez hermétiquement avec un couvercle lesté. N'ajoutez pas une goutte d'eau.","Cinq heures à feu très doux, sans jamais ouvrir. Servez avec une salade de chou au vinaigre."],
     en:["Marinate the brisket twelve hours in sour orange, garlic and onion — the acid tenderises a very fibrous cut.","Line a large pot with banana leaves passed through a flame, letting them overhang generously.","Stack in layers: beef at the bottom, then green plantains, then ripe, then cassava, salting each tier.","Fold the leaves over and seal tightly with a weighted lid. Do not add a drop of water.","Five hours over very low heat, never opening it. Serve with a vinegared cabbage salad."]} },

{ id:'quesillo-nicaraguayen', c:'na', lat:12.340, lon:-86.674, base:4, prep:30, cook:20, diff:2, tags:['cheese','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#f0e8d0','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Quesillo',en:'Quesillo'},
  p:{fr:'La Paz Centro, Nicaragua',en:'La Paz Centro, Nicaragua'},
  d:{fr:"Une tortilla roulée autour d'un fromage filant, d'oignons marinés et de crème aigre. Il se sert dans un sac plastique, jamais dans une assiette : on mord le coin du sac et on presse, et c'est ainsi qu'on le mange depuis toujours sur la route de León.",
     en:"A tortilla rolled around a stretchy cheese, pickled onions and sour cream. It is served in a plastic bag, never on a plate: you bite the corner of the bag and squeeze, which is how it has always been eaten on the road to León."},
  i:[['corn_tortillas',8,'pc'],['mozzarella',400,'g'],['onion',3,'pc'],['white_wine_vinegar',200,'ml'],['sour_cream',300,'ml'],['chili_pepper',1,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner les oignons émincés très fin au vinaigre salé au moins deux heures : ils doivent devenir translucides et perdre leur agressivité.","Employez un fromage frais à pâte filée, non affiné : c'est l'élasticité qui compte, pas le goût.","Réchauffez la tortilla sur la plaque jusqu'à ce qu'elle devienne souple, sans la laisser sécher ni durcir.","Posez le fromage au centre, ajoutez les oignons égouttés puis la crème, et roulez serré.","Servez immédiatement. Refroidi, le fromage se rétracte et le quesillo perd tout son intérêt."],
     en:["Pickle the very finely sliced onions in salted vinegar at least two hours: they should turn translucent and lose their bite.","Use a fresh pasta filata cheese, unripened: elasticity is what matters, not flavour.","Warm the tortilla on the griddle until it turns supple, without letting it dry or harden.","Lay the cheese in the centre, add the drained onions then the cream, and roll tightly.","Serve at once. Cooled, the cheese contracts and the quesillo loses all its point."]} },

{ id:'indio-viejo', c:'na', lat:12.115, lon:-86.236, base:6, prep:60, cook:90, diff:2, tags:['beef','stew','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e8c46a','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Indio viejo',en:'Indio viejo'},
  p:{fr:'Managua, Nicaragua',en:'Managua, Nicaragua'},
  d:{fr:"Un ragoût de bœuf effiloché épaissi à la masa de maïs, parfumé à l'orange amère et à la menthe. C'est l'un des plats précolombiens les mieux conservés d'Amérique centrale : la viande a remplacé le gibier, mais la technique d'épaississement à la masa n'a pas bougé.",
     en:"A shredded beef stew thickened with corn masa, scented with sour orange and mint. It is one of the best-preserved pre-Columbian dishes in Central America: beef replaced game, but the masa-thickening technique has not changed."},
  i:[['beef_brisket',1,'kg'],['corn_masa',250,'g'],['ripe_tomato',500,'g'],['onion',3,'pc'],['bell_pepper',2,'pc'],['garlic',8,'clove'],['sour_orange_juice',200,'ml'],['mint',1,'bunch'],['annatto',15,'g'],['lard',80,'g'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir la poitrine une heure et demie, laissez-la tiédir dans son bouillon puis effilochez-la à la main.","Délayez la masa dans du bouillon froid, jamais chaud : versée dans un liquide chaud, elle prend en grumeaux impossibles à défaire.","Faites revenir oignon, ail, poivron et tomate dans le saindoux coloré au roucou.","Ajoutez la viande, le bouillon et la masa délayée, et remuez sans arrêt vingt minutes à feu doux.","Terminez par l'orange amère et la menthe hors du feu. La consistance juste est celle d'une purée qui coule lentement."],
     en:["Boil the brisket an hour and a half, cool it in its broth then shred it by hand.","Slake the masa in cold broth, never hot: poured into hot liquid it lumps in a way nothing can undo.","Fry onion, garlic, pepper and tomato in lard coloured with annatto.","Add the meat, broth and slaked masa, and stir without pause for twenty minutes over low heat.","Finish with sour orange and mint off the heat. The right consistency runs slowly like a thick purée."]} },

{ id:'rondon-nicaraguayen', c:'na', lat:12.014, lon:-83.763, base:8, prep:60, cook:90, diff:2, tags:['sea','stew','slow'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'soup',food:['#f4f0e6','#e8c46a','#7fae5a','#e07a6a'],garnish:'#6fbf8f'},
  n:{fr:'Rondón',en:'Rondón'},
  p:{fr:'Bluefields, Nicaragua',en:'Bluefields, Nicaragua'},
  d:{fr:"Un ragoût créole caribéen de poisson, tubercules et lait de coco, cuit lentement dans une seule marmite. Le nom vient de l'anglais run down : le cuisinier « court » chercher tout ce qu'il trouve, et le contenu change à chaque fois.",
     en:"A Caribbean Creole stew of fish, root vegetables and coconut milk, slowly cooked in one pot. The name comes from English run down: the cook runs to fetch whatever is at hand, and the contents change every time."},
  i:[['white_fish',1,'kg'],['crab_claws',8,'pc'],['shrimp',300,'g'],['coconut_milk',1,'l'],['cassava',600,'g'],['plantain',4,'pc'],['sweet_potato',500,'g'],['breadfruit',1,'pc'],['onion',2,'pc'],['garlic',8,'clove'],['thyme',1,'bunch'],['scotch_bonnet',1,'pc'],['flour',150,'g'],['salt',null,'']],
  s:{fr:["Pressez la noix de coco deux fois et gardez les deux laits séparés — le clair pour la cuisson longue, l'épais pour la fin.","Faites cuire les tubercules dans le lait clair quarante minutes, avec le thym et l'ail.","Ajoutez des dombrés roulés à la main, de simples boulettes de farine et d'eau, et laissez-les pocher vingt minutes.","Posez le piment entier sans le percer : il parfume sans brûler, et se retire avant de servir.","Ajoutez poisson, crabe et crevettes puis le lait épais, et laissez frémir dix minutes sans jamais bouillir."],
     en:["Press the coconut twice and keep the two milks apart — the thin for the long cooking, the thick for the end.","Cook the root vegetables in the thin milk for forty minutes, with the thyme and garlic.","Add hand-rolled dumplings, simple balls of flour and water, and poach them twenty minutes.","Set the whole chilli in unpierced: it scents without burning, and is removed before serving.","Add fish, crab and shrimp then the thick milk, and simmer ten minutes without ever boiling."]} },

{ id:'chancho-con-yuca', c:'na', lat:11.935, lon:-85.950, base:6, prep:1440, cook:90, diff:2, tags:['pork','slow','street'],
  art:{v:'leaf',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#8f5a3a','#7fae5a','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Chancho con yuca',en:'Chancho con yuca'},
  p:{fr:'Granada, Nicaragua',en:'Granada, Nicaragua'},
  d:{fr:"Du porc salé une nuit puis mijoté, servi avec du manioc et du chou mariné. Il se distingue du vigorón par la viande : ici le porc est saumuré et cuit à l'humide, quand le vigorón exige un chicharrón sec et croustillant.",
     en:"Pork salted overnight then stewed, served with cassava and pickled cabbage. It differs from vigorón in the meat: here the pork is brined and cooked wet, whereas vigorón demands a dry, crisp chicharrón."},
  i:[['pork_shoulder',1.2,'kg'],['coarse_salt',80,'g'],['cassava',1,'kg'],['cabbage',400,'g'],['onion',2,'pc'],['ripe_tomato',300,'g'],['white_wine_vinegar',150,'ml'],['sour_orange_juice',150,'ml'],['garlic',8,'clove'],['banana_leaf',6,'pc'],['salt',null,'']],
  s:{fr:["Frottez le porc de gros sel et d'ail écrasé et laissez-le vingt-quatre heures au frais, à découvert.","Rincez-le et goûtez un fragment cuit avant d'aller plus loin : le sel pénètre très inégalement selon l'épaisseur.","Faites-le mijoter une heure et demie avec l'orange amère et l'oignon, jusqu'à ce qu'il se défasse à la fourchette.","Faites bouillir le manioc à part, dans une eau à peine salée, et retirez le fil ligneux.","Dressez sur feuille de bananier avec le chou au vinaigre, et arrosez du jus de cuisson du porc."],
     en:["Rub the pork with coarse salt and crushed garlic and leave it twenty-four hours in the cold, uncovered.","Rinse it and taste a cooked fragment before going further: salt penetrates very unevenly depending on thickness.","Simmer it an hour and a half with the sour orange and onion, until it falls apart under a fork.","Boil the cassava separately in barely salted water, and remove the woody thread.","Plate on banana leaf with the vinegared cabbage, and spoon over the pork cooking juices."]} },

{ id:'rosquillas-somotenas', c:'na', lat:13.481, lon:-86.583, base:10, prep:60, cook:30, diff:2, tags:['bake','cheese','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Rosquillas somoteñas',en:'Somoto rosquillas'},
  p:{fr:'Somoto, Nicaragua',en:'Somoto, Nicaragua'},
  d:{fr:"Des anneaux croquants de masa de maïs et de fromage sec, cuits au four à bois. Somoto en vit : la ville compte des dizaines de fours familiaux, et les rosquillas se vendent le long de la route panaméricaine à toute heure.",
     en:"Crisp rings of corn masa and dry cheese, baked in wood-fired ovens. Somoto lives on them: the town has dozens of family ovens, and rosquillas are sold along the Pan-American highway at all hours."},
  i:[['corn_masa',700,'g'],['queso_seco',400,'g'],['butter',150,'g'],['egg',3,'pc'],['sugar',100,'g'],['whole_milk',100,'ml'],['salt',null,'']],
  s:{fr:["Employez un maïs blanc nixtamalisé et moulu à sec, plus grossier que la masa à tortillas : c'est ce grain qui donne le croquant.","Râpez le fromage sec très finement — un fromage frais rendrait de l'eau et la rosquilla resterait molle.","Travaillez le beurre et le fromage jusqu'à obtenir une crème, puis incorporez la masa, les œufs et le sucre.","Formez des anneaux de sept centimètres, épais d'un doigt, et laissez-les sécher une demi-heure à l'air.","Cuisez 25 minutes à 190 °C. Elles doivent sonner creux et durcir en refroidissant."],
     en:["Use white nixtamalised corn ground dry, coarser than tortilla masa: that grain gives the crunch.","Grate the dry cheese very finely — a fresh cheese would release water and the rosquilla would stay soft.","Work the butter and cheese to a cream, then work in the masa, eggs and sugar.","Shape seven-centimetre rings a finger thick, and let them dry half an hour in the air.","Bake 25 minutes at 190°C. They should sound hollow and harden as they cool."]} }
,

{ id:'casado', c:'na', lat:9.928, lon:-84.091, base:4, prep:60, cook:60, diff:2, tags:['rice','comfort','veg'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'rice',food:['#f4f0e6','#3a2018','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Casado',en:'Casado'},
  p:{fr:'San José, Costa Rica',en:'San José, Costa Rica'},
  d:{fr:"L'assiette complète costaricienne : riz, haricots, plantain, salade, légume et une viande. Le nom veut dire « marié » : les éléments sont unis dans la même assiette, et l'on dit aussi que c'était le déjeuner que l'épouse préparait au travailleur.",
     en:"The complete Costa Rican plate: rice, beans, plantain, salad, a vegetable and a meat. The name means married: the elements are joined on one plate, and it is also said to be the lunch a wife packed for a working husband."},
  i:[['long_grain_rice',400,'g'],['black_beans',300,'g'],['plantain',3,'pc'],['chicken_breast',600,'g'],['cabbage',300,'g'],['ripe_tomato',300,'g'],['egg',4,'pc'],['onion',2,'pc'],['bell_pepper',1,'pc'],['cilantro',1,'bunch'],['garlic',6,'clove'],['lime',2,'pc'],['salt',null,'']],
  s:{fr:["Cuisez le riz avec un fond d'oignon, d'ail et de poivron revenus : le riz nature ne se sert pas au Costa Rica.","Faites mijoter les haricots noirs une heure et demie avec de la coriandre entière, tiges comprises.","Gardez l'eau de cuisson des haricots : c'est elle qui servira au gallo pinto du lendemain, et la jeter serait un gâchis.","Faites frire les plantains bien mûrs en biseau, jusqu'à ce qu'ils caramélisent sur les bords.","Disposez chaque élément côte à côte, sans les mêler, et ajoutez une salade de chou au citron vert."],
     en:["Cook the rice on a base of softened onion, garlic and pepper: plain rice is not served in Costa Rica.","Simmer the black beans an hour and a half with whole coriander, stems included.","Keep the bean cooking water: it is what makes tomorrow's gallo pinto, and throwing it away would be waste.","Fry very ripe plantains on the bias, until they caramelise at the edges.","Set each element side by side without mixing, and add a cabbage salad with lime."]} },

{ id:'chifrijo', c:'na', lat:9.933, lon:-84.080, base:4, prep:60, cook:90, diff:2, tags:['pork','legume','street'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#3a2018','#c9754a','#e07a6a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Chifrijo',en:'Chifrijo'},
  p:{fr:'San José, Costa Rica',en:'San José, Costa Rica'},
  d:{fr:"Un bol superposant haricots, riz, chicharrón et pico de gallo. Le nom est une contraction de chicharrón et frijoles ; il a été inventé dans les années 1990 dans un bar de San José, et fait l'objet d'un litige de marque déposée toujours en cours.",
     en:"A bowl layering beans, rice, chicharrón and pico de gallo. The name contracts chicharrón and frijoles; it was invented in the 1990s in a San José bar, and remains the subject of an unresolved trademark dispute."},
  i:[['red_kidney_beans',400,'g'],['long_grain_rice',300,'g'],['pork_belly',600,'g'],['ripe_tomato',400,'g'],['onion',2,'pc'],['cilantro',1,'bunch'],['lime',4,'pc'],['avocado',2,'pc'],['tortilla_chips',300,'g'],['garlic',6,'clove'],['chili_pepper',1,'pc'],['salt',null,'']],
  s:{fr:["Cuisez les haricots rouges jusqu'à ce qu'ils soient tendres mais entiers, et gardez-les dans un peu de leur jus.","Faites cuire la poitrine de porc en dés dans son propre gras, à couvert quarante minutes puis à découvert jusqu'à ce qu'elle croustille.","Préparez le pico de gallo à la dernière minute et salez-le seulement au moment de servir — salé à l'avance, il rend son eau.","Montez le bol dans cet ordre : riz au fond, haricots avec un peu de jus, chicharrón brûlant, pico de gallo, avocat.","L'ordre compte : le chicharrón posé sous les haricots ramollit en deux minutes. Servez avec des tortillas frites."],
     en:["Cook the red beans until tender but whole, and keep them in a little of their liquid.","Cook the diced pork belly in its own fat, covered for forty minutes then uncovered until it crisps.","Make the pico de gallo at the last minute and salt it only as you serve — salted ahead, it weeps.","Build the bowl in this order: rice at the bottom, beans with a little liquid, scalding chicharrón, pico de gallo, avocado.","The order matters: chicharrón laid under the beans goes soft in two minutes. Serve with fried tortillas."]} },

{ id:'tamal-tico', c:'na', lat:9.864, lon:-83.919, base:10, prep:240, cook:180, diff:3, tags:['festive','slow','pork'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ead4',style:'other',food:['#e8c46a','#8f5a3a','#7fae5a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Tamal tico',en:'Tamal tico'},
  p:{fr:'Cartago, Costa Rica',en:'Cartago, Costa Rica'},
  d:{fr:"Le tamal de Noël costaricien, à la masa de maïs et pomme de terre, garni de porc et de légumes. Ils se cuisent par paires liées ensemble, appelées piñas : on ne les compte jamais à l'unité, toujours par deux.",
     en:"The Costa Rican Christmas tamal, of corn and potato masa, filled with pork and vegetables. They are cooked in pairs tied together, called piñas: they are never counted singly, always by twos."},
  i:[['corn_masa',1.2,'kg'],['potato',600,'g'],['lard',300,'g'],['pork_shoulder',1,'kg'],['carrot',3,'pc'],['green_beans',200,'g'],['peas',200,'g'],['bell_pepper',2,'pc'],['long_grain_rice',200,'g'],['raisins',80,'g'],['banana_leaf',30,'pc'],['annatto',15,'g'],['pork_broth',1,'l'],['salt',null,'']],
  s:{fr:["Faites cuire le porc en bouillon avec les aromates, désossez-le et gardez le bouillon pour la masa.","Écrasez les pommes de terre bouillies et mêlez-les à la masa : c'est ce qui donne au tamal tico sa texture plus douce que celle de ses voisins.","Détendez au saindoux fondu et au bouillon chaud, en battant, jusqu'à ce que la pâte tombe de la cuillère en ruban.","Coupez les feuilles en rectangles, passez-les à la flamme et étalez la pâte en couche fine — un tamal tico est plat, pas dodu.","Garnissez, pliez, liez les paquets deux par deux et cuisez trois heures dans l'eau bouillante."],
     en:["Cook the pork in broth with aromatics, bone it and keep the broth for the masa.","Mash the boiled potatoes and mix them into the masa: that is what gives the tamal tico its softer texture than its neighbours'.","Loosen with melted lard and hot broth, beating, until the dough falls from the spoon in a ribbon.","Cut the leaves into rectangles, pass them through a flame and spread the dough thinly — a tamal tico is flat, not plump.","Fill, fold, tie the parcels in pairs and boil three hours."]} },

{ id:'patacones', c:'na', lat:9.991, lon:-83.036, base:6, prep:30, cook:25, diff:1, tags:['street','fry','veg'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Patacones',en:'Patacones'},
  p:{fr:'Limón, Costa Rica',en:'Limón, Costa Rica'},
  d:{fr:"Des rondelles de banane plantain verte frites deux fois et aplaties entre les deux bains. L'écrasement à mi-cuisson n'est pas cosmétique : il augmente la surface exposée, et c'est ce qui rend le patacón croustillant au lieu de farineux.",
     en:"Slices of green plantain fried twice and flattened between the two baths. The flattening midway is not cosmetic: it increases the exposed surface, and that is what makes a patacón crisp rather than floury."},
  i:[['plantain',6,'pc'],['frying_oil',1,'l'],['garlic',6,'clove'],['coarse_salt',20,'g'],['water',500,'ml'],['lime',2,'pc'],['refried_beans',300,'g']],
  s:{fr:["Employez des plantains franchement verts : dès qu'ils jaunissent, le sucre caramélise et ils brunissent avant d'être cuits.","Pelez-les en incisant la peau dans la longueur, jamais comme une banane — la peau verte ne se détache pas.","Coupez des rondelles de deux centimètres et frites-les à 160 °C, cinq minutes, jusqu'à ce qu'elles soient tendres mais pâles.","Égouttez, aplatissez chacune à un demi-centimètre, puis trempez-les brièvement dans de l'eau salée à l'ail.","Ce bain d'eau salée fait éclater l'huile mais donne le croustillant. Seconde friture à 190 °C, deux minutes."],
     en:["Use frankly green plantains: as soon as they yellow, the sugar caramelises and they brown before they cook.","Peel them by scoring the skin lengthways, never like a banana — green skin will not come away.","Cut two-centimetre slices and fry at 160°C for five minutes, until tender but pale.","Drain, flatten each to half a centimetre, then dip them briefly in salted garlic water.","That salt-water dip makes the oil spit but gives the crispness. Second fry at 190°C for two minutes."]} },

{ id:'chorreadas', c:'na', lat:9.870, lon:-83.925, base:6, prep:30, cook:25, diff:1, tags:['breakfast','veg','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e8c46a','#f2dfa8','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chorreadas',en:'Chorreadas'},
  p:{fr:'Cartago, Costa Rica',en:'Cartago, Costa Rica'},
  d:{fr:"Des crêpes épaisses de maïs frais broyé, servies avec de la crème aigre. Le nom vient de chorrear, couler : la pâte est si liquide qu'elle s'étale d'elle-même sur la plaque, et l'on ne l'aide jamais avec une spatule.",
     en:"Thick pancakes of ground fresh corn, served with sour cream. The name comes from chorrear, to pour: the batter is so loose it spreads by itself on the griddle, and is never helped along with a spatula."},
  i:[['sweetcorn',8,'pc'],['sugar',60,'g'],['butter',60,'g'],['sour_cream',300,'ml'],['queso_fresco',200,'g'],['whole_milk',100,'ml'],['salt',null,'']],
  s:{fr:["Broyez les grains frais sans eau, ou avec une cuillerée de lait au plus si le maïs est déjà mûr et sec.","Passez au tamis grossier pour retenir les plus grosses peaux, mais gardez du grain : une pâte lisse donne une crêpe caoutchouteuse.","Salez, sucrez légèrement et laissez reposer dix minutes que l'amidon s'hydrate.","Versez une louche sur une plaque beurrée à feu moyen et laissez la pâte s'étaler seule, sans y toucher.","Cinq minutes par face, jusqu'à ce que les bords dorent. Servez avec crème aigre et fromage frais."],
     en:["Grind the fresh kernels without water, or with a spoonful of milk at most if the corn is already mature and dry.","Sieve coarsely to hold back the largest skins, but keep some grain: a smooth batter gives a rubbery pancake.","Salt, sweeten lightly and rest ten minutes for the starch to hydrate.","Pour a ladleful onto a buttered griddle over medium heat and let the batter spread by itself, untouched.","Five minutes a side, until the edges brown. Serve with sour cream and fresh cheese."]} },

{ id:'arroz-con-leche-tico', c:'na', lat:9.925, lon:-84.086, base:6, prep:20, cook:60, diff:1, tags:['sweet','comfort','slow'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#f0e8d0','#e8dcb8','#c9754a'],garnish:'#c9754a'},
  n:{fr:'Arroz con leche',en:'Arroz con leche'},
  p:{fr:'San José, Costa Rica',en:'San José, Costa Rica'},
  d:{fr:"Un riz au lait à la cannelle et au zeste de citron, servi tiède. Il est arrivé d'Espagne avec les Maures avant elle ; la version costaricienne se distingue par le lait concentré, qui remplace une partie du lait frais et donne une texture plus dense.",
     en:"A rice pudding with cinnamon and lemon zest, served warm. It came from Spain, and to Spain from the Moors; the Costa Rican version is marked by condensed milk, which replaces part of the fresh milk and gives a denser texture."},
  i:[['short_grain_rice',250,'g'],['whole_milk',1.2,'l'],['condensed_milk',300,'g'],['cinnamon_stick',3,'pc'],['lemon',1,'pc'],['sugar',100,'g'],['raisins',80,'g'],['salt',null,'']],
  s:{fr:["Faites d'abord cuire le riz à l'eau avec la cannelle et le zeste, quinze minutes, jusqu'à ce qu'il ait absorbé toute l'eau.","Cuire directement dans le lait allonge la cuisson de moitié : le lait ralentit l'hydratation de l'amidon.","Ajoutez ensuite le lait chaud et laissez mijoter quarante minutes en remuant régulièrement.","Ajoutez le lait concentré et le sucre dans les dix dernières minutes seulement — le sucre trop tôt durcit le grain.","Retirez du feu quand il paraît encore trop liquide : il épaissit beaucoup en refroidissant."],
     en:["Cook the rice first in water with the cinnamon and zest, fifteen minutes, until all the water is absorbed.","Cooking straight in milk lengthens it by half: milk slows the starch's hydration.","Then add hot milk and simmer forty minutes, stirring regularly.","Add the condensed milk and sugar in the last ten minutes only — sugar too early hardens the grain.","Take it off the heat while it still looks too loose: it thickens a great deal as it cools."]} },

{ id:'hojaldres-panamenas', c:'na', lat:8.984, lon:-79.518, base:8, prep:90, cook:20, diff:2, tags:['bread','fry','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Hojaldres',en:'Hojaldres'},
  p:{fr:'Panama, Panama',en:'Panama City, Panama'},
  d:{fr:"Des galettes de pâte frites, gonflées et feuilletées, servies au petit-déjeuner. Malgré leur nom, il n'y a aucun feuilletage au beurre : le feuilleté vient de l'étirement de la pâte à la main, jusqu'à la transparence.",
     en:"Fried dough cakes, puffed and flaky, served at breakfast. Despite the name there is no butter lamination: the flakiness comes from stretching the dough by hand until it is transparent."},
  i:[['flour',600,'g'],['baking_powder',15,'g'],['sugar',40,'g'],['shortening',100,'g'],['water',300,'ml'],['frying_oil',1.5,'l'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte souple et laissez-la reposer une heure sous un linge, le temps que le gluten se détende.","Divisez en boules, huilez-les généreusement et laissez reposer encore trente minutes : l'huile empêche la pâte de sécher et facilite l'étirement.","Étirez chaque boule à la main, en la faisant tourner, jusqu'à ce qu'elle devienne translucide au centre.","C'est cet étirement qui crée les couches, et il ne se remplace pas par un rouleau à pâtisserie.","Frites à 180 °C, une minute par face. La galette gonfle en cloques et se déchire en feuillets sous les doigts."],
     en:["Knead a soft dough and rest it an hour under a cloth, so the gluten relaxes.","Divide into balls, oil them generously and rest another thirty minutes: the oil keeps the dough from drying and helps the stretching.","Stretch each ball by hand, turning it, until it becomes translucent at the centre.","That stretching is what creates the layers, and a rolling pin will not replace it.","Fry at 180°C, one minute a side. The cake blisters and tears into leaves under the fingers."]} },

{ id:'tamal-de-olla', c:'na', lat:8.990, lon:-79.525, base:10, prep:120, cook:90, diff:2, tags:['poultry','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'cake',food:['#e8c46a','#c9302a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Tamal de olla',en:'Tamal de olla'},
  p:{fr:'Panama, Panama',en:'Panama City, Panama'},
  d:{fr:"Un tamal cuit en plat plutôt qu'en paquets, monté en couches comme un gratin. C'est la version pressée du tamal panaméen : même pâte, même garniture, mais deux heures gagnées sur le pliage des feuilles.",
     en:"A tamal baked in a dish rather than in parcels, layered like a gratin. It is the hurried version of the Panamanian tamal: same dough, same filling, but two hours saved on folding leaves."},
  i:[['corn_masa',1,'kg'],['lard',250,'g'],['chicken',1.2,'kg'],['ripe_tomato',500,'g'],['bell_pepper',2,'pc'],['onion',3,'pc'],['annatto',20,'g'],['olives',150,'g'],['raisins',80,'g'],['capers',60,'g'],['chicken_broth',1,'l'],['banana_leaf',6,'pc'],['garlic',8,'clove'],['salt',null,'']],
  s:{fr:["Pochez le poulet, effilochez-le et faites-le mijoter dans un sofrito de tomate, poivron et roucou.","Faites cuire la masa dans le bouillon avec le saindoux, en remuant sans arrêt trente minutes, jusqu'à ce qu'elle se décolle du fond.","Cette cuisson préalable est indispensable : une masa crue étalée en plat cuit inégalement et reste crue au centre.","Tapissez le plat de feuilles de bananier, étalez la moitié de la masa, le poulet, puis le reste de la masa.","Cuisez 45 minutes à 180 °C. Laissez reposer vingt minutes avant de découper, sinon les couches glissent."],
     en:["Poach the chicken, shred it and simmer it in a sofrito of tomato, pepper and annatto.","Cook the masa in the broth with the lard, stirring without pause for thirty minutes, until it pulls from the base.","This pre-cooking is essential: raw masa spread in a dish bakes unevenly and stays raw at the centre.","Line the dish with banana leaves, spread half the masa, the chicken, then the rest of the masa.","Bake 45 minutes at 180°C. Rest twenty minutes before cutting, or the layers slide."]} },

{ id:'carimanolas', c:'na', lat:8.978, lon:-79.530, base:8, prep:90, cook:25, diff:2, tags:['street','fry','beef'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#8f4a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Carimañolas',en:'Carimañolas'},
  p:{fr:'Panama, Panama',en:'Panama City, Panama'},
  d:{fr:"Des croquettes fuselées de manioc farcies de viande hachée, frites. La forme allongée aux deux bouts pointus n'est pas décorative : elle permet de manger la croquette debout sans qu'elle se casse, et elle est identique de Panama à Carthagène.",
     en:"Spindle-shaped cassava croquettes filled with minced meat, fried. The elongated shape with two pointed ends is not decorative: it lets you eat the croquette standing without it breaking, and it is identical from Panama to Cartagena."},
  i:[['cassava',1.2,'kg'],['ground_beef',400,'g'],['onion',2,'pc'],['ripe_tomato',300,'g'],['bell_pepper',1,'pc'],['garlic',6,'clove'],['egg',2,'pc'],['cumin',8,'g'],['frying_oil',1.5,'l'],['queso_fresco',150,'g'],['salt',null,'']],
  s:{fr:["Faites bouillir le manioc jusqu'à ce qu'il se défasse, retirez le fil ligneux et écrasez-le encore brûlant.","Écrasé froid, il devient granuleux et la pâte se fend au façonnage — c'est l'erreur qui gâche le plus de carimañolas.","Travaillez la purée à la main jusqu'à ce qu'elle devienne homogène et légèrement collante, sans farine.","Faites revenir la viande jusqu'à ce qu'elle soit sèche, et laissez-la refroidir avant de garnir.","Formez des fuseaux autour de la farce, en effilant les deux bouts, et frites à 180 °C, quatre minutes."],
     en:["Boil the cassava until it falls apart, remove the woody thread and mash it while still scalding.","Mashed cold it turns grainy and the dough cracks when shaped — the mistake that ruins the most carimañolas.","Work the mash by hand until it turns smooth and slightly tacky, with no flour.","Fry the meat until dry, and cool it before filling.","Form spindles around the filling, tapering both ends, and fry at 180°C for four minutes."]} },

{ id:'saus-panameno', c:'na', lat:9.359, lon:-79.900, base:6, prep:120, cook:180, diff:2, tags:['pork','fresh','slow'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'salad',food:['#f4f0e6','#f0e8d0','#7fae5a','#e07a6a'],garnish:'#7fae6a'},
  n:{fr:'Saus',en:'Saus'},
  p:{fr:'Colón, Panama',en:'Colón, Panama'},
  d:{fr:"Des pieds de porc pochés puis marinés au citron vert, au concombre et au piment, servis froids. Le plat vient des Antillais anglophones venus creuser le canal ; son nom est une déformation de souse, la même préparation en Jamaïque.",
     en:"Pig's trotters poached then marinated in lime, cucumber and chilli, served cold. The dish came with the English-speaking West Indians who dug the canal; its name is a corruption of souse, the same preparation in Jamaica."},
  i:[['pork_trotters',1.5,'kg'],['lime',8,'pc'],['cucumber',2,'pc'],['onion',3,'pc'],['scotch_bonnet',2,'pc'],['cilantro',1,'bunch'],['white_wine_vinegar',150,'ml'],['garlic',8,'clove'],['oregano',5,'g'],['salt',null,'']],
  s:{fr:["Grattez et flambez les pieds pour retirer les soies restantes, puis rincez-les longuement.","Pochez-les trois heures avec l'ail et l'origan, jusqu'à ce que la chair se détache de l'os sans effort.","Désossez-les tièdes en gardant la couenne, et coupez tout en morceaux de la taille d'une bouchée.","Mélangez immédiatement au citron vert, au vinaigre et aux légumes crus, pendant que la viande est encore tiède.","C'est en refroidissant dans la marinade que la gélatine se fige et enrobe le tout. Réfrigérez six heures avant de servir."],
     en:["Scrape and singe the trotters to remove remaining bristles, then rinse them at length.","Poach them three hours with garlic and oregano, until the flesh leaves the bone without effort.","Bone them warm, keeping the rind, and cut everything into bite-sized pieces.","Mix immediately with lime, vinegar and raw vegetables, while the meat is still warm.","It is by cooling in the marinade that the gelatine sets and coats everything. Chill six hours before serving."]} },

{ id:'pesada-de-nance', c:'na', lat:7.962, lon:-80.429, base:6, prep:40, cook:40, diff:1, tags:['sweet','fruit','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#e8a032','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Pesada de nance',en:'Pesada de nance'},
  p:{fr:'Azuero, Panama',en:'Azuero, Panama'},
  d:{fr:"Une crème épaisse de nance, petit fruit jaune du Panama, liée à la maïzena. Le nance a une odeur forte et fromagère qui déroute au premier abord ; cuit et sucré, il devient un dessert que la péninsule d'Azuero considère comme le sien.",
     en:"A thick cream of nance, a small yellow Panamanian fruit, bound with cornflour. Nance has a strong, cheesy smell that disconcerts at first; cooked and sweetened, it becomes a dessert the Azuero peninsula counts as its own."},
  i:[['nance',800,'g'],['sugar',250,'g'],['cornstarch',60,'g'],['cinnamon_stick',2,'pc'],['clove',6,'pc'],['water',800,'ml'],['salt',null,'']],
  s:{fr:["Faites bouillir les nances entiers vingt minutes avec la cannelle et le girofle, jusqu'à ce qu'ils s'ouvrent.","Passez-les au tamis en pressant, et jetez les noyaux et les peaux — ils sont amers et gâchent la texture.","Délayez la maïzena dans un peu d'eau froide avant de l'incorporer, jamais directement dans le chaud.","Faites épaissir à feu doux en remuant sans arrêt, dix minutes, jusqu'à ce que la crème nappe la cuillère.","Versez dans des coupes et laissez prendre au frais. Se mange froid, avec un biscuit sec."],
     en:["Boil the whole nances twenty minutes with the cinnamon and cloves, until they split.","Push them through a sieve, pressing, and discard the stones and skins — they are bitter and spoil the texture.","Slake the cornflour in a little cold water before adding it, never straight into the hot.","Thicken over low heat, stirring without pause, ten minutes, until the cream coats the spoon.","Pour into bowls and set in the cold. Eaten cold, with a dry biscuit."]} }
];
